INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X12','soc',3,'u2',ARRAY['SO3-2-u2-C4']::text[],'세시 음식과 세시 풍속에 담긴 바람(건강·복·풍년)을 잘못 안다','무엇을 바랐을까요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
