INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X22','soc',3,'u2',ARRAY['SO3-2-u2-C8']::text[],'교통수단은 사람만 옮긴다고, 또는 한 가지 까닭으로만 이용한다고 여긴다','필요에 따라 다양하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
