INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X32','soc',3,'u2',ARRAY['SO3-2-u2-C12','SO3-2-u2-C14']::text[],'교통을 한쪽으로만 본다(편리하니 문제가 없다, 또는 문제가 있으니 교통수단을 없애자)','편리해졌지만 문제도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
