INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X40','soc',3,'u2',ARRAY['SO3-2-u2-C18']::text[],'전화기가 변해 온 차례나 그때의 생활 모습을 바꾸어 안다','초기 → 유선 → 휴대 → 오늘날') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
