INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_basic#3','soc',3,2,'u2','L01','g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',1,'ox','auto','세시 풍속도 풍습이에요.',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"ox","stem":"세시 풍속도 풍습이에요.","answer":"O","reason_options":[{"t":"세시 풍속도 옛날부터 되풀이되어 전해 오는 생활 모습이기 때문에","correct":true},{"t":"세시 풍속은 풍습과 아무 관계가 없기 때문에","mis":"SO3-2-u2-X01"}],"mis":"SO3-2-u2-X01","explanation":["동그라미 판을 떠올려요.","작은 동그라미가 안에 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_basic#4','soc',3,2,'u2','L01','g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',1,'mc','auto','설날, 정월 대보름, 단오, 추석처럼 해마다 일정하게 지켜 즐기는 날을 무엇이라고 하나요?',ARRAY['SO3-2-u2-X03']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"mc","stem":"설날, 정월 대보름, 단오, 추석처럼 해마다 일정하게 지켜 즐기는 날을 무엇이라고 하나요?","options":[{"t":"명절","correct":true},{"t":"생일","mis":"SO3-2-u2-X03"},{"t":"주말","mis":"SO3-2-u2-X03"},{"t":"방학","mis":"SO3-2-u2-X03"}],"explanation":["해마다 지켜요.","즐기는 날이에요.","명절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_basic#5','soc',3,2,'u2','L01','g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',2,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"차례","r":"명절날 아침에 조상들에게 지내는 제사"},{"l":"덕담","r":"남이 잘되기를 바라며 나누는 좋은 말"},{"l":"설빔","r":"설을 맞아 새로 마련한 옷이나 신발"}],"mis":"SO3-2-u2-X03","explanation":["제사는 차례예요.","좋은 말은 덕담이에요.","새 옷은 설빔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_basic#6','soc',3,2,'u2','L01','g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',2,'mc','auto','생일날 미역국, 돌잔치, 전통 결혼식, 김장은 모두 무엇에 해당하나요?',ARRAY['SO3-2-u2-X03','SO3-2-u2-X02','SO3-2-u2-X01']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"mc","stem":"생일날 미역국, 돌잔치, 전통 결혼식, 김장은 모두 무엇에 해당하나요?","options":[{"t":"일상생활 속 풍습","correct":true},{"t":"명절날 하는 차례","mis":"SO3-2-u2-X03"},{"t":"오늘 새로 생긴 일","mis":"SO3-2-u2-X02"},{"t":"학교에서 배우는 과목","mis":"SO3-2-u2-X01"}],"explanation":["생활 속에서 해요.","옛날부터 이어졌어요.","일상생활 속 풍습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_basic#7','soc',3,2,'u2','L01','g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',2,'blank','auto','명절이나 절기마다 하는 일, 먹는 음식, 입는 옷, 즐기는 (    ) 등 고유의 세시 풍속이 전해져요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X03']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"blank","stem":"명절이나 절기마다 하는 일, 먹는 음식, 입는 옷, 즐기는 (    ) 등 고유의 세시 풍속이 전해져요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"놀이","correct":true},{"t":"숙제","mis":"SO3-2-u2-X03"},{"t":"시험","mis":"SO3-2-u2-X03"},{"t":"청소","mis":"SO3-2-u2-X03"}],"explanation":["윷놀이를 떠올려요.","즐기는 것이에요.","놀이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_basic#8','soc',3,2,'u2','L01','g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',2,'mc','auto','카드 가운데 작은 동그라미(세시 풍속)에 놓을 카드는 무엇인가요?',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"mc","stem":"카드 가운데 작은 동그라미(세시 풍속)에 놓을 카드는 무엇인가요?","options":[{"t":"㉦ 설날에 어른들께 세배해요","correct":true},{"t":"㉠ 생일날 미역국을 먹어요","mis":"SO3-2-u2-X01"},{"t":"㉣ 첫 번째 생일에 돌잔치를 해요","mis":"SO3-2-u2-X01"},{"t":"㉥ 이사할 때 이웃들에게 떡을 돌려요","mis":"SO3-2-u2-X01"}],"explanation":["해마다 정해진 때예요.","명절에 하는 일이에요.","세배예요."],"asset":{"type":"passage","lines":["㉠ 생일날 미역국을 먹어요.","㉡ 명절날 아침에 차례를 지내요.","㉢ 추석에 송편을 먹어요.","㉣ 첫 번째 생일에 돌잔치를 해요.","㉤ 연날리기 같은 전통 놀이를 즐겨요.","㉥ 이사할 때 이웃들에게 떡을 돌려요.","㉦ 설날에 어른들께 세배해요.","㉧ 전통 결혼식을 해요."],"title":"풍습 카드 여덟 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_basic#9','soc',3,2,'u2','L01','g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',2,'ox','auto','풍습은 오늘날에는 볼 수 없는 옛날 사람들만의 생활 모습이에요.',ARRAY['SO3-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"ox","stem":"풍습은 오늘날에는 볼 수 없는 옛날 사람들만의 생활 모습이에요.","answer":"X","reason_options":[{"t":"생일 미역국, 명절 차례처럼 오늘날에도 이어지는 풍습이 많기 때문에","correct":true},{"t":"풍습은 옛날에만 있던 일이기 때문에","mis":"SO3-2-u2-X02"}],"mis":"SO3-2-u2-X02","explanation":["오늘 우리 생활을 봐요.","미역국을 먹어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_basic#10','soc',3,2,'u2','L01','g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',3,'error','auto','동그라미 판을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"error","stem":"동그라미 판을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「세시 풍속은 풍습이 아니라서 따로 떨어져 있어.」","correct":true,"mis_target":"SO3-2-u2-X01"},{"t":"친구 가 — 「작은 동그라미가 큰 동그라미 안에 있어.」","mis":"SO3-2-u2-X01"},{"t":"친구 나 — 「세시 풍속도 풍습의 하나야.」","mis":"SO3-2-u2-X01"}],"explanation":["두 동그라미를 봐요.","안에 들어 있어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["큰 동그라미 — 풍습","작은 동그라미 — 세시 풍속","작은 동그라미는 큰 동그라미 안에 들어 있어요."],"title":"동그라미 판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
