INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_challenge#2','soc',3,2,'u2','L01','g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',2,'ox','auto','추석에 가족과 송편을 만들어 먹는 것은 세시 풍속이에요.',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"ox","stem":"추석에 가족과 송편을 만들어 먹는 것은 세시 풍속이에요.","answer":"O","reason_options":[{"t":"추석이라는 해마다 일정한 때에 되풀이하는 풍습이기 때문에","correct":true},{"t":"송편은 아무 때나 먹는 음식이기 때문에","mis":"SO3-2-u2-X01"}],"mis":"SO3-2-u2-X01","explanation":["추석은 해마다 와요.","그때 되풀이해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_challenge#3','soc',3,2,'u2','L01','g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',3,'mc','auto','카드 여덟 장을 모두 놓았을 때 큰 동그라미(풍습) 안에 들어 있는 카드는 모두 몇 장인가요?',ARRAY['SO3-2-u2-X01','SO3-2-u2-X02']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"mc","stem":"카드 여덟 장을 모두 놓았을 때 큰 동그라미(풍습) 안에 들어 있는 카드는 모두 몇 장인가요?","options":[{"t":"8장","correct":true},{"t":"4장","mis":"SO3-2-u2-X01"},{"t":"0장","mis":"SO3-2-u2-X02"},{"t":"1장","mis":"SO3-2-u2-X01"}],"explanation":["작은 동그라미도 큰 동그라미 안이에요.","모든 카드가 풍습이에요.","8장이에요."],"asset":{"type":"passage","lines":["㉠ 생일날 미역국을 먹어요.","㉡ 명절날 아침에 차례를 지내요.","㉢ 추석에 송편을 먹어요.","㉣ 첫 번째 생일에 돌잔치를 해요.","㉤ 연날리기 같은 전통 놀이를 즐겨요.","㉥ 이사할 때 이웃들에게 떡을 돌려요.","㉦ 설날에 어른들께 세배해요.","㉧ 전통 결혼식을 해요."],"title":"풍습 카드 여덟 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_challenge#4','soc',3,2,'u2','L01','g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',3,'mc','auto','카드에서 작은 동그라미에 놓을 카드끼리 바르게 모은 것은 무엇인가요?',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"mc","stem":"카드에서 작은 동그라미에 놓을 카드끼리 바르게 모은 것은 무엇인가요?","options":[{"t":"㉡, ㉢, ㉤, ㉦","correct":true},{"t":"㉠, ㉣, ㉥, ㉧","mis":"SO3-2-u2-X01"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"SO3-2-u2-X01"},{"t":"㉥, ㉦, ㉧, ㉠","mis":"SO3-2-u2-X01"}],"explanation":["명절에 하는 일을 찾아요.","차례·송편·전통 놀이·세배예요.","㉡, ㉢, ㉤, ㉦이에요."],"asset":{"type":"passage","lines":["㉠ 생일날 미역국을 먹어요.","㉡ 명절날 아침에 차례를 지내요.","㉢ 추석에 송편을 먹어요.","㉣ 첫 번째 생일에 돌잔치를 해요.","㉤ 연날리기 같은 전통 놀이를 즐겨요.","㉥ 이사할 때 이웃들에게 떡을 돌려요.","㉦ 설날에 어른들께 세배해요.","㉧ 전통 결혼식을 해요."],"title":"풍습 카드 여덟 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_challenge#5','soc',3,2,'u2','L01','g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',3,'ox','auto','세시 풍속이 아닌 풍습도 있어요.',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"ox","stem":"세시 풍속이 아닌 풍습도 있어요.","answer":"O","reason_options":[{"t":"생일 미역국이나 돌잔치처럼 해마다 같은 때에 모두 함께 하는 일이 아닌 풍습도 있기 때문에","correct":true},{"t":"풍습은 모두 세시 풍속이기 때문에","mis":"SO3-2-u2-X01"}],"mis":"SO3-2-u2-X01","explanation":["큰 동그라미에만 있는 카드가 있어요.","미역국, 돌잔치예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_challenge#6','soc',3,2,'u2','L01','g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',3,'error','auto','풍습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"error","stem":"풍습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「돌잔치는 해마다 설날에 하는 세시 풍속이야.」","correct":true,"mis_target":"SO3-2-u2-X01"},{"t":"친구 가 — 「돌잔치는 첫 번째 생일에 하는 풍습이야.」","mis":"SO3-2-u2-X01"},{"t":"친구 다 — 「세배는 설날에 하는 세시 풍속이야.」","mis":"SO3-2-u2-X01"}],"explanation":["돌잔치는 언제 해요?","첫 생일이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_challenge#7','soc',3,2,'u2','L01','g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',3,'mc','auto','「풍습」과 「세시 풍속」의 관계를 바르게 나타낸 것은 무엇인가요?',ARRAY['SO3-2-u2-X01','SO3-2-u2-X02']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"mc","stem":"「풍습」과 「세시 풍속」의 관계를 바르게 나타낸 것은 무엇인가요?","options":[{"t":"세시 풍속은 풍습의 하나예요","correct":true},{"t":"풍습은 모두 세시 풍속이에요","mis":"SO3-2-u2-X01"},{"t":"둘은 서로 관계가 없어요","mis":"SO3-2-u2-X01"},{"t":"세시 풍속은 오늘날 새로 생긴 일이에요","mis":"SO3-2-u2-X02"}],"explanation":["큰 것과 작은 것이에요.","작은 것이 안에 있어요.","세시 풍속은 풍습의 하나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_challenge#8','soc',3,2,'u2','L01','g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',4,'mc','auto','「풍습과 세시 풍속」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X02','SO3-2-u2-X01']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C1","difficulty":4,"kind":"mc","stem":"「풍습과 세시 풍속」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"옛날부터 되풀이되어 전해 오는 생활 모습을 풍습이라 하고, 그 가운데 해마다 일정한 때에 되풀이하는 것을 세시 풍속이라고 해요","correct":true},{"t":"풍습은 옛날에만 있었고 세시 풍속은 오늘날에만 있어요","mis":"SO3-2-u2-X02"},{"t":"세시 풍속은 풍습과 상관없는 놀이예요","mis":"SO3-2-u2-X01"},{"t":"풍습은 모두 명절에만 하는 일이에요","mis":"SO3-2-u2-X01"}],"explanation":["풍습의 뜻이에요.","세시 풍속의 뜻이에요.","둘의 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_challenge#9','soc',3,2,'u2','L01','g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',4,'mc','auto','「태어난 지 100일이 되는 날 잔치를 하고 떡을 나누어 먹는 일」을 동그라미 판에 놓는다면 어디에 놓아야 하나요?',ARRAY['SO3-2-u2-X01','SO3-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C1","difficulty":4,"kind":"mc","stem":"「태어난 지 100일이 되는 날 잔치를 하고 떡을 나누어 먹는 일」을 동그라미 판에 놓는다면 어디에 놓아야 하나요?","options":[{"t":"큰 동그라미(풍습) 안, 작은 동그라미 밖","correct":true},{"t":"작은 동그라미(세시 풍속) 안","mis":"SO3-2-u2-X01"},{"t":"두 동그라미 밖","mis":"SO3-2-u2-X02"},{"t":"어디에도 놓을 수 없어요","mis":"SO3-2-u2-X02"}],"explanation":["옛날부터 전해 와요.","명절은 아니에요.","풍습에만 놓아요."],"asset":{"type":"passage","lines":["큰 동그라미 — 풍습","작은 동그라미 — 세시 풍속","작은 동그라미는 큰 동그라미 안에 들어 있어요."],"title":"동그라미 판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L01_challenge#10','soc',3,2,'u2','L01','g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',4,'essay','teacher','내가 알고 있거나 경험해 본 풍습을 하나 쓰고, 그것이 세시 풍속인지 아닌지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C1","difficulty":4,"kind":"essay","stem":"내가 알고 있거나 경험해 본 풍습을 하나 쓰고, 그것이 세시 풍속인지 아닌지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 설날에 어른들께 세배하는 풍습을 해 봤어요. 설날이라는 해마다 일정한 때에 되풀이하니까 세시 풍속이에요. / 예: 생일날 미역국을 먹어요. 옛날부터 전해 오는 풍습이지만 명절이나 절기에 하는 일이 아니니 세시 풍속은 아니에요.","scoring_points":["풍습을 하나 썼는가","세시 풍속인지 판단했는가","「해마다 일정한 때」를 까닭으로 썼는가"]},"explanation":["풍습을 떠올려요.","해마다 같은 때인지 봐요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_basic#1','soc',3,2,'u2','L02','g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',1,'mc','auto','한꺼번에 많은 일손이 필요한 농사일을 함께하려고 마을에 만든 공동 조직은 무엇인가요?',ARRAY['SO3-2-u2-X04','SO3-2-u2-X05']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"mc","stem":"한꺼번에 많은 일손이 필요한 농사일을 함께하려고 마을에 만든 공동 조직은 무엇인가요?","options":[{"t":"두레","correct":true},{"t":"품앗이","mis":"SO3-2-u2-X04"},{"t":"돌잡이","mis":"SO3-2-u2-X05"},{"t":"관례","mis":"SO3-2-u2-X05"}],"explanation":["농사일이에요.","마을 조직이에요.","두레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_basic#2','soc',3,2,'u2','L02','g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',1,'sa','auto','김장, 지붕 얹기처럼 일손이 모자란 일을 서로 돌아가면서 돕는 풍습을 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"sa","stem":"김장, 지붕 얹기처럼 일손이 모자란 일을 서로 돌아가면서 돕는 풍습을 네 글자로 쓰세요.","answer":["품앗이"],"explanation":["돌아가며 도와요.","품◯◯예요.","품앗이예요."],"mis":"SO3-2-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_basic#3','soc',3,2,'u2','L02','g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',1,'ox','auto','옛날에 아기가 태어나면 대문에 금줄을 쳤어요.',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"ox","stem":"옛날에 아기가 태어나면 대문에 금줄을 쳤어요.","answer":"O","reason_options":[{"t":"산모와 아기의 건강을 바라며 나쁜 기운을 막으려고 했기 때문에","correct":true},{"t":"아기가 태어난 것을 숨기려고 했기 때문에","mis":"SO3-2-u2-X05"}],"mis":"SO3-2-u2-X05","explanation":["출생 풍습이에요.","나쁜 기운을 막아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_basic#4','soc',3,2,'u2','L02','g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',1,'mc','auto','남자와 여자가 결혼하기 전에 하던 성인식은 무엇인가요?',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"mc","stem":"남자와 여자가 결혼하기 전에 하던 성인식은 무엇인가요?","options":[{"t":"관례","correct":true},{"t":"회갑","mis":"SO3-2-u2-X05"},{"t":"혼례","mis":"SO3-2-u2-X05"},{"t":"장례","mis":"SO3-2-u2-X05"}],"explanation":["결혼하기 전이에요.","어른이 돼요.","관례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_basic#5','soc',3,2,'u2','L02','g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',2,'match','auto','일생 동안의 풍습과 담긴 바람을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"match","stem":"일생 동안의 풍습과 담긴 바람을 알맞게 이으세요.","pairs":[{"l":"금줄 치기","r":"산모와 아기가 건강하기를 바라요"},{"l":"돌잔치","r":"아기가 아프지 않고 오래 살기를 바라요"},{"l":"회갑","r":"부모님이 건강하게 오래 사시기를 빌어요"},{"l":"장례","r":"남은 가족을 위로해요"}],"mis":"SO3-2-u2-X05","explanation":["출생은 건강이에요.","첫돌은 오래 살기예요.","회갑과 장례도 이어요."],"asset":{"type":"passage","lines":["㉠ 대문에 21일 동안 금줄을 쳤어요.","㉡ 태어난 지 100일에 잔치를 했어요.","㉢ 첫돌에 음식을 먹고 돌잡이를 했어요.","㉣ 결혼하기 전에 성인식을 했어요.","㉤ 부부가 되는 예식을 올렸어요.","㉥ 60년 동안 건강하게 사신 것을 축하했어요.","㉦ 남은 가족을 위로하는 예식을 치렀어요."],"title":"옛날 일생 동안의 풍습 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_basic#6','soc',3,2,'u2','L02','g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',2,'mc','auto','돌잔치에서 쌀, 붓, 활, 돈, 실 등을 펼쳐 놓고 아이에게 골라잡게 하는 일은 무엇인가요?',ARRAY['SO3-2-u2-X05','SO3-2-u2-X04']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"mc","stem":"돌잔치에서 쌀, 붓, 활, 돈, 실 등을 펼쳐 놓고 아이에게 골라잡게 하는 일은 무엇인가요?","options":[{"t":"돌잡이","correct":true},{"t":"금줄","mis":"SO3-2-u2-X05"},{"t":"회갑","mis":"SO3-2-u2-X05"},{"t":"두레","mis":"SO3-2-u2-X04"}],"explanation":["첫돌 잔치예요.","골라잡아요.","돌잡이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_basic#7','soc',3,2,'u2','L02','g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',2,'blank','auto','회갑을 (    )이라고 부르기도 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"blank","stem":"회갑을 (    )이라고 부르기도 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"환갑","correct":true},{"t":"백일","mis":"SO3-2-u2-X05"},{"t":"첫돌","mis":"SO3-2-u2-X05"},{"t":"관례","mis":"SO3-2-u2-X05"}],"explanation":["60년을 축하해요.","환◯이에요.","환갑이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_basic#8','soc',3,2,'u2','L02','g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',2,'mc','auto','자료에서 일손이 「한꺼번에 많이」 필요해 두레로 함께한 일은 어느 것인가요?',ARRAY['SO3-2-u2-X04','SO3-2-u2-X06']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"mc","stem":"자료에서 일손이 「한꺼번에 많이」 필요해 두레로 함께한 일은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"SO3-2-u2-X04"},{"t":"가와 나 모두 품앗이","mis":"SO3-2-u2-X04"},{"t":"둘 다 혼자서 한 일","mis":"SO3-2-u2-X06"}],"explanation":["모내기와 벼 베기예요.","마을 조직이 해요.","가예요."],"asset":{"type":"passage","lines":["가. 모내기·김매기·벼 베기처럼 일손이 한꺼번에 많이 필요한 일","나. 김장·지붕 얹기처럼 한 집에서 하기에 일손이 모자란 일"],"title":"옛날 사람들이 함께한 일 두 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_basic#9','soc',3,2,'u2','L02','g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',2,'ox','auto','옛날 사람들은 중요한 일이 있어도 이웃과 마음을 나누지 않았어요.',ARRAY['SO3-2-u2-X06']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"ox","stem":"옛날 사람들은 중요한 일이 있어도 이웃과 마음을 나누지 않았어요.","answer":"X","reason_options":[{"t":"출생, 혼례, 장례처럼 중요한 일이 있을 때 서로 축하하거나 위로하며 마음을 나눴기 때문에","correct":true},{"t":"옛날 사람들은 모든 일을 혼자서만 했기 때문에","mis":"SO3-2-u2-X06"}],"mis":"SO3-2-u2-X06","explanation":["축하하고 위로했어요.","마음을 나눴어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_basic#10','soc',3,2,'u2','L02','g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',3,'mc','auto','자료의 풍습을 일생의 차례대로 놓았을 때 ㉣(성인식) 바로 다음에 오는 것은 무엇인가요?',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"mc","stem":"자료의 풍습을 일생의 차례대로 놓았을 때 ㉣(성인식) 바로 다음에 오는 것은 무엇인가요?","options":[{"t":"㉤ 부부가 되는 예식","correct":true},{"t":"㉢ 돌잡이","mis":"SO3-2-u2-X05"},{"t":"㉥ 60년 축하","mis":"SO3-2-u2-X05"},{"t":"㉠ 금줄","mis":"SO3-2-u2-X05"}],"explanation":["관례 다음이에요.","결혼해요.","혼례예요."],"asset":{"type":"passage","lines":["㉠ 대문에 21일 동안 금줄을 쳤어요.","㉡ 태어난 지 100일에 잔치를 했어요.","㉢ 첫돌에 음식을 먹고 돌잡이를 했어요.","㉣ 결혼하기 전에 성인식을 했어요.","㉤ 부부가 되는 예식을 올렸어요.","㉥ 60년 동안 건강하게 사신 것을 축하했어요.","㉦ 남은 가족을 위로하는 예식을 치렀어요."],"title":"옛날 일생 동안의 풍습 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_challenge#1','soc',3,2,'u2','L02','g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',2,'sa','auto','옛날에 아기가 태어나면 대문에 금줄을 며칠 동안 쳤나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"sa","stem":"옛날에 아기가 태어나면 대문에 금줄을 며칠 동안 쳤나요? 숫자로 쓰세요.","answer":["21","21일"],"explanation":["세 이레예요.","2◯일이에요.","21일이에요."],"mis":"SO3-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_challenge#2','soc',3,2,'u2','L02','g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',2,'ox','auto','오늘날에도 아이를 같이 돌보거나 반찬을 같이 나누는 품앗이가 있어요.',ARRAY['SO3-2-u2-X02']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"ox","stem":"오늘날에도 아이를 같이 돌보거나 반찬을 같이 나누는 품앗이가 있어요.","answer":"O","reason_options":[{"t":"품앗이 풍습이 모습을 바꾸어 오늘날에도 이어지고 있기 때문에","correct":true},{"t":"품앗이는 옛날에 모두 사라졌기 때문에","mis":"SO3-2-u2-X02"}],"mis":"SO3-2-u2-X02","explanation":["육아 품앗이가 있어요.","모습이 바뀌었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_challenge#3','soc',3,2,'u2','L02','g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',3,'mc','auto','옛날 사람들이 농사일이나 집안일을 함께한 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X04','SO3-2-u2-X06']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"mc","stem":"옛날 사람들이 농사일이나 집안일을 함께한 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"도움이 필요할 때 힘을 합해 도와주는 정이 있었기 때문이에요","correct":true},{"t":"혼자 일하면 안 된다는 규칙이 있었기 때문이에요","mis":"SO3-2-u2-X04"},{"t":"이웃과 서로 겨루려고 했기 때문이에요","mis":"SO3-2-u2-X06"},{"t":"이웃에게 돈을 받으려고 했기 때문이에요","mis":"SO3-2-u2-X06"}],"explanation":["두레와 품앗이예요.","서로 도왔어요.","정이 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_challenge#4','soc',3,2,'u2','L02','g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',3,'mc','auto','자료의 풍습 가운데 기쁨을 축하하는 것이 아니라 슬픔을 위로하는 풍습은 무엇인가요?',ARRAY['SO3-2-u2-X06']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"mc","stem":"자료의 풍습 가운데 기쁨을 축하하는 것이 아니라 슬픔을 위로하는 풍습은 무엇인가요?","options":[{"t":"㉦","correct":true},{"t":"㉡","mis":"SO3-2-u2-X06"},{"t":"㉤","mis":"SO3-2-u2-X06"},{"t":"㉥","mis":"SO3-2-u2-X06"}],"explanation":["축하와 위로가 있어요.","남은 가족을 위로해요.","장례예요."],"asset":{"type":"passage","lines":["㉠ 대문에 21일 동안 금줄을 쳤어요.","㉡ 태어난 지 100일에 잔치를 했어요.","㉢ 첫돌에 음식을 먹고 돌잡이를 했어요.","㉣ 결혼하기 전에 성인식을 했어요.","㉤ 부부가 되는 예식을 올렸어요.","㉥ 60년 동안 건강하게 사신 것을 축하했어요.","㉦ 남은 가족을 위로하는 예식을 치렀어요."],"title":"옛날 일생 동안의 풍습 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_challenge#5','soc',3,2,'u2','L02','g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',3,'error','auto','두레와 품앗이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X04']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"error","stem":"두레와 품앗이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「품앗이는 마을 사람 모두가 만든 농사 조직이야.」","correct":true,"mis_target":"SO3-2-u2-X04"},{"t":"친구 나 — 「두레는 일손이 많이 필요한 농사일을 함께하려고 만들었어.」","mis":"SO3-2-u2-X04"},{"t":"친구 다 — 「품앗이는 서로 돌아가며 도왔어.」","mis":"SO3-2-u2-X04"}],"explanation":["조직은 두레예요.","품앗이는 돌아가며 도와요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_challenge#6','soc',3,2,'u2','L02','g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',3,'mc','auto','관례를 마친 사람을 옛날 사람들은 어떻게 대했나요?',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"mc","stem":"관례를 마친 사람을 옛날 사람들은 어떻게 대했나요?","options":[{"t":"어른으로 대해 줬어요","correct":true},{"t":"아기로 대해 줬어요","mis":"SO3-2-u2-X05"},{"t":"마을을 떠나게 했어요","mis":"SO3-2-u2-X05"},{"t":"회갑 잔치를 열어 줬어요","mis":"SO3-2-u2-X05"}],"explanation":["성인식이에요.","어른이 됐어요.","어른으로 대했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_challenge#7','soc',3,2,'u2','L02','g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',3,'ox','auto','회갑은 아기가 태어나자마자 하는 풍습이에요.',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"ox","stem":"회갑은 아기가 태어나자마자 하는 풍습이에요.","answer":"X","reason_options":[{"t":"회갑은 부모님이 60년 동안 건강하게 사신 것을 축하하는 풍습이기 때문에","correct":true},{"t":"회갑은 출생을 알리는 풍습이기 때문에","mis":"SO3-2-u2-X05"}],"mis":"SO3-2-u2-X05","explanation":["60년이에요.","부모님 잔치예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_challenge#8','soc',3,2,'u2','L02','g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',4,'mc','auto','옛날의 일상생활 속 풍습을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X06','SO3-2-u2-X05']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C2","difficulty":4,"kind":"mc","stem":"옛날의 일상생활 속 풍습을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"기쁨과 슬픔을 나누며 서로 돕고 사는 조상들의 마음이 담겨 있어요","correct":true},{"t":"옛날 사람들은 힘든 일을 언제나 혼자서만 했어요","mis":"SO3-2-u2-X06"},{"t":"풍습을 보아도 옛날 사람들의 생각은 알 수 없어요","mis":"SO3-2-u2-X06"},{"t":"일생 동안의 풍습은 모두 슬픔을 나누는 일이에요","mis":"SO3-2-u2-X05"}],"explanation":["축하하고 위로했어요.","서로 도왔어요.","마음이 담겨 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_challenge#9','soc',3,2,'u2','L02','g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',4,'mc','auto','옛날 마을 사람들이 이웃의 혼례에도 장례에도 함께한 모습에서 알 수 있는 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X06']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C2","difficulty":4,"kind":"mc","stem":"옛날 마을 사람들이 이웃의 혼례에도 장례에도 함께한 모습에서 알 수 있는 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"기쁜 일은 함께 축하하고 슬픈 일은 함께 위로하며 서로 도우려는 생각","correct":true},{"t":"남의 집 일에는 끼지 않으려는 생각","mis":"SO3-2-u2-X06"},{"t":"기쁜 일에만 모이고 슬픈 일은 모른 척하려는 생각","mis":"SO3-2-u2-X06"},{"t":"잔치 음식을 얻어먹으려는 생각","mis":"SO3-2-u2-X06"}],"explanation":["혼례는 기쁜 일이에요.","장례는 슬픈 일이에요.","함께 나눴어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L02_challenge#10','soc',3,2,'u2','L02','g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',4,'essay','teacher','자료의 일생 동안의 풍습 가운데 하나를 골라 어떤 풍습인지 쓰고, 그 풍습에 담긴 옛날 사람들의 마음을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C2","difficulty":4,"kind":"essay","stem":"자료의 일생 동안의 풍습 가운데 하나를 골라 어떤 풍습인지 쓰고, 그 풍습에 담긴 옛날 사람들의 마음을 쓰세요.","answer_guide":{"answer":"예: ㉢ 첫돌에는 아기가 아프지 않고 오래 살기를 바라는 음식을 먹고 돌잡이를 했어요. 아기가 건강하게 자라기를 바라는 가족과 이웃의 마음이 담겨 있어요.","scoring_points":["풍습 하나를 골랐는가","어떤 풍습인지 썼는가","담긴 마음을 썼는가"]},"explanation":["하나를 골라요.","무엇을 했는지 써요.","마음을 써요."],"asset":{"type":"passage","lines":["㉠ 대문에 21일 동안 금줄을 쳤어요.","㉡ 태어난 지 100일에 잔치를 했어요.","㉢ 첫돌에 음식을 먹고 돌잡이를 했어요.","㉣ 결혼하기 전에 성인식을 했어요.","㉤ 부부가 되는 예식을 올렸어요.","㉥ 60년 동안 건강하게 사신 것을 축하했어요.","㉦ 남은 가족을 위로하는 예식을 치렀어요."],"title":"옛날 일생 동안의 풍습 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_basic#1','soc',3,2,'u2','L03','g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',1,'mc','auto','옛날에 결혼하는 날 신랑이 신부 집으로 가지고 간 것은 무엇인가요?',ARRAY['SO3-2-u2-X07']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C3","difficulty":1,"kind":"mc","stem":"옛날에 결혼하는 날 신랑이 신부 집으로 가지고 간 것은 무엇인가요?","options":[{"t":"나무로 만든 기러기","correct":true},{"t":"반지","mis":"SO3-2-u2-X07"},{"t":"대추와 밤","mis":"SO3-2-u2-X07"},{"t":"케이크","mis":"SO3-2-u2-X07"}],"explanation":["한번 짝을 맺으면 평생 함께해요.","새 모양이에요.","나무 기러기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_basic#2','soc',3,2,'u2','L03','g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',1,'sa','auto','오늘날 결혼식에서 신랑 신부가 평생 함께할 것을 약속하며 주고받는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C3","difficulty":1,"kind":"sa","stem":"오늘날 결혼식에서 신랑 신부가 평생 함께할 것을 약속하며 주고받는 것을 두 글자로 쓰세요.","answer":["반지"],"explanation":["손가락에 끼워요.","반◯예요.","반지예요."],"mis":"SO3-2-u2-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_basic#3','soc',3,2,'u2','L03','g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',1,'ox','auto','오늘날에도 아기가 태어난 지 100일이 되는 날에 백일잔치를 해요.',ARRAY['SO3-2-u2-X09']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C3","difficulty":1,"kind":"ox","stem":"오늘날에도 아기가 태어난 지 100일이 되는 날에 백일잔치를 해요.","answer":"O","reason_options":[{"t":"백일잔치는 변화하면서 이어져 내려오는 풍습이기 때문에","correct":true},{"t":"백일잔치는 이미 사라진 풍습이기 때문에","mis":"SO3-2-u2-X09"}],"mis":"SO3-2-u2-X09","explanation":["오늘날에도 해요.","이어져 내려와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_basic#4','soc',3,2,'u2','L03','g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',1,'mc','auto','오늘날 아기가 태어났을 때 거의 볼 수 없어 사라져 가는 풍습은 무엇인가요?',ARRAY['SO3-2-u2-X09']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C3","difficulty":1,"kind":"mc","stem":"오늘날 아기가 태어났을 때 거의 볼 수 없어 사라져 가는 풍습은 무엇인가요?","options":[{"t":"금줄 치기","correct":true},{"t":"백일잔치","mis":"SO3-2-u2-X09"},{"t":"돌잔치","mis":"SO3-2-u2-X09"},{"t":"생일 미역국","mis":"SO3-2-u2-X09"}],"explanation":["대문에 쳤어요.","오늘날 거의 없어요.","금줄 치기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_basic#5','soc',3,2,'u2','L03','g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',2,'mc','auto','폐백은 무엇인가요?',ARRAY['SO3-2-u2-X07','SO3-2-u2-X05']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"mc","stem":"폐백은 무엇인가요?","options":[{"t":"신부가 처음으로 신랑 부모나 신랑 쪽 어른들을 뵐 때 큰절을 올리는 것","correct":true},{"t":"결혼식이 끝나고 떠나는 여행","mis":"SO3-2-u2-X07"},{"t":"평생 함께할 것을 약속하며 주고받는 물건","mis":"SO3-2-u2-X07"},{"t":"아기가 태어나면 대문에 치는 줄","mis":"SO3-2-u2-X05"}],"explanation":["어른들께 드리는 인사예요.","큰절이에요.","폐백이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_basic#6','soc',3,2,'u2','L03','g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',2,'match','auto','결혼 풍습을 옛날과 오늘날로 견주어 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"match","stem":"결혼 풍습을 옛날과 오늘날로 견주어 알맞게 이으세요.","pairs":[{"l":"신부 집","r":"결혼식장·공원"},{"l":"혼례복(한복)","r":"턱시도·웨딩드레스"},{"l":"나무 기러기","r":"반지"},{"l":"신부 집에서 며칠","r":"신혼여행"}],"mis":"SO3-2-u2-X07","explanation":["장소를 견줘요.","옷과 물건을 견줘요.","마친 뒤를 견줘요."],"asset":{"type":"passage","lines":["장소 — 옛날: 신부 집 / 오늘날: 결혼식장, 공원 등","입는 옷 — 옛날: 혼례복(한복) / 오늘날: 턱시도, 웨딩드레스","주고받는 물건 — 옛날: 나무 기러기 / 오늘날: 반지","마친 뒤 — 옛날: 신부 집에서 며칠 뒤 신랑 집 / 오늘날: 신혼여행","함께하는 마음 — 부부가 된 것을 알리고 미래를 축복해요"],"title":"옛날과 오늘날의 결혼 풍습 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_basic#7','soc',3,2,'u2','L03','g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',2,'mc','auto','비교표에서 옛날과 오늘날이 「같은」 줄은 무엇인가요?',ARRAY['SO3-2-u2-X08']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"mc","stem":"비교표에서 옛날과 오늘날이 「같은」 줄은 무엇인가요?","options":[{"t":"부부가 된 것을 알리고 미래를 축복하는 마음","correct":true},{"t":"결혼하는 장소","mis":"SO3-2-u2-X08"},{"t":"입는 옷","mis":"SO3-2-u2-X08"},{"t":"주고받는 물건","mis":"SO3-2-u2-X08"}],"explanation":["달라진 줄이 많아요.","같은 줄은 하나예요.","축복하는 마음이에요."],"asset":{"type":"passage","lines":["장소 — 옛날: 신부 집 / 오늘날: 결혼식장, 공원 등","입는 옷 — 옛날: 혼례복(한복) / 오늘날: 턱시도, 웨딩드레스","주고받는 물건 — 옛날: 나무 기러기 / 오늘날: 반지","마친 뒤 — 옛날: 신부 집에서 며칠 뒤 신랑 집 / 오늘날: 신혼여행","함께하는 마음 — 부부가 된 것을 알리고 미래를 축복해요"],"title":"옛날과 오늘날의 결혼 풍습 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_basic#8','soc',3,2,'u2','L03','g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',2,'ox','auto','옛날 풍습은 오늘날 모두 사라졌어요.',ARRAY['SO3-2-u2-X02']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"ox","stem":"옛날 풍습은 오늘날 모두 사라졌어요.","answer":"X","reason_options":[{"t":"백일잔치, 회갑잔치, 폐백처럼 변화하면서 이어져 내려오는 풍습이 있기 때문에","correct":true},{"t":"풍습은 시간이 지나면 모두 없어지기 때문에","mis":"SO3-2-u2-X02"}],"mis":"SO3-2-u2-X02","explanation":["이어지는 것이 있어요.","백일잔치예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_basic#9','soc',3,2,'u2','L03','g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',2,'blank','auto','옛날과 오늘날의 풍습을 (    )하면 사람들의 생활이 무엇이 달라졌는지 알 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X08']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"blank","stem":"옛날과 오늘날의 풍습을 (    )하면 사람들의 생활이 무엇이 달라졌는지 알 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"비교","correct":true},{"t":"외우기","mis":"SO3-2-u2-X08"},{"t":"숨기기","mis":"SO3-2-u2-X08"},{"t":"따라 하기","mis":"SO3-2-u2-X08"}],"explanation":["견주어 봐요.","비◯예요.","비교예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_basic#10','soc',3,2,'u2','L03','g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',3,'error','auto','결혼 풍습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X07']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"error","stem":"결혼 풍습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「옛날에는 혼례가 끝나면 곧바로 신혼여행을 떠났대.」","correct":true,"mis_target":"SO3-2-u2-X07"},{"t":"친구 나 — 「옛날에는 신부 집에서 혼례를 치렀대.」","mis":"SO3-2-u2-X07"},{"t":"친구 다 — 「오늘날에는 반지를 주고받아.」","mis":"SO3-2-u2-X07"}],"explanation":["옛날 혼례 뒤예요.","신부 집에서 며칠 지냈어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["장소 — 옛날: 신부 집 / 오늘날: 결혼식장, 공원 등","입는 옷 — 옛날: 혼례복(한복) / 오늘날: 턱시도, 웨딩드레스","주고받는 물건 — 옛날: 나무 기러기 / 오늘날: 반지","마친 뒤 — 옛날: 신부 집에서 며칠 뒤 신랑 집 / 오늘날: 신혼여행","함께하는 마음 — 부부가 된 것을 알리고 미래를 축복해요"],"title":"옛날과 오늘날의 결혼 풍습 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_challenge#1','soc',3,2,'u2','L03','g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',2,'sa','auto','폐백 때 어른들이 신랑 신부에게 자식을 많이 낳고 부자가 되라는 뜻으로 던져 주는 것 가운데 하나를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"sa","stem":"폐백 때 어른들이 신랑 신부에게 자식을 많이 낳고 부자가 되라는 뜻으로 던져 주는 것 가운데 하나를 쓰세요.","answer":["대추","밤"],"explanation":["열매예요.","대추나 밤이에요.","대추, 밤이에요."],"mis":"SO3-2-u2-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_challenge#2','soc',3,2,'u2','L03','g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',2,'ox','auto','장례 풍습도 달라지고 있어요.',ARRAY['SO3-2-u2-X09']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"ox","stem":"장례 풍습도 달라지고 있어요.","answer":"O","reason_options":[{"t":"땅에 묻는 매장이 줄고 수목장이나 해양장으로 치르는 경우가 많아지고 있기 때문에","correct":true},{"t":"장례 풍습은 옛날과 하나도 다르지 않기 때문에","mis":"SO3-2-u2-X09"}],"mis":"SO3-2-u2-X09","explanation":["장례도 변해요.","매장이 줄었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_challenge#3','soc',3,2,'u2','L03','g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',3,'mc','auto','옛날 신랑이 나무 기러기를 준 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X07','SO3-2-u2-X05']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"mc","stem":"옛날 신랑이 나무 기러기를 준 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"기러기처럼 오래도록 행복하게 함께 살자는 뜻이에요","correct":true},{"t":"기러기처럼 멀리 떠나자는 뜻이에요","mis":"SO3-2-u2-X07"},{"t":"부자가 되라는 뜻이에요","mis":"SO3-2-u2-X07"},{"t":"나쁜 기운을 막으려는 뜻이에요","mis":"SO3-2-u2-X05"}],"explanation":["기러기는 짝을 지어요.","평생 함께해요.","함께 살자는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_challenge#4','soc',3,2,'u2','L03','g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',3,'mc','auto','자료의 두 묶음 가운데 「나」 묶음을 가리키는 말로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X09','SO3-2-u2-X02','SO3-2-u2-X01']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"mc","stem":"자료의 두 묶음 가운데 「나」 묶음을 가리키는 말로 알맞은 것은 무엇인가요?","options":[{"t":"사라져 가는 풍습","correct":true},{"t":"변화하면서 이어져 내려오는 풍습","mis":"SO3-2-u2-X09"},{"t":"오늘날 새로 생긴 풍습","mis":"SO3-2-u2-X02"},{"t":"세시 풍속","mis":"SO3-2-u2-X01"}],"explanation":["금줄 치기와 관례예요.","오늘날 거의 안 해요.","사라져 가는 풍습이에요."],"asset":{"type":"passage","lines":["가. 백일잔치 · 회갑잔치 · 폐백","나. 금줄 치기 · 관례"],"title":"풍습의 변화 두 묶음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_challenge#5','soc',3,2,'u2','L03','g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',3,'error','auto','풍습의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X09']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"error","stem":"풍습의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「관례는 오늘날에도 그대로 이어져 내려오는 풍습이야.」","correct":true,"mis_target":"SO3-2-u2-X09"},{"t":"친구 가 — 「백일잔치는 오늘날에도 해.」","mis":"SO3-2-u2-X09"},{"t":"친구 나 — 「금줄 치기는 사라져 가는 풍습이야.」","mis":"SO3-2-u2-X09"}],"explanation":["관례를 봐요.","사라져 가요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["가. 백일잔치 · 회갑잔치 · 폐백","나. 금줄 치기 · 관례"],"title":"풍습의 변화 두 묶음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_challenge#6','soc',3,2,'u2','L03','g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',3,'ox','auto','옛날과 오늘날의 결혼 풍습은 모든 것이 똑같아요.',ARRAY['SO3-2-u2-X08']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"ox","stem":"옛날과 오늘날의 결혼 풍습은 모든 것이 똑같아요.","answer":"X","reason_options":[{"t":"장소, 옷, 주고받는 물건은 달라졌고 축복하는 마음만 같기 때문에","correct":true},{"t":"결혼 풍습은 한번 정해지면 바뀌지 않기 때문에","mis":"SO3-2-u2-X08"}],"mis":"SO3-2-u2-X08","explanation":["비교표를 봐요.","달라진 줄이 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["장소 — 옛날: 신부 집 / 오늘날: 결혼식장, 공원 등","입는 옷 — 옛날: 혼례복(한복) / 오늘날: 턱시도, 웨딩드레스","주고받는 물건 — 옛날: 나무 기러기 / 오늘날: 반지","마친 뒤 — 옛날: 신부 집에서 며칠 뒤 신랑 집 / 오늘날: 신혼여행","함께하는 마음 — 부부가 된 것을 알리고 미래를 축복해요"],"title":"옛날과 오늘날의 결혼 풍습 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_challenge#7','soc',3,2,'u2','L03','g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',3,'mc','auto','풍습은 한번 정해지면 조금도 바뀌지 않는다는 생각을 바로잡을 수 있는 예로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X02']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"mc","stem":"풍습은 한번 정해지면 조금도 바뀌지 않는다는 생각을 바로잡을 수 있는 예로 가장 알맞은 것은 무엇인가요?","options":[{"t":"결혼할 때 주고받는 물건이 나무 기러기에서 반지로 바뀌었어요","correct":true},{"t":"생일날 미역국을 먹어요","mis":"SO3-2-u2-X02"},{"t":"명절날 아침에 차례를 지내요","mis":"SO3-2-u2-X02"},{"t":"설날에 세배해요","mis":"SO3-2-u2-X02"}],"explanation":["바뀐 예를 찾아요.","물건이 바뀌었어요.","기러기에서 반지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_challenge#8','soc',3,2,'u2','L03','g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',4,'mc','auto','옛날과 오늘날의 결혼 풍습을 견주어 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X08']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C3","difficulty":4,"kind":"mc","stem":"옛날과 오늘날의 결혼 풍습을 견주어 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"모습은 달라졌지만 부부가 된 것을 알리고 축복해 주는 마음은 변함없어요","correct":true},{"t":"모습도 마음도 모두 똑같아요","mis":"SO3-2-u2-X08"},{"t":"모습도 마음도 모두 달라졌어요","mis":"SO3-2-u2-X08"},{"t":"오늘날 결혼식에는 축복해 주는 가족과 친척이 없어요","mis":"SO3-2-u2-X08"}],"explanation":["모습은 달라졌어요.","마음은 같아요.","변함없는 것이 있어요."],"asset":{"type":"passage","lines":["장소 — 옛날: 신부 집 / 오늘날: 결혼식장, 공원 등","입는 옷 — 옛날: 혼례복(한복) / 오늘날: 턱시도, 웨딩드레스","주고받는 물건 — 옛날: 나무 기러기 / 오늘날: 반지","마친 뒤 — 옛날: 신부 집에서 며칠 뒤 신랑 집 / 오늘날: 신혼여행","함께하는 마음 — 부부가 된 것을 알리고 미래를 축복해요"],"title":"옛날과 오늘날의 결혼 풍습 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_challenge#9','soc',3,2,'u2','L03','g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',4,'mc','auto','아기가 태어났을 때의 풍습을 옛날과 오늘날로 견주어 조사하려고 해요. 비교표에 넣을 내용으로 가장 알맞지 않은 것은 무엇인가요?',ARRAY['SO3-2-u2-X09']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C3","difficulty":4,"kind":"mc","stem":"아기가 태어났을 때의 풍습을 옛날과 오늘날로 견주어 조사하려고 해요. 비교표에 넣을 내용으로 가장 알맞지 않은 것은 무엇인가요?","options":[{"t":"추석에 하는 강강술래","correct":true},{"t":"옛날 대문의 금줄","mis":"SO3-2-u2-X09"},{"t":"오늘날의 백일잔치","mis":"SO3-2-u2-X09"},{"t":"100일 떡 나누기","mis":"SO3-2-u2-X09"}],"explanation":["출생과 관련 있어야 해요.","강강술래는 추석이에요.","알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L03_challenge#10','soc',3,2,'u2','L03','g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',4,'essay','teacher','자료의 두 묶음에서 풍습을 하나씩 골라, 하나는 오늘날 어떻게 이어지는지, 다른 하나는 왜 사라져 간다고 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C3","difficulty":4,"kind":"essay","stem":"자료의 두 묶음에서 풍습을 하나씩 골라, 하나는 오늘날 어떻게 이어지는지, 다른 하나는 왜 사라져 간다고 하는지 쓰세요.","answer_guide":{"answer":"예: 백일잔치는 오늘날에도 아기가 태어난 지 100일이 되는 날에 잔치를 하며 이어져요. 금줄 치기는 오늘날 아기가 태어나도 금줄을 치는 집을 거의 볼 수 없어서 사라져 가는 풍습이라고 해요.","scoring_points":["이어지는 풍습을 바르게 골랐는가","사라져 가는 풍습을 바르게 골랐는가","오늘날의 모습을 근거로 썼는가"]},"explanation":["가에서 하나예요.","나에서 하나예요.","오늘날 모습을 써요."],"asset":{"type":"passage","lines":["가. 백일잔치 · 회갑잔치 · 폐백","나. 금줄 치기 · 관례"],"title":"풍습의 변화 두 묶음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_basic#1','soc',3,2,'u2','L04','g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',1,'mc','auto','한 해가 시작되는 음력 1월 1일은 어떤 명절인가요?',ARRAY['SO3-2-u2-X10']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"mc","stem":"한 해가 시작되는 음력 1월 1일은 어떤 명절인가요?","options":[{"t":"설날","correct":true},{"t":"추석","mis":"SO3-2-u2-X10"},{"t":"단오","mis":"SO3-2-u2-X10"},{"t":"동지","mis":"SO3-2-u2-X10"}],"explanation":["한 해의 시작이에요.","떡국을 먹어요.","설날이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_basic#2','soc',3,2,'u2','L04','g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',1,'sa','auto','추석에 그해 새로 난 쌀로 빚어 먹은 떡을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"sa","stem":"추석에 그해 새로 난 쌀로 빚어 먹은 떡을 두 글자로 쓰세요.","answer":["송편"],"explanation":["반달 모양이에요.","송◯이에요.","송편이에요."],"mis":"SO3-2-u2-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_basic#3','soc',3,2,'u2','L04','g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',1,'ox','auto','동지에는 팥죽을 먹었어요.',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"ox","stem":"동지에는 팥죽을 먹었어요.","answer":"O","reason_options":[{"t":"붉은팥이 나쁜 기운을 쫓는다고 여겼기 때문에","correct":true},{"t":"팥죽은 단오에 먹는 음식이기 때문에","mis":"SO3-2-u2-X11"}],"mis":"SO3-2-u2-X11","explanation":["밤이 가장 긴 날이에요.","붉은팥이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_basic#4','soc',3,2,'u2','L04','g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',1,'mc','auto','정월 대보름에 먹은 음식은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"mc","stem":"정월 대보름에 먹은 음식은 무엇인가요?","options":[{"t":"오곡밥과 나물","correct":true},{"t":"송편","mis":"SO3-2-u2-X11"},{"t":"팥죽","mis":"SO3-2-u2-X11"},{"t":"수리취떡","mis":"SO3-2-u2-X11"}],"explanation":["다섯 가지 곡식이에요.","보름에 먹어요.","오곡밥과 나물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_basic#5','soc',3,2,'u2','L04','g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',2,'match','auto','명절과 그날 즐긴 놀이를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"match","stem":"명절과 그날 즐긴 놀이를 알맞게 이으세요.","pairs":[{"l":"설날","r":"널뛰기"},{"l":"정월 대보름","r":"쥐불놀이"},{"l":"단오","r":"그네뛰기"},{"l":"추석","r":"강강술래"}],"mis":"SO3-2-u2-X11","explanation":["설날은 널뛰기예요.","대보름은 쥐불놀이예요.","단오와 추석도 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_basic#6','soc',3,2,'u2','L04','g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',2,'mc','auto','수수께끼 상자의 단서가 가리키는 명절은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"mc","stem":"수수께끼 상자의 단서가 가리키는 명절은 무엇인가요?","options":[{"t":"정월 대보름","correct":true},{"t":"설날","mis":"SO3-2-u2-X11"},{"t":"추석","mis":"SO3-2-u2-X11"},{"t":"동지","mis":"SO3-2-u2-X11"}],"explanation":["달맞이를 해요.","부럼을 깨물어요.","정월 대보름이에요."],"asset":{"type":"passage","lines":["단서 1 — 달맞이를 하며 소원을 빌었어요.","단서 2 — 쥐불놀이와 다리밟기를 했어요.","단서 3 — 부럼을 깨물고 오곡밥과 나물을 먹었어요."],"title":"수수께끼 상자 하나"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_basic#7','soc',3,2,'u2','L04','g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',2,'blank','auto','정월 대보름에는 (    )을 깨물며 이가 튼튼해지고 피부병이 생기지 않기를 빌었어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"blank","stem":"정월 대보름에는 (    )을 깨물며 이가 튼튼해지고 피부병이 생기지 않기를 빌었어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"부럼","correct":true},{"t":"송편","mis":"SO3-2-u2-X11"},{"t":"팥죽","mis":"SO3-2-u2-X11"},{"t":"떡국","mis":"SO3-2-u2-X11"}],"explanation":["단단한 열매예요.","밤·호두·땅콩이에요.","부럼이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_basic#8','soc',3,2,'u2','L04','g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',2,'mc','auto','달력 띠에서 ㉰(음력 5월 5일)에 해당하는 명절은 무엇인가요?',ARRAY['SO3-2-u2-X10']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"mc","stem":"달력 띠에서 ㉰(음력 5월 5일)에 해당하는 명절은 무엇인가요?","options":[{"t":"단오","correct":true},{"t":"추석","mis":"SO3-2-u2-X10"},{"t":"설날","mis":"SO3-2-u2-X10"},{"t":"정월 대보름","mis":"SO3-2-u2-X10"}],"explanation":["모내기를 마쳤어요.","잠시 쉬는 날이에요.","단오예요."],"asset":{"type":"passage","lines":["㉮ 음력 1월 1일 — 한 해가 시작되는 날","㉯ 음력 1월 15일 — 새해 처음으로 보름달이 뜨는 날","㉰ 음력 5월 5일 — 모내기를 마치고 잠시 쉬는 날","㉱ 음력 8월 15일 — 곡식과 과일을 거두어들이는 때","㉲ 양력 12월 22일 무렵 — 밤이 가장 길고 낮이 가장 짧은 날"],"title":"다섯 명절 달력 띠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_basic#9','soc',3,2,'u2','L04','g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',2,'ox','auto','다섯 명절은 모두 음력 날짜로 쇠요.',ARRAY['SO3-2-u2-X10']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"ox","stem":"다섯 명절은 모두 음력 날짜로 쇠요.","answer":"X","reason_options":[{"t":"동지는 양력 12월 22일 무렵이기 때문에","correct":true},{"t":"다섯 명절의 날짜는 모두 같은 달이기 때문에","mis":"SO3-2-u2-X10"}],"mis":"SO3-2-u2-X10","explanation":["달력 띠를 봐요.","동지는 양력이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉮ 음력 1월 1일 — 한 해가 시작되는 날","㉯ 음력 1월 15일 — 새해 처음으로 보름달이 뜨는 날","㉰ 음력 5월 5일 — 모내기를 마치고 잠시 쉬는 날","㉱ 음력 8월 15일 — 곡식과 과일을 거두어들이는 때","㉲ 양력 12월 22일 무렵 — 밤이 가장 길고 낮이 가장 짧은 날"],"title":"다섯 명절 달력 띠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_basic#10','soc',3,2,'u2','L04','g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',3,'mc','auto','설날에 먹는 떡국의 가래떡 「긴 모양」에 담긴 마음은 무엇인가요?',ARRAY['SO3-2-u2-X12']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"mc","stem":"설날에 먹는 떡국의 가래떡 「긴 모양」에 담긴 마음은 무엇인가요?","options":[{"t":"건강하고 오래 살기를 바라는 마음","correct":true},{"t":"나쁜 기운을 쫓으려는 마음","mis":"SO3-2-u2-X12"},{"t":"풍년을 축하하는 마음","mis":"SO3-2-u2-X12"},{"t":"여름을 시원하게 보내려는 마음","mis":"SO3-2-u2-X12"}],"explanation":["길게 이어져요.","오래 살기예요.","건강하고 오래 살기를 바라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_challenge#1','soc',3,2,'u2','L04','g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',2,'sa','auto','단오에 여름을 시원하게 보내라고 주고받은 물건을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"sa","stem":"단오에 여름을 시원하게 보내라고 주고받은 물건을 두 글자로 쓰세요.","answer":["부채"],"explanation":["바람을 일으켜요.","부◯예요.","부채예요."],"mis":"SO3-2-u2-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_challenge#2','soc',3,2,'u2','L04','g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',2,'ox','auto','추석은 곡식과 과일을 거두어들이는 때로, 풍년을 축하하고 감사하는 마음으로 차례를 지냈어요.',ARRAY['SO3-2-u2-X12']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"ox","stem":"추석은 곡식과 과일을 거두어들이는 때로, 풍년을 축하하고 감사하는 마음으로 차례를 지냈어요.","answer":"O","reason_options":[{"t":"가을에 거둔 곡식과 과일로 조상들에게 감사했기 때문에","correct":true},{"t":"추석은 모내기를 시작하는 봄 명절이기 때문에","mis":"SO3-2-u2-X12"}],"mis":"SO3-2-u2-X12","explanation":["가을이에요.","거두어들여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_challenge#3','soc',3,2,'u2','L04','g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',3,'mc','auto','옛날 사람들이 동지를 「작은 설」이라고 한 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X10','SO3-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"mc","stem":"옛날 사람들이 동지를 「작은 설」이라고 한 까닭은 무엇인가요?","options":[{"t":"동지부터 낮의 길이가 점점 길어져 새해의 시작이라고 생각했기 때문이에요","correct":true},{"t":"보름달이 가장 크게 뜨는 날이어서","mis":"SO3-2-u2-X10"},{"t":"떡국을 먹는 날이어서","mis":"SO3-2-u2-X11"},{"t":"모내기를 시작하는 날이어서","mis":"SO3-2-u2-X10"}],"explanation":["밤이 가장 길어요.","다음 날부터 낮이 길어져요.","새해의 시작이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_challenge#4','soc',3,2,'u2','L04','g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',3,'mc','auto','옛날 사람들이 추석에 한 일이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"mc","stem":"옛날 사람들이 추석에 한 일이 아닌 것은 무엇인가요?","options":[{"t":"팥죽을 대문에 뿌리기","correct":true},{"t":"성묘하기","mis":"SO3-2-u2-X11"},{"t":"강강술래 하기","mis":"SO3-2-u2-X11"},{"t":"송편 빚기","mis":"SO3-2-u2-X11"}],"explanation":["추석에 한 일을 떠올려요.","팥죽은 동지예요.","아닌 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_challenge#5','soc',3,2,'u2','L04','g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',3,'error','auto','세시 음식에 담긴 마음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X12']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"error","stem":"세시 음식에 담긴 마음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「송편에는 나쁜 기운을 쫓으려는 마음이 담겨 있어.」","correct":true,"mis_target":"SO3-2-u2-X12"},{"t":"친구 가 — 「떡국의 흰색에는 밝은 한 해가 되기를 바라는 생각이 담겨 있어.」","mis":"SO3-2-u2-X12"},{"t":"친구 다 — 「송편에는 점점 나아지기를 바라는 마음이 담겨 있어.」","mis":"SO3-2-u2-X12"}],"explanation":["나쁜 기운은 팥이에요.","송편은 반달이 보름달로요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_challenge#6','soc',3,2,'u2','L04','g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',3,'mc','auto','모내기를 마치고 더운 여름을 맞기 전에 잠시 쉬며 창포 삶은 물에 머리를 감은 명절은 언제인가요?',ARRAY['SO3-2-u2-X10']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"mc","stem":"모내기를 마치고 더운 여름을 맞기 전에 잠시 쉬며 창포 삶은 물에 머리를 감은 명절은 언제인가요?","options":[{"t":"음력 5월 5일","correct":true},{"t":"음력 1월 1일","mis":"SO3-2-u2-X10"},{"t":"음력 8월 15일","mis":"SO3-2-u2-X10"},{"t":"양력 12월 22일 무렵","mis":"SO3-2-u2-X10"}],"explanation":["단오예요.","여름이 오기 전이에요.","음력 5월 5일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_challenge#7','soc',3,2,'u2','L04','g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',3,'ox','auto','옛날 세시 풍속 가운데 차례 지내기, 윷놀이하기, 떡국 먹기는 오늘날까지 이어져 내려오고 있어요.',ARRAY['SO3-2-u2-X02']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"ox","stem":"옛날 세시 풍속 가운데 차례 지내기, 윷놀이하기, 떡국 먹기는 오늘날까지 이어져 내려오고 있어요.","answer":"O","reason_options":[{"t":"오늘날에도 명절에 차례를 지내고 떡국을 먹고 윷놀이를 하기 때문에","correct":true},{"t":"옛날 세시 풍속은 오늘날 모두 사라졌기 때문에","mis":"SO3-2-u2-X02"}],"mis":"SO3-2-u2-X02","explanation":["요즘 설날을 떠올려요.","떡국을 먹어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_challenge#8','soc',3,2,'u2','L04','g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',4,'mc','auto','다섯 명절의 세시 풍속을 살펴보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X11','SO3-2-u2-X12']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C4","difficulty":4,"kind":"mc","stem":"다섯 명절의 세시 풍속을 살펴보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"명절마다 하는 일, 먹는 음식, 놀이가 다르고 건강과 풍년과 복을 바라는 마음이 담겨 있어요","correct":true},{"t":"다섯 명절에는 모두 같은 음식을 먹어요","mis":"SO3-2-u2-X11"},{"t":"세시 풍속은 명절마다 모두 똑같아요","mis":"SO3-2-u2-X11"},{"t":"세시 풍속에는 옛날 사람들의 생각이 담겨 있지 않아요","mis":"SO3-2-u2-X12"}],"explanation":["명절마다 달라요.","바라는 마음이 있어요.","건강·풍년·복이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_challenge#9','soc',3,2,'u2','L04','g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',4,'mc','auto','어떤 명절에 「새해 달력을 주고받고, 오래 살기를 기원하며 버선을 드렸다」고 해요. 이 명절에 먹은 음식은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C4","difficulty":4,"kind":"mc","stem":"어떤 명절에 「새해 달력을 주고받고, 오래 살기를 기원하며 버선을 드렸다」고 해요. 이 명절에 먹은 음식은 무엇인가요?","options":[{"t":"팥죽","correct":true},{"t":"떡국","mis":"SO3-2-u2-X11"},{"t":"송편","mis":"SO3-2-u2-X11"},{"t":"오곡밥","mis":"SO3-2-u2-X11"}],"explanation":["새해를 맞을 준비예요.","작은 설이에요.","동지의 팥죽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L04_challenge#10','soc',3,2,'u2','L04','g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',4,'essay','teacher','다섯 명절 가운데 하나를 골라 그날 하는 일, 먹는 음식, 놀이를 하나씩 쓰고, 그 속에 담긴 옛날 사람들의 바람을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C4","difficulty":4,"kind":"essay","stem":"다섯 명절 가운데 하나를 골라 그날 하는 일, 먹는 음식, 놀이를 하나씩 쓰고, 그 속에 담긴 옛날 사람들의 바람을 쓰세요.","answer_guide":{"answer":"예: 설날에는 설빔을 입고 어른들께 세배를 드렸어요. 떡국을 먹고 윷놀이를 즐겼어요. 가족과 친척이 모여 서로의 건강과 복을 바라는 마음이 담겨 있어요.","scoring_points":["명절에 맞는 하는 일을 썼는가","음식과 놀이를 썼는가","담긴 바람을 썼는가"]},"explanation":["명절 하나를 골라요.","일·음식·놀이를 써요.","바람을 써요."],"asset":{"type":"passage","lines":["㉮ 음력 1월 1일 — 한 해가 시작되는 날","㉯ 음력 1월 15일 — 새해 처음으로 보름달이 뜨는 날","㉰ 음력 5월 5일 — 모내기를 마치고 잠시 쉬는 날","㉱ 음력 8월 15일 — 곡식과 과일을 거두어들이는 때","㉲ 양력 12월 22일 무렵 — 밤이 가장 길고 낮이 가장 짧은 날"],"title":"다섯 명절 달력 띠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_basic#1','soc',3,2,'u2','L05','g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',1,'mc','auto','옛날 우리 조상들은 주로 어떤 일을 하며 살았나요?',ARRAY['SO3-2-u2-X13']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C5","difficulty":1,"kind":"mc","stem":"옛날 우리 조상들은 주로 어떤 일을 하며 살았나요?","options":[{"t":"농사짓기","correct":true},{"t":"공장에서 물건 만들기","mis":"SO3-2-u2-X13"},{"t":"가게에서 물건 팔기","mis":"SO3-2-u2-X13"},{"t":"영화 만들기","mis":"SO3-2-u2-X13"}],"explanation":["계절의 영향을 받아요.","논밭에서 일해요.","농사짓기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_basic#2','soc',3,2,'u2','L05','g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',1,'sa','auto','오늘날 설날에도 친척들이 모여 먹는, 가래떡으로 만든 음식을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C5","difficulty":1,"kind":"sa","stem":"오늘날 설날에도 친척들이 모여 먹는, 가래떡으로 만든 음식을 두 글자로 쓰세요.","answer":["떡국"],"explanation":["설날 아침이에요.","떡◯이에요.","떡국이에요."],"mis":"SO3-2-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_basic#3','soc',3,2,'u2','L05','g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',1,'ox','auto','옛날에는 농사와 관련 있는 세시 풍속이 계절마다 다양했어요.',ARRAY['SO3-2-u2-X13']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C5","difficulty":1,"kind":"ox","stem":"옛날에는 농사와 관련 있는 세시 풍속이 계절마다 다양했어요.","answer":"O","reason_options":[{"t":"농사는 계절에 따라 해야 하는 일이 정해져 있기 때문에","correct":true},{"t":"옛날 사람들은 농사를 짓지 않았기 때문에","mis":"SO3-2-u2-X13"}],"mis":"SO3-2-u2-X13","explanation":["농사는 계절을 따라요.","세시 풍속도 따라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_basic#4','soc',3,2,'u2','L05','g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',1,'mc','auto','설날 글에서 노란 형광펜(옛날부터 이어져 오는 모습)을 칠할 곳은 어디인가요?',ARRAY['SO3-2-u2-X15']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C5","difficulty":1,"kind":"mc","stem":"설날 글에서 노란 형광펜(옛날부터 이어져 오는 모습)을 칠할 곳은 어디인가요?","options":[{"t":"㉡ 차례를 지낸 뒤 세배를 했어요","correct":true},{"t":"㉣ 케이크를 후식으로 먹었어요","mis":"SO3-2-u2-X15"},{"t":"㉤ 영화관에 가서 영화를 봤어요","mis":"SO3-2-u2-X15"},{"t":"㉥ 해외여행을 떠난대요","mis":"SO3-2-u2-X15"}],"explanation":["옛날에도 했어요.","세배예요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 친척들이 할아버지 댁에 모여 차례를 지냈어요.","㉡ 차례를 지낸 뒤 세배를 했어요.","㉢ 다 함께 떡국을 먹었어요.","㉣ 고모가 사 온 케이크를 후식으로 먹었어요.","㉤ 우리 가족은 영화관에 가서 영화를 봤어요.","㉥ 사촌 동생네 가족은 남은 연휴 동안 해외여행을 떠난대요."],"title":"오늘날 어느 어린이의 설날 글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_basic#5','soc',3,2,'u2','L05','g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',2,'mc','auto','자료에서 새해 첫 보름달을 보며 한 해의 풍년을 기원한 계절은 언제인가요?',ARRAY['SO3-2-u2-X13']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"mc","stem":"자료에서 새해 첫 보름달을 보며 한 해의 풍년을 기원한 계절은 언제인가요?","options":[{"t":"겨울","correct":true},{"t":"여름","mis":"SO3-2-u2-X13"},{"t":"가을","mis":"SO3-2-u2-X13"},{"t":"봄","mis":"SO3-2-u2-X13"}],"explanation":["농사를 시작하기 전이에요.","새해예요.","겨울이에요."],"asset":{"type":"passage","lines":["겨울 — 새해 첫 보름달을 보며 한 해의 풍년을 기원했어요.","가을 — 곡식을 거두고 음식을 만들어 먹으며 수확의 기쁨을 나눴어요."],"title":"옛날 농촌의 계절과 세시 풍속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_basic#6','soc',3,2,'u2','L05','g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',2,'mc','auto','오늘날 농사와 관련 있는 세시 풍속을 즐기는 사람이 줄어든 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X14','SO3-2-u2-X13']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"mc","stem":"오늘날 농사와 관련 있는 세시 풍속을 즐기는 사람이 줄어든 까닭은 무엇인가요?","options":[{"t":"직업이 다양해지면서 농사짓는 사람이 줄어들어서","correct":true},{"t":"명절이 모두 없어져서","mis":"SO3-2-u2-X14"},{"t":"세시 풍속을 즐기면 안 되어서","mis":"SO3-2-u2-X14"},{"t":"날씨가 늘 똑같아져서","mis":"SO3-2-u2-X13"}],"explanation":["오늘날 직업을 봐요.","여러 가지예요.","농사짓는 사람이 줄었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_basic#7','soc',3,2,'u2','L05','g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',2,'blank','auto','오늘날에는 농사와 관련 있는 세시 풍속보다는 큰 (    )을 중심으로 한 세시 풍속이 이어져 오고 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X14']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"blank","stem":"오늘날에는 농사와 관련 있는 세시 풍속보다는 큰 (    )을 중심으로 한 세시 풍속이 이어져 오고 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"명절","correct":true},{"t":"공장","mis":"SO3-2-u2-X14"},{"t":"학교","mis":"SO3-2-u2-X14"},{"t":"가게","mis":"SO3-2-u2-X14"}],"explanation":["설날, 추석이에요.","큰 ◯◯이에요.","명절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_basic#8','soc',3,2,'u2','L05','g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',2,'match','auto','설날 글의 모습을 알맞은 형광펜과 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"match","stem":"설날 글의 모습을 알맞은 형광펜과 이으세요.","pairs":[{"l":"㉢ 떡국 먹기","r":"노란색 — 이어져 오는 모습"},{"l":"㉤ 영화 보기","r":"하늘색 — 달라진 모습"}],"mis":"SO3-2-u2-X15","explanation":["옛날에도 했나요?","떡국은 했어요.","영화는 달라졌어요."],"asset":{"type":"passage","lines":["㉠ 친척들이 할아버지 댁에 모여 차례를 지냈어요.","㉡ 차례를 지낸 뒤 세배를 했어요.","㉢ 다 함께 떡국을 먹었어요.","㉣ 고모가 사 온 케이크를 후식으로 먹었어요.","㉤ 우리 가족은 영화관에 가서 영화를 봤어요.","㉥ 사촌 동생네 가족은 남은 연휴 동안 해외여행을 떠난대요."],"title":"오늘날 어느 어린이의 설날 글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_basic#9','soc',3,2,'u2','L05','g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',2,'ox','auto','오늘날에는 설날에 옛날 세시 풍속을 하나도 하지 않아요.',ARRAY['SO3-2-u2-X15']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"ox","stem":"오늘날에는 설날에 옛날 세시 풍속을 하나도 하지 않아요.","answer":"X","reason_options":[{"t":"차례, 세배, 떡국처럼 이어져 오는 모습이 있기 때문에","correct":true},{"t":"오늘날 설날에는 여행만 가기 때문에","mis":"SO3-2-u2-X15"}],"mis":"SO3-2-u2-X15","explanation":["노란 조각이 있어요.","세배가 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 친척들이 할아버지 댁에 모여 차례를 지냈어요.","㉡ 차례를 지낸 뒤 세배를 했어요.","㉢ 다 함께 떡국을 먹었어요.","㉣ 고모가 사 온 케이크를 후식으로 먹었어요.","㉤ 우리 가족은 영화관에 가서 영화를 봤어요.","㉥ 사촌 동생네 가족은 남은 연휴 동안 해외여행을 떠난대요."],"title":"오늘날 어느 어린이의 설날 글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_basic#10','soc',3,2,'u2','L05','g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',3,'mc','auto','옛날과 오늘날의 세시 풍속이 달라지고 있지만 변함없는 것은 무엇인가요?',ARRAY['SO3-2-u2-X16','SO3-2-u2-X11']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"mc","stem":"옛날과 오늘날의 세시 풍속이 달라지고 있지만 변함없는 것은 무엇인가요?","options":[{"t":"가족이나 이웃과 기쁨을 함께 나누는 것","correct":true},{"t":"농사와 관련 있는 세시 풍속을 모두 즐기는 것","mis":"SO3-2-u2-X16"},{"t":"명절마다 같은 음식을 먹는 것","mis":"SO3-2-u2-X11"},{"t":"계절마다 새 명절을 만드는 것","mis":"SO3-2-u2-X16"}],"explanation":["명절에 모여요.","함께 기뻐해요.","기쁨을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_challenge#1','soc',3,2,'u2','L05','g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',2,'sa','auto','설날 글에서 하늘색 형광펜(옛날과 달라진 모습)을 칠할 곳의 기호를 하나만 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"sa","stem":"설날 글에서 하늘색 형광펜(옛날과 달라진 모습)을 칠할 곳의 기호를 하나만 쓰세요.","answer":["㉣","㉤","㉥"],"explanation":["옛날에 없던 모습이에요.","케이크·영화·여행이에요.","㉣, ㉤, ㉥ 가운데 하나예요."],"asset":{"type":"passage","lines":["㉠ 친척들이 할아버지 댁에 모여 차례를 지냈어요.","㉡ 차례를 지낸 뒤 세배를 했어요.","㉢ 다 함께 떡국을 먹었어요.","㉣ 고모가 사 온 케이크를 후식으로 먹었어요.","㉤ 우리 가족은 영화관에 가서 영화를 봤어요.","㉥ 사촌 동생네 가족은 남은 연휴 동안 해외여행을 떠난대요."],"title":"오늘날 어느 어린이의 설날 글(내 말로)"},"mis":"SO3-2-u2-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_challenge#2','soc',3,2,'u2','L05','g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',2,'ox','auto','농사는 계절과 날씨의 영향을 많이 받아요.',ARRAY['SO3-2-u2-X13']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"ox","stem":"농사는 계절과 날씨의 영향을 많이 받아요.","answer":"O","reason_options":[{"t":"계절에 따라 씨를 뿌리고 거두는 일이 정해져 있기 때문에","correct":true},{"t":"농사는 날씨와 아무 관계가 없기 때문에","mis":"SO3-2-u2-X13"}],"mis":"SO3-2-u2-X13","explanation":["계절마다 할 일이 있어요.","날씨도 중요해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_challenge#3','soc',3,2,'u2','L05','g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',3,'mc','auto','자료의 「가을」 세시 풍속과 가장 관계있는 명절은 무엇인가요?',ARRAY['SO3-2-u2-X13']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"mc","stem":"자료의 「가을」 세시 풍속과 가장 관계있는 명절은 무엇인가요?","options":[{"t":"추석","correct":true},{"t":"설날","mis":"SO3-2-u2-X13"},{"t":"단오","mis":"SO3-2-u2-X13"},{"t":"정월 대보름","mis":"SO3-2-u2-X13"}],"explanation":["곡식을 거둬요.","수확의 기쁨이에요.","추석이에요."],"asset":{"type":"passage","lines":["겨울 — 새해 첫 보름달을 보며 한 해의 풍년을 기원했어요.","가을 — 곡식을 거두고 음식을 만들어 먹으며 수확의 기쁨을 나눴어요."],"title":"옛날 농촌의 계절과 세시 풍속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_challenge#4','soc',3,2,'u2','L05','g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',3,'error','auto','설날 글을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X15']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"error","stem":"설날 글을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「해외여행은 옛날부터 이어져 온 설날 모습이야.」","correct":true,"mis_target":"SO3-2-u2-X15"},{"t":"친구 가 — 「차례와 세배는 옛날부터 이어져 왔어.」","mis":"SO3-2-u2-X15"},{"t":"친구 나 — 「영화 보기는 달라진 모습이야.」","mis":"SO3-2-u2-X15"}],"explanation":["여행을 봐요.","옛날에는 없었어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 친척들이 할아버지 댁에 모여 차례를 지냈어요.","㉡ 차례를 지낸 뒤 세배를 했어요.","㉢ 다 함께 떡국을 먹었어요.","㉣ 고모가 사 온 케이크를 후식으로 먹었어요.","㉤ 우리 가족은 영화관에 가서 영화를 봤어요.","㉥ 사촌 동생네 가족은 남은 연휴 동안 해외여행을 떠난대요."],"title":"오늘날 어느 어린이의 설날 글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_challenge#5','soc',3,2,'u2','L05','g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',3,'mc','auto','설날 글을 두 형광펜으로 칠한 뒤 알 수 있는 것은 무엇인가요?',ARRAY['SO3-2-u2-X15','SO3-2-u2-X14']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"mc","stem":"설날 글을 두 형광펜으로 칠한 뒤 알 수 있는 것은 무엇인가요?","options":[{"t":"차례, 세배, 떡국처럼 이어져 오는 모습도 있고 여행, 영화처럼 달라진 모습도 있어요","correct":true},{"t":"오늘날 설날 모습은 옛날과 모두 똑같아요","mis":"SO3-2-u2-X15"},{"t":"오늘날 설날 모습은 옛날과 모두 달라요","mis":"SO3-2-u2-X14"},{"t":"설날 모습은 칠해도 알 수 있는 것이 없어요","mis":"SO3-2-u2-X15"}],"explanation":["노란 조각이 있어요.","하늘색 조각도 있어요.","둘 다 있어요."],"asset":{"type":"passage","lines":["㉠ 친척들이 할아버지 댁에 모여 차례를 지냈어요.","㉡ 차례를 지낸 뒤 세배를 했어요.","㉢ 다 함께 떡국을 먹었어요.","㉣ 고모가 사 온 케이크를 후식으로 먹었어요.","㉤ 우리 가족은 영화관에 가서 영화를 봤어요.","㉥ 사촌 동생네 가족은 남은 연휴 동안 해외여행을 떠난대요."],"title":"오늘날 어느 어린이의 설날 글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_challenge#6','soc',3,2,'u2','L05','g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',3,'ox','auto','옛날과 오늘날의 생활 모습은 달라졌지만 세시 풍속은 조금도 변함이 없어요.',ARRAY['SO3-2-u2-X14']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"ox","stem":"옛날과 오늘날의 생활 모습은 달라졌지만 세시 풍속은 조금도 변함이 없어요.","answer":"X","reason_options":[{"t":"생활 모습이 달라지면서 세시 풍속도 큰 명절 중심으로 달라졌기 때문에","correct":true},{"t":"세시 풍속은 한번 정해지면 바뀌지 않기 때문에","mis":"SO3-2-u2-X14"}],"mis":"SO3-2-u2-X14","explanation":["생활이 달라졌어요.","세시 풍속도 달라졌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_challenge#7','soc',3,2,'u2','L05','g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',3,'mc','auto','농사짓는 사람이 많던 옛날 마을과 직업이 다양한 오늘날 도시를 견줄 때, 세시 풍속의 차이로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X13','SO3-2-u2-X14']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"mc","stem":"농사짓는 사람이 많던 옛날 마을과 직업이 다양한 오늘날 도시를 견줄 때, 세시 풍속의 차이로 가장 알맞은 것은 무엇인가요?","options":[{"t":"옛날에는 계절마다 다양했고 오늘날에는 큰 명절 중심이에요","correct":true},{"t":"옛날에는 명절이 없었고 오늘날에만 있어요","mis":"SO3-2-u2-X13"},{"t":"옛날과 오늘날 모두 계절마다 같은 수만큼 있어요","mis":"SO3-2-u2-X14"},{"t":"오늘날에는 세시 풍속이 계절마다 더 많아졌어요","mis":"SO3-2-u2-X14"}],"explanation":["옛날은 농사예요.","오늘날은 직업이 다양해요.","큰 명절 중심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_challenge#8','soc',3,2,'u2','L05','g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',4,'mc','auto','「옛날과 오늘날의 세시 풍속 비교」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X02','SO3-2-u2-X14','SO3-2-u2-X16']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C5","difficulty":4,"kind":"mc","stem":"「옛날과 오늘날의 세시 풍속 비교」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"생활 모습이 달라지며 세시 풍속도 달라졌지만 가족이나 이웃과 기쁨을 나누는 마음은 변함없어요","correct":true},{"t":"세시 풍속은 오늘날 모두 사라졌어요","mis":"SO3-2-u2-X02"},{"t":"세시 풍속은 옛날과 하나도 달라지지 않았어요","mis":"SO3-2-u2-X14"},{"t":"오늘날에는 가족이나 이웃과 기쁨을 나누는 일이 사라졌어요","mis":"SO3-2-u2-X16"}],"explanation":["달라진 것이 있어요.","변함없는 것도 있어요.","함께 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_challenge#9','soc',3,2,'u2','L05','g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',4,'mc','auto','설날 글의 ㉥ 가족이 연휴에 여행을 가도 이어지는 옛날 세시 풍속의 마음을 찾는다면 무엇일까요?',ARRAY['SO3-2-u2-X13','SO3-2-u2-X16']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C5","difficulty":4,"kind":"mc","stem":"설날 글의 ㉥ 가족이 연휴에 여행을 가도 이어지는 옛날 세시 풍속의 마음을 찾는다면 무엇일까요?","options":[{"t":"가족과 함께 시간을 보내며 기쁨을 나누는 마음","correct":true},{"t":"농사의 풍년을 비는 마음","mis":"SO3-2-u2-X13"},{"t":"혼자 조용히 쉬려는 마음","mis":"SO3-2-u2-X16"},{"t":"세시 풍속을 모두 버리려는 마음","mis":"SO3-2-u2-X16"}],"explanation":["여행도 가족과 가요.","함께 보내요.","기쁨을 나눠요."],"asset":{"type":"passage","lines":["㉠ 친척들이 할아버지 댁에 모여 차례를 지냈어요.","㉡ 차례를 지낸 뒤 세배를 했어요.","㉢ 다 함께 떡국을 먹었어요.","㉣ 고모가 사 온 케이크를 후식으로 먹었어요.","㉤ 우리 가족은 영화관에 가서 영화를 봤어요.","㉥ 사촌 동생네 가족은 남은 연휴 동안 해외여행을 떠난대요."],"title":"오늘날 어느 어린이의 설날 글(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L05_challenge#10','soc',3,2,'u2','L05','g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',4,'essay','teacher','우리 가족의 명절 모습을 떠올려 옛날부터 이어져 오는 모습과 달라진 모습을 하나씩 쓰고, 변함없이 이어지는 마음을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C5","difficulty":4,"kind":"essay","stem":"우리 가족의 명절 모습을 떠올려 옛날부터 이어져 오는 모습과 달라진 모습을 하나씩 쓰고, 변함없이 이어지는 마음을 쓰세요.","answer_guide":{"answer":"예: 추석에 송편을 먹는 것은 옛날부터 이어져 오는 모습이에요. 연휴에 가족과 놀이공원에 가는 것은 달라진 모습이에요. 그래도 가족이 함께 모여 기쁨을 나누는 마음은 변함없어요.","scoring_points":["이어져 오는 모습을 썼는가","달라진 모습을 썼는가","변함없는 마음을 썼는가"]},"explanation":["노란 형광펜이에요.","하늘색 형광펜이에요.","마음을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_basic#1','soc',3,2,'u2','L06','g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',1,'mc','auto','설날에 복이 들어오기를 바라며 옷에 차고 다니던 물건은 무엇인가요?',ARRAY['SO3-2-u2-X17']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C6","difficulty":1,"kind":"mc","stem":"설날에 복이 들어오기를 바라며 옷에 차고 다니던 물건은 무엇인가요?","options":[{"t":"복주머니","correct":true},{"t":"부채","mis":"SO3-2-u2-X17"},{"t":"나무 기러기","mis":"SO3-2-u2-X17"},{"t":"금줄","mis":"SO3-2-u2-X17"}],"explanation":["설날 아침이에요.","주머니예요.","복주머니예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_basic#2','soc',3,2,'u2','L06','g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',1,'sa','auto','제기가 바닥에 떨어지지 않게 차면서 노는 놀이를 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C6","difficulty":1,"kind":"sa","stem":"제기가 바닥에 떨어지지 않게 차면서 노는 놀이를 네 글자로 쓰세요.","answer":["제기차기"],"explanation":["발로 차요.","제기◯◯예요.","제기차기예요."],"mis":"SO3-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_basic#3','soc',3,2,'u2','L06','g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',1,'ox','auto','오늘날에도 설날에 복주머니를 선물하기도 해요.',ARRAY['SO3-2-u2-X02']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C6","difficulty":1,"kind":"ox","stem":"오늘날에도 설날에 복주머니를 선물하기도 해요.","answer":"O","reason_options":[{"t":"설날에 복이 들어오기를 바라는 마음이 오늘날에도 이어지기 때문에","correct":true},{"t":"복주머니는 오늘날 볼 수 없는 물건이기 때문에","mis":"SO3-2-u2-X02"}],"mis":"SO3-2-u2-X02","explanation":["오늘날에도 해요.","선물해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
