INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_basic#5','soc',3,2,'u2','L06','g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',2,'mc','auto','윷놀이를 할 때 필요한 것끼리 모은 것은 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"mc","stem":"윷놀이를 할 때 필요한 것끼리 모은 것은 무엇인가요?","options":[{"t":"윷, 윷판, 윷말","correct":true},{"t":"투호 병과 화살","mis":"SO3-2-u2-X18"},{"t":"제기와 안전 고깔","mis":"SO3-2-u2-X18"},{"t":"고누판과 부채","mis":"SO3-2-u2-X18"}],"explanation":["윷을 던져요.","말을 놓아요.","윷·윷판·윷말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_basic#6','soc',3,2,'u2','L06','g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',2,'mc','auto','복주머니를 만들 때 가장 먼저 하는 일은 무엇인가요?',ARRAY['SO3-2-u2-X17']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"mc","stem":"복주머니를 만들 때 가장 먼저 하는 일은 무엇인가요?","options":[{"t":"활동 자료를 뜯어 준비하기","correct":true},{"t":"리본이나 끈으로 손잡이 만들기","mis":"SO3-2-u2-X17"},{"t":"도안에 풀을 발라 모양 만들기","mis":"SO3-2-u2-X17"},{"t":"도안에 색칠하고 모양대로 뜯기","mis":"SO3-2-u2-X17"}],"explanation":["도안이 있어야 해요.","먼저 준비해요.","활동 자료를 뜯어요."],"asset":{"type":"passage","lines":["① ‘복주머니 만들기’ 활동 자료를 뜯어 준비해요.","② 도안에 색칠하고 복주머니 모양으로 뜯어요.","③ 도안에 풀을 발라 복주머니 모양을 만들어요.","④ 리본이나 끈으로 손잡이를 만들어 완성해요."],"title":"복주머니 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_basic#7','soc',3,2,'u2','L06','g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',2,'blank','auto','윷놀이에서 윷 또는 모가 나오거나 상대편 윷말을 잡으면 한 번 (    ) 던져요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"blank","stem":"윷놀이에서 윷 또는 모가 나오거나 상대편 윷말을 잡으면 한 번 (    ) 던져요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"더","correct":true},{"t":"덜","mis":"SO3-2-u2-X18"},{"t":"쉬고","mis":"SO3-2-u2-X18"},{"t":"빼고","mis":"SO3-2-u2-X18"}],"explanation":["좋은 결과예요.","한 번 ◯예요.","더예요."],"asset":{"type":"passage","lines":["· 윷판을 펼쳐 놓고 편을 둘로 나눠요. 편마다 윷말을 네 개씩 가져요.","· 윷을 던져 나온 결과(도, 개, 걸, 윷, 모)에 따라 윷말을 움직여요.","· 윷 또는 모가 나오거나 상대편 윷말을 잡으면 한 번 더 던져요.","· 네 개의 윷말이 먼저 출발점으로 들어오면 이겨요."],"title":"윷놀이 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_basic#8','soc',3,2,'u2','L06','g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',2,'match','auto','전통 놀이와 놀이 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"match","stem":"전통 놀이와 놀이 방법을 알맞게 이으세요.","pairs":[{"l":"윷놀이","r":"편을 갈라 윷으로 승부를 겨뤄요"},{"l":"제기차기","r":"제기가 떨어지지 않게 차요"},{"l":"투호","r":"병에 화살을 던져 넣어요"},{"l":"고누","r":"판에서 말을 따거나 가둬요"}],"mis":"SO3-2-u2-X18","explanation":["윷은 던져요.","제기는 차요.","투호와 고누도 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_basic#9','soc',3,2,'u2','L06','g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',2,'ox','auto','전통 놀이를 체험할 때는 안전에 유의하고 규칙을 잘 지켜야 해요.',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"ox","stem":"전통 놀이를 체험할 때는 안전에 유의하고 규칙을 잘 지켜야 해요.","answer":"O","reason_options":[{"t":"함께 즐겁게 놀려면 다치지 않고 약속을 지켜야 하기 때문에","correct":true},{"t":"전통 놀이에는 규칙이 없기 때문에","mis":"SO3-2-u2-X18"}],"mis":"SO3-2-u2-X18","explanation":["여럿이 놀아요.","안전과 규칙이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_basic#10','soc',3,2,'u2','L06','g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',3,'mc','auto','윷놀이 방법에서 이기는 때는 언제인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"mc","stem":"윷놀이 방법에서 이기는 때는 언제인가요?","options":[{"t":"네 개의 윷말이 먼저 출발점으로 들어왔을 때","correct":true},{"t":"윷을 처음 던졌을 때","mis":"SO3-2-u2-X18"},{"t":"도가 나왔을 때","mis":"SO3-2-u2-X18"},{"t":"윷말 하나가 먼저 들어왔을 때","mis":"SO3-2-u2-X18"}],"explanation":["윷말은 네 개예요.","모두 들어와야 해요.","먼저 들어오면 이겨요."],"asset":{"type":"passage","lines":["· 윷판을 펼쳐 놓고 편을 둘로 나눠요. 편마다 윷말을 네 개씩 가져요.","· 윷을 던져 나온 결과(도, 개, 걸, 윷, 모)에 따라 윷말을 움직여요.","· 윷 또는 모가 나오거나 상대편 윷말을 잡으면 한 번 더 던져요.","· 네 개의 윷말이 먼저 출발점으로 들어오면 이겨요."],"title":"윷놀이 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
