INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_challenge#2','soc',3,2,'u2','L06','g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',2,'ox','auto','복주머니는 아무 순서로 만들어도 똑같이 완성돼요.',ARRAY['SO3-2-u2-X17']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"ox","stem":"복주머니는 아무 순서로 만들어도 똑같이 완성돼요.","answer":"X","reason_options":[{"t":"도안을 준비하고 색칠해 뜯은 뒤 붙이고 손잡이를 다는 차례가 있기 때문에","correct":true},{"t":"만드는 차례는 아무 상관이 없기 때문에","mis":"SO3-2-u2-X17"}],"mis":"SO3-2-u2-X17","explanation":["차례가 있어요.","뜯어야 색칠해요.","그래서 X예요."],"asset":{"type":"passage","lines":["① ‘복주머니 만들기’ 활동 자료를 뜯어 준비해요.","② 도안에 색칠하고 복주머니 모양으로 뜯어요.","③ 도안에 풀을 발라 복주머니 모양을 만들어요.","④ 리본이나 끈으로 손잡이를 만들어 완성해요."],"title":"복주머니 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_challenge#3','soc',3,2,'u2','L06','g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',3,'mc','auto','복주머니 만드는 차례에서 ③ 바로 앞에 하는 일은 무엇인가요?',ARRAY['SO3-2-u2-X17']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"mc","stem":"복주머니 만드는 차례에서 ③ 바로 앞에 하는 일은 무엇인가요?","options":[{"t":"도안에 색칠하고 복주머니 모양으로 뜯기","correct":true},{"t":"리본이나 끈으로 손잡이 만들기","mis":"SO3-2-u2-X17"},{"t":"활동 자료를 뜯어 준비하기","mis":"SO3-2-u2-X17"},{"t":"복주머니를 선물하기","mis":"SO3-2-u2-X17"}],"explanation":["③은 풀로 붙여요.","그 앞이에요.","색칠하고 뜯어요."],"asset":{"type":"passage","lines":["① ‘복주머니 만들기’ 활동 자료를 뜯어 준비해요.","② 도안에 색칠하고 복주머니 모양으로 뜯어요.","③ 도안에 풀을 발라 복주머니 모양을 만들어요.","④ 리본이나 끈으로 손잡이를 만들어 완성해요."],"title":"복주머니 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_challenge#4','soc',3,2,'u2','L06','g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',3,'mc','auto','복주머니를 설날 아침에 차고 다닌 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X17','SO3-2-u2-X18']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"mc","stem":"복주머니를 설날 아침에 차고 다닌 까닭은 무엇인가요?","options":[{"t":"복이 들어온다는 좋은 뜻이었기 때문이에요","correct":true},{"t":"나쁜 기운을 쫓는 팥이 들어 있었기 때문이에요","mis":"SO3-2-u2-X17"},{"t":"여름을 시원하게 보내려고요","mis":"SO3-2-u2-X17"},{"t":"윷놀이에 쓰려고요","mis":"SO3-2-u2-X18"}],"explanation":["이름에 답이 있어요.","복이에요.","복이 들어와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_challenge#5','soc',3,2,'u2','L06','g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',3,'error','auto','윷놀이 규칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"error","stem":"윷놀이 규칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「도가 나오면 한 번 더 던질 수 있어.」","correct":true,"mis_target":"SO3-2-u2-X18"},{"t":"친구 나 — 「모가 나오면 한 번 더 던져.」","mis":"SO3-2-u2-X18"},{"t":"친구 다 — 「상대편 윷말을 잡으면 한 번 더 던져.」","mis":"SO3-2-u2-X18"}],"explanation":["규칙을 봐요.","윷이나 모예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["· 윷판을 펼쳐 놓고 편을 둘로 나눠요. 편마다 윷말을 네 개씩 가져요.","· 윷을 던져 나온 결과(도, 개, 걸, 윷, 모)에 따라 윷말을 움직여요.","· 윷 또는 모가 나오거나 상대편 윷말을 잡으면 한 번 더 던져요.","· 네 개의 윷말이 먼저 출발점으로 들어오면 이겨요."],"title":"윷놀이 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_challenge#6','soc',3,2,'u2','L06','g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',3,'mc','auto','어린이들에게 전통 놀이를 가르쳐 주고 체험 활동을 진행하는 직업은 무엇인가요?',ARRAY['SO3-2-u2-X18','SO3-2-u2-X17','SO3-2-u2-X02']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"mc","stem":"어린이들에게 전통 놀이를 가르쳐 주고 체험 활동을 진행하는 직업은 무엇인가요?","options":[{"t":"전통 놀이 지도사","correct":true},{"t":"전통 놀이를 없애는 사람","mis":"SO3-2-u2-X18"},{"t":"복주머니만 파는 사람","mis":"SO3-2-u2-X17"},{"t":"명절을 새로 만드는 사람","mis":"SO3-2-u2-X02"}],"explanation":["우리 놀이를 알려요.","가르쳐 줘요.","전통 놀이 지도사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_challenge#7','soc',3,2,'u2','L06','g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',3,'ox','auto','전통 놀이는 혼자서만 할 수 있는 놀이예요.',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"ox","stem":"전통 놀이는 혼자서만 할 수 있는 놀이예요.","answer":"X","reason_options":[{"t":"윷놀이처럼 편을 갈라 여럿이 함께 겨루는 놀이가 많기 때문에","correct":true},{"t":"전통 놀이는 함께하면 안 되기 때문에","mis":"SO3-2-u2-X18"}],"mis":"SO3-2-u2-X18","explanation":["편을 갈라요.","모둠이 함께해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_challenge#8','soc',3,2,'u2','L06','g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',4,'mc','auto','오늘 체험한 풍습을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X02','SO3-2-u2-X17']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C6","difficulty":4,"kind":"mc","stem":"오늘 체험한 풍습을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"복주머니 만들기, 윷놀이, 제기차기처럼 옛날부터 오늘날까지 전해 내려오는 풍습이 있어요","correct":true},{"t":"옛날 풍습은 오늘날까지 하나도 전해 내려오지 않아요","mis":"SO3-2-u2-X02"},{"t":"전통 놀이는 옛날 사람들만 할 수 있어요","mis":"SO3-2-u2-X02"},{"t":"복주머니는 아무 뜻이 없는 물건이에요","mis":"SO3-2-u2-X17"}],"explanation":["직접 해 봤어요.","오늘날에도 해요.","전해 내려와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_challenge#9','soc',3,2,'u2','L06','g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',4,'mc','auto','윷을 던져 「윷」이 나와 상대편 윷말을 잡았어요. 그다음에 할 일로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C6","difficulty":4,"kind":"mc","stem":"윷을 던져 「윷」이 나와 상대편 윷말을 잡았어요. 그다음에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"한 번 더 던져요","correct":true},{"t":"차례를 넘겨요","mis":"SO3-2-u2-X18"},{"t":"놀이를 끝내요","mis":"SO3-2-u2-X18"},{"t":"윷말을 처음 자리로 되돌려요","mis":"SO3-2-u2-X18"}],"explanation":["윷이 나왔어요.","상대 말도 잡았어요.","한 번 더 던져요."],"asset":{"type":"passage","lines":["· 윷판을 펼쳐 놓고 편을 둘로 나눠요. 편마다 윷말을 네 개씩 가져요.","· 윷을 던져 나온 결과(도, 개, 걸, 윷, 모)에 따라 윷말을 움직여요.","· 윷 또는 모가 나오거나 상대편 윷말을 잡으면 한 번 더 던져요.","· 네 개의 윷말이 먼저 출발점으로 들어오면 이겨요."],"title":"윷놀이 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L06_challenge#10','soc',3,2,'u2','L06','g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',4,'essay','teacher','모둠 친구들에게 전통 놀이 하나를 소개하는 글을 쓰세요. 놀이 이름, 필요한 도구, 노는 방법을 넣고 지킬 점도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C6","difficulty":4,"kind":"essay","stem":"모둠 친구들에게 전통 놀이 하나를 소개하는 글을 쓰세요. 놀이 이름, 필요한 도구, 노는 방법을 넣고 지킬 점도 쓰세요.","answer_guide":{"answer":"예: 제기차기를 소개할게요. 제기가 필요해요. 제기가 바닥에 떨어지지 않게 발로 계속 차고, 많이 찬 사람이 이겨요. 주변 친구와 부딪치지 않게 거리를 두고 규칙을 잘 지켜요.","scoring_points":["놀이 이름과 도구를 썼는가","노는 방법을 썼는가","안전·규칙을 썼는가"]},"explanation":["놀이를 골라요.","방법을 써요.","지킬 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_basic#1','soc',3,2,'u2','L07','g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',1,'mc','auto','전광판의 칸 가운데 옛날 세시 음식이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C7","difficulty":1,"kind":"mc","stem":"전광판의 칸 가운데 옛날 세시 음식이 아닌 것은 무엇인가요?","options":[{"t":"라면","correct":true},{"t":"떡국","mis":"SO3-2-u2-X11"},{"t":"송편","mis":"SO3-2-u2-X11"},{"t":"팥죽","mis":"SO3-2-u2-X11"}],"explanation":["명절 음식을 떠올려요.","떡국·송편·팥죽이에요.","라면은 아니에요."],"asset":{"type":"passage","lines":["떡국 · 송편 · 팥죽 · 오곡밥 · 수리취떡 · 라면 · 우유 선물","쥐불놀이 · 다리밟기 · 강강술래 · 그네뛰기 · 책 읽기 · 금줄 치기"],"title":"풍습 전광판의 칸 몇 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_basic#2','soc',3,2,'u2','L07','g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',1,'sa','auto','어버이날 부모님께 선물하는 꽃을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C7","difficulty":1,"kind":"sa","stem":"어버이날 부모님께 선물하는 꽃을 쓰세요.","answer":["카네이션"],"explanation":["빨간 꽃이에요.","카◯◯◯이에요.","카네이션이에요."],"mis":"SO3-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_basic#3','soc',3,2,'u2','L07','g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',1,'ox','auto','쥐불놀이는 정월 대보름에 하던 일이에요.',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C7","difficulty":1,"kind":"ox","stem":"쥐불놀이는 정월 대보름에 하던 일이에요.","answer":"O","reason_options":[{"t":"정월 대보름에 달맞이와 함께 쥐불놀이와 다리밟기를 했기 때문에","correct":true},{"t":"쥐불놀이는 단오에 하던 일이기 때문에","mis":"SO3-2-u2-X11"}],"mis":"SO3-2-u2-X11","explanation":["보름달이에요.","달맞이와 함께해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_basic#4','soc',3,2,'u2','L07','g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',1,'mc','auto','시험을 치르는 사람에게 주는 것으로, 합격을 기원하는 마음이 담긴 것은 무엇인가요?',ARRAY['SO3-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C7","difficulty":1,"kind":"mc","stem":"시험을 치르는 사람에게 주는 것으로, 합격을 기원하는 마음이 담긴 것은 무엇인가요?","options":[{"t":"엿","correct":true},{"t":"부채","mis":"SO3-2-u2-X19"},{"t":"카네이션","mis":"SO3-2-u2-X19"},{"t":"팥죽","mis":"SO3-2-u2-X19"}],"explanation":["끈끈하게 붙어요.","시험 풍습이에요.","엿이에요."],"asset":{"type":"passage","lines":["가. 시험을 치르는 사람에게 엿을 줘요.","나. 어버이날 부모님께 카네이션을 선물해요.","다. 설날에 복주머니를 선물해요."],"title":"오늘날 볼 수 있는 풍습 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_basic#5','soc',3,2,'u2','L07','g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',2,'match','auto','오늘날 풍습과 담긴 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"match","stem":"오늘날 풍습과 담긴 뜻을 알맞게 이으세요.","pairs":[{"l":"엿 주기","r":"합격을 기원해요"},{"l":"카네이션 선물","r":"부모님 사랑에 감사해요"},{"l":"복주머니 선물","r":"복이 들어오기를 바라요"}],"mis":"SO3-2-u2-X19","explanation":["시험은 합격이에요.","어버이날은 감사예요.","설날은 복이에요."],"asset":{"type":"passage","lines":["가. 시험을 치르는 사람에게 엿을 줘요.","나. 어버이날 부모님께 카네이션을 선물해요.","다. 설날에 복주머니를 선물해요."],"title":"오늘날 볼 수 있는 풍습 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_basic#6','soc',3,2,'u2','L07','g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',2,'mc','auto','전광판의 칸 가운데 옛날 명절이나 절기에 하던 일은 무엇인가요?',ARRAY['SO3-2-u2-X11','SO3-2-u2-X01']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"mc","stem":"전광판의 칸 가운데 옛날 명절이나 절기에 하던 일은 무엇인가요?","options":[{"t":"다리밟기","correct":true},{"t":"책 읽기","mis":"SO3-2-u2-X11"},{"t":"금줄 치기","mis":"SO3-2-u2-X01"},{"t":"우유 선물","mis":"SO3-2-u2-X11"}],"explanation":["정월 대보름이에요.","쥐불놀이와 함께해요.","다리밟기예요."],"asset":{"type":"passage","lines":["떡국 · 송편 · 팥죽 · 오곡밥 · 수리취떡 · 라면 · 우유 선물","쥐불놀이 · 다리밟기 · 강강술래 · 그네뛰기 · 책 읽기 · 금줄 치기"],"title":"풍습 전광판의 칸 몇 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_basic#7','soc',3,2,'u2','L07','g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',2,'blank','auto','플라잉 디스크 윷놀이는 윷 대신 플라잉 디스크를 던지는, (    ) 놀이에 새로운 도구를 더한 놀이예요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"blank","stem":"플라잉 디스크 윷놀이는 윷 대신 플라잉 디스크를 던지는, (    ) 놀이에 새로운 도구를 더한 놀이예요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"전통","correct":true},{"t":"컴퓨터","mis":"SO3-2-u2-X18"},{"t":"외국","mis":"SO3-2-u2-X18"},{"t":"공부","mis":"SO3-2-u2-X18"}],"explanation":["윷놀이예요.","옛날부터 내려와요.","전통이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_basic#8','soc',3,2,'u2','L07','g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',2,'ox','auto','금줄 치기는 명절이나 절기에 하던 일이에요.',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"ox","stem":"금줄 치기는 명절이나 절기에 하던 일이에요.","answer":"X","reason_options":[{"t":"금줄 치기는 아기가 태어났을 때 하던 일상생활 속 풍습이기 때문에","correct":true},{"t":"금줄 치기는 해마다 설날에 하던 일이기 때문에","mis":"SO3-2-u2-X01"}],"mis":"SO3-2-u2-X01","explanation":["언제 쳤나요?","아기가 태어났을 때예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
