INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_challenge#2','soc',3,2,'u2','L07','g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',2,'ox','auto','전광판에서 수리취떡은 세시 음식 칸이에요.',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"ox","stem":"전광판에서 수리취떡은 세시 음식 칸이에요.","answer":"O","reason_options":[{"t":"수리취떡은 단오에 먹던 세시 음식이기 때문에","correct":true},{"t":"수리취떡은 아무 때나 먹는 과자이기 때문에","mis":"SO3-2-u2-X11"}],"mis":"SO3-2-u2-X11","explanation":["단오 음식이에요.","수레바퀴 모양이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_challenge#3','soc',3,2,'u2','L07','g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',3,'mc','auto','전광판에서 「세시 음식」 칸도 「명절·절기에 하던 일」 칸도 아닌 것끼리 모은 것은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"mc","stem":"전광판에서 「세시 음식」 칸도 「명절·절기에 하던 일」 칸도 아닌 것끼리 모은 것은 무엇인가요?","options":[{"t":"라면, 우유 선물, 책 읽기, 금줄 치기","correct":true},{"t":"떡국, 송편, 팥죽, 오곡밥","mis":"SO3-2-u2-X11"},{"t":"쥐불놀이, 다리밟기, 강강술래, 그네뛰기","mis":"SO3-2-u2-X11"},{"t":"송편, 강강술래, 팥죽, 쥐불놀이","mis":"SO3-2-u2-X11"}],"explanation":["두 칸에 넣을 것을 빼요.","남은 것이 있어요.","라면·우유·책·금줄이에요."],"asset":{"type":"passage","lines":["떡국 · 송편 · 팥죽 · 오곡밥 · 수리취떡 · 라면 · 우유 선물","쥐불놀이 · 다리밟기 · 강강술래 · 그네뛰기 · 책 읽기 · 금줄 치기"],"title":"풍습 전광판의 칸 몇 개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_challenge#4','soc',3,2,'u2','L07','g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',3,'error','auto','풍습을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"error","stem":"풍습을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「카네이션 선물에는 합격을 기원하는 마음이 담겨 있어.」","correct":true,"mis_target":"SO3-2-u2-X19"},{"t":"친구 가 — 「엿 주기에는 합격을 기원하는 마음이 담겨 있어.」","mis":"SO3-2-u2-X19"},{"t":"친구 다 — 「복주머니 선물에는 복을 바라는 마음이 담겨 있어.」","mis":"SO3-2-u2-X19"}],"explanation":["카네이션은 언제 줘요?","어버이날이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["가. 시험을 치르는 사람에게 엿을 줘요.","나. 어버이날 부모님께 카네이션을 선물해요.","다. 설날에 복주머니를 선물해요."],"title":"오늘날 볼 수 있는 풍습 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_challenge#5','soc',3,2,'u2','L07','g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',3,'mc','auto','설날 모습 가운데 옛날부터 오늘날까지 이어져 내려오는 것은 무엇인가요?',ARRAY['SO3-2-u2-X15']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"mc","stem":"설날 모습 가운데 옛날부터 오늘날까지 이어져 내려오는 것은 무엇인가요?","options":[{"t":"차례 지내고 세배하고 떡국 먹기","correct":true},{"t":"해외여행 가기","mis":"SO3-2-u2-X15"},{"t":"영화 보기","mis":"SO3-2-u2-X15"},{"t":"보드게임 하기","mis":"SO3-2-u2-X15"}],"explanation":["옛날 설날에도 했어요.","친척이 모여요.","차례·세배·떡국이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_challenge#6','soc',3,2,'u2','L07','g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',3,'ox','auto','세시 풍속은 해마다 되풀이하지 않아서 풍습이 아니에요.',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"ox","stem":"세시 풍속은 해마다 되풀이하지 않아서 풍습이 아니에요.","answer":"X","reason_options":[{"t":"세시 풍속은 해마다 일정한 때에 되풀이하는 풍습이기 때문에","correct":true},{"t":"세시 풍속은 한 번만 하는 행사이기 때문에","mis":"SO3-2-u2-X01"}],"mis":"SO3-2-u2-X01","explanation":["해마다 되풀이해요.","풍습의 하나예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_challenge#7','soc',3,2,'u2','L07','g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',3,'mc','auto','옛날과 오늘날의 세시 풍속이 달라져도 이어지는 마음을 정리한 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X16','SO3-2-u2-X13']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"mc","stem":"옛날과 오늘날의 세시 풍속이 달라져도 이어지는 마음을 정리한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"가족이나 이웃과 함께 기쁨을 나누는 마음","correct":true},{"t":"혼자만 즐기려는 마음","mis":"SO3-2-u2-X16"},{"t":"농사만 생각하는 마음","mis":"SO3-2-u2-X13"},{"t":"옛것을 모두 버리려는 마음","mis":"SO3-2-u2-X16"}],"explanation":["명절에 모여요.","함께해요.","기쁨을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_challenge#8','soc',3,2,'u2','L07','g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',4,'mc','auto','주제 「옛날과 오늘날의 풍습」을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X02','SO3-2-u2-X09']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C7","difficulty":4,"kind":"mc","stem":"주제 「옛날과 오늘날의 풍습」을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"옛날 풍습에는 생활과 생각이 담겨 있고, 모습을 바꾸며 오늘날까지 이어지는 풍습도 있어요","correct":true},{"t":"옛날 풍습과 오늘날 생활은 아무 관계가 없어요","mis":"SO3-2-u2-X44"},{"t":"오늘날에는 옛날부터 이어진 풍습이 하나도 없어요","mis":"SO3-2-u2-X02"},{"t":"풍습은 한번 정해지면 조금도 바뀌지 않아요","mis":"SO3-2-u2-X09"}],"explanation":["생활과 생각이 담겼어요.","모습이 바뀌어요.","이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_challenge#9','soc',3,2,'u2','L07','g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',4,'mc','auto','미래에 전해 주고 싶은 오늘날 풍습을 소개하는 글에 꼭 들어가야 할 두 가지는 무엇인가요?',ARRAY['SO3-2-u2-X19','SO3-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C7","difficulty":4,"kind":"mc","stem":"미래에 전해 주고 싶은 오늘날 풍습을 소개하는 글에 꼭 들어가야 할 두 가지는 무엇인가요?","options":[{"t":"풍습 설명과 담긴 뜻","correct":true},{"t":"풍습의 값과 파는 곳","mis":"SO3-2-u2-X19"},{"t":"풍습을 처음 만든 사람 이름","mis":"SO3-2-u2-X19"},{"t":"풍습을 없애는 방법","mis":"SO3-2-u2-X02"}],"explanation":["무엇인지 써요.","어떤 마음인지 써요.","설명과 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L07_challenge#10','soc',3,2,'u2','L07','g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',4,'essay','teacher','오늘날 풍습 가운데 미래에 전해 주고 싶은 것을 하나 골라 풍습 설명과 담긴 뜻을 쓰고, 전해 주고 싶은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C7","difficulty":4,"kind":"essay","stem":"오늘날 풍습 가운데 미래에 전해 주고 싶은 것을 하나 골라 풍습 설명과 담긴 뜻을 쓰고, 전해 주고 싶은 까닭을 쓰세요.","answer_guide":{"answer":"예: 어버이날 부모님께 카네이션을 선물하는 풍습이에요. 부모님의 사랑에 감사하는 마음이 담겨 있어요. 미래에도 고마운 마음을 표현하는 좋은 풍습이라 전해 주고 싶어요.","scoring_points":["풍습을 설명했는가","담긴 뜻을 썼는가","전해 주고 싶은 까닭을 썼는가"]},"explanation":["풍습을 골라요.","뜻을 써요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_basic#1','soc',3,2,'u2','L08','g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',1,'mc','auto','어떤 장소에서 다른 장소로 사람이 이동하거나 물건을 옮기는 것을 무엇이라고 하나요?',ARRAY['SO3-2-u2-X20']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C8","difficulty":1,"kind":"mc","stem":"어떤 장소에서 다른 장소로 사람이 이동하거나 물건을 옮기는 것을 무엇이라고 하나요?","options":[{"t":"교통","correct":true},{"t":"세시 풍속","mis":"SO3-2-u2-X20"},{"t":"교통로","mis":"SO3-2-u2-X20"},{"t":"풍습","mis":"SO3-2-u2-X20"}],"explanation":["이동하고 옮겨요.","장소와 장소 사이예요.","교통이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_basic#2','soc',3,2,'u2','L08','g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',1,'sa','auto','사람이 이동하거나 물건을 옮길 때 사용하는 도구를 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C8","difficulty":1,"kind":"sa","stem":"사람이 이동하거나 물건을 옮길 때 사용하는 도구를 네 글자로 쓰세요.","answer":["교통수단"],"explanation":["도구예요.","교통◯◯이에요.","교통수단이에요."],"mis":"SO3-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_basic#3','soc',3,2,'u2','L08','g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',1,'ox','auto','하늘에도 비행기가 다니도록 정해진 길이 있어요.',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C8","difficulty":1,"kind":"ox","stem":"하늘에도 비행기가 다니도록 정해진 길이 있어요.","answer":"O","reason_options":[{"t":"눈에 보이지는 않지만 비행기가 다니는 항공로가 있기 때문에","correct":true},{"t":"하늘에는 길이 하나도 없기 때문에","mis":"SO3-2-u2-X21"}],"mis":"SO3-2-u2-X21","explanation":["눈에 보이지 않아요.","항공로예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_basic#4','soc',3,2,'u2','L08','g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',1,'mc','auto','다음 가운데 교통로가 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X20']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C8","difficulty":1,"kind":"mc","stem":"다음 가운데 교통로가 아닌 것은 무엇인가요?","options":[{"t":"자동차","correct":true},{"t":"도로","mis":"SO3-2-u2-X20"},{"t":"철도","mis":"SO3-2-u2-X20"},{"t":"수로","mis":"SO3-2-u2-X20"}],"explanation":["교통로는 길이에요.","길 위를 다니는 것을 빼요.","자동차는 교통수단이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_basic#5','soc',3,2,'u2','L08','g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',2,'match','auto','교통수단과 다니는 길을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C8","difficulty":2,"kind":"match","stem":"교통수단과 다니는 길을 알맞게 이으세요.","pairs":[{"l":"고속버스","r":"고속 국도"},{"l":"지하철","r":"철도"},{"l":"유람선","r":"수로"},{"l":"비행기","r":"항공로"}],"mis":"SO3-2-u2-X21","explanation":["고속버스는 고속 국도예요.","지하철은 철도예요.","유람선과 비행기도 이어요."],"asset":{"type":"passage","lines":["마을버스 — 도로","고속버스 — 고속 국도","지하철 — 철도","자전거 — 자전거 도로","유람선 — 바다나 강의 정해진 수로"],"title":"교통수단과 다니는 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_basic#6','soc',3,2,'u2','L08','g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',2,'mc','auto','그림 속 모습 가운데 실제로 보기 어려운 것은 무엇인가요?',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C8","difficulty":2,"kind":"mc","stem":"그림 속 모습 가운데 실제로 보기 어려운 것은 무엇인가요?","options":[{"t":"㉡","correct":true},{"t":"㉠","mis":"SO3-2-u2-X21"},{"t":"㉣","mis":"SO3-2-u2-X21"},{"t":"모두 실제 모습이에요","mis":"SO3-2-u2-X21"}],"explanation":["열차의 길을 봐요.","철도로 다녀요.","㉡이에요."],"asset":{"type":"passage","lines":["㉠ 자동차가 도로로 다녀요.","㉡ 열차가 바다 위를 달려요.","㉢ 배가 하늘을 날아요.","㉣ 비행기가 하늘로 다녀요."],"title":"「생각을 열어요」 그림 속 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_basic#7','soc',3,2,'u2','L08','g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',2,'blank','auto','교통은 주로 (    )를 따라 움직이는 교통수단에 의해 이루어져요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X20']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C8","difficulty":2,"kind":"blank","stem":"교통은 주로 (    )를 따라 움직이는 교통수단에 의해 이루어져요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"교통로","correct":true},{"t":"세시 풍속","mis":"SO3-2-u2-X20"},{"t":"교통수단","mis":"SO3-2-u2-X20"},{"t":"주차장","mis":"SO3-2-u2-X20"}],"explanation":["교통에 쓰는 길이에요.","교통◯예요.","교통로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
