INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_basic#9','soc',3,2,'u2','L08','g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',2,'ox','auto','교통수단은 사람이 이동할 때만 쓰고 물건을 옮길 때는 쓰지 않아요.',ARRAY['SO3-2-u2-X22']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C8","difficulty":2,"kind":"ox","stem":"교통수단은 사람이 이동할 때만 쓰고 물건을 옮길 때는 쓰지 않아요.","answer":"X","reason_options":[{"t":"트럭이나 화물선처럼 물건을 옮기는 교통수단도 있기 때문에","correct":true},{"t":"교통은 사람만 옮기는 일이기 때문에","mis":"SO3-2-u2-X22"}],"mis":"SO3-2-u2-X22","explanation":["짐도 옮겨요.","트럭이 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
