INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_challenge#6','soc',3,2,'u2','L08','g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',3,'mc','auto','그림 속 ㉢을 실제 모습으로 바로잡은 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C8","difficulty":3,"kind":"mc","stem":"그림 속 ㉢을 실제 모습으로 바로잡은 것으로 알맞은 것은 무엇인가요?","options":[{"t":"배가 바다로 다녀요","correct":true},{"t":"배가 철도로 다녀요","mis":"SO3-2-u2-X21"},{"t":"배가 고속 국도로 다녀요","mis":"SO3-2-u2-X21"},{"t":"배가 하늘로 다녀요","mis":"SO3-2-u2-X21"}],"explanation":["배의 교통로예요.","바다나 강이에요.","바다로 다녀요."],"asset":{"type":"passage","lines":["㉠ 자동차가 도로로 다녀요.","㉡ 열차가 바다 위를 달려요.","㉢ 배가 하늘을 날아요.","㉣ 비행기가 하늘로 다녀요."],"title":"「생각을 열어요」 그림 속 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_challenge#7','soc',3,2,'u2','L08','g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',3,'ox','auto','교통수단은 아무 길로나 다닐 수 있어요.',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C8","difficulty":3,"kind":"ox","stem":"교통수단은 아무 길로나 다닐 수 있어요.","answer":"X","reason_options":[{"t":"교통수단마다 다니는 교통로가 정해져 있기 때문에","correct":true},{"t":"모든 교통수단은 같은 길로 다니기 때문에","mis":"SO3-2-u2-X21"}],"mis":"SO3-2-u2-X21","explanation":["제 길이 있어요.","철도·수로·항공로예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_challenge#8','soc',3,2,'u2','L08','g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',4,'mc','auto','「교통의 뜻」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X22','SO3-2-u2-X21','SO3-2-u2-X20']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C8","difficulty":4,"kind":"mc","stem":"「교통의 뜻」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"교통은 교통로를 따라 움직이는 교통수단으로 이루어지고, 사람들은 필요에 따라 다양한 교통수단을 이용해요","correct":true},{"t":"교통수단은 언제나 한 가지 까닭으로만 이용해요","mis":"SO3-2-u2-X22"},{"t":"하늘과 강, 바다에는 교통로가 없어요","mis":"SO3-2-u2-X21"},{"t":"교통은 물건만 옮기는 일이에요","mis":"SO3-2-u2-X20"}],"explanation":["교통로와 교통수단이에요.","필요에 따라 골라요.","다양하게 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_challenge#9','soc',3,2,'u2','L08','g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',4,'mc','auto','가족과 섬에 있는 친척 집에 가려고 해요. 바다를 건널 때 이용할 교통수단과 교통로를 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C8","difficulty":4,"kind":"mc","stem":"가족과 섬에 있는 친척 집에 가려고 해요. 바다를 건널 때 이용할 교통수단과 교통로를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"여객선 — 수로","correct":true},{"t":"여객선 — 철도","mis":"SO3-2-u2-X21"},{"t":"지하철 — 수로","mis":"SO3-2-u2-X21"},{"t":"고속버스 — 항공로","mis":"SO3-2-u2-X21"}],"explanation":["바다를 건너요.","배를 타요.","여객선과 수로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L08_challenge#10','soc',3,2,'u2','L08','g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',4,'essay','teacher','내가 최근에 이용한 교통수단 하나를 쓰고, 그 교통수단이 다니는 교통로와 이용한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C8","difficulty":4,"kind":"essay","stem":"내가 최근에 이용한 교통수단 하나를 쓰고, 그 교통수단이 다니는 교통로와 이용한 까닭을 쓰세요.","answer_guide":{"answer":"예: 지난 주말에 가족과 지하철을 탔어요. 지하철은 철도로 다녀요. 영화관이 먼 곳에 있어서 빠르게 가려고 이용했어요.","scoring_points":["교통수단을 썼는가","알맞은 교통로를 썼는가","이용한 까닭을 썼는가"]},"explanation":["교통수단을 떠올려요.","다니는 길을 써요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_basic#1','soc',3,2,'u2','L09','g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',1,'mc','auto','소나 말이 끄는 수레로, 무거운 짐을 옮길 때 이용한 옛날 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X23']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"mc","stem":"소나 말이 끄는 수레로, 무거운 짐을 옮길 때 이용한 옛날 교통수단은 무엇인가요?","options":[{"t":"달구지","correct":true},{"t":"가마","mis":"SO3-2-u2-X23"},{"t":"뗏목","mis":"SO3-2-u2-X23"},{"t":"돛단배","mis":"SO3-2-u2-X23"}],"explanation":["바퀴가 있어요.","소나 말이 끌어요.","달구지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_basic#2','soc',3,2,'u2','L09','g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',1,'sa','auto','사람을 태우고 가마꾼이 들어 옮긴 옛날 교통수단을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"sa","stem":"사람을 태우고 가마꾼이 들어 옮긴 옛날 교통수단을 두 글자로 쓰세요.","answer":["가마"],"explanation":["사람이 들어요.","가◯예요.","가마예요."],"mis":"SO3-2-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_basic#3','soc',3,2,'u2','L09','g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',1,'ox','auto','옛날 사람들은 주로 걸어서 이동했어요.',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"ox","stem":"옛날 사람들은 주로 걸어서 이동했어요.","answer":"O","reason_options":[{"t":"오늘날 같은 기계의 힘으로 움직이는 교통수단이 없었기 때문에","correct":true},{"t":"옛날에는 자동차가 아주 많았기 때문에","mis":"SO3-2-u2-X24"}],"mis":"SO3-2-u2-X24","explanation":["옛날에는 걸었어요.","말이나 배도 탔어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_basic#4','soc',3,2,'u2','L09','g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',1,'mc','auto','배에 바람의 힘을 이용하는 돛을 달고 강이나 바다를 건넌 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X23','SO3-2-u2-X25']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"mc","stem":"배에 바람의 힘을 이용하는 돛을 달고 강이나 바다를 건넌 교통수단은 무엇인가요?","options":[{"t":"돛단배","correct":true},{"t":"나룻배","mis":"SO3-2-u2-X23"},{"t":"뗏목","mis":"SO3-2-u2-X23"},{"t":"증기선","mis":"SO3-2-u2-X25"}],"explanation":["돛이 있어요.","바람을 받아요.","돛단배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_basic#5','soc',3,2,'u2','L09','g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',2,'match','auto','옛날 교통수단과 움직이는 힘을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"match","stem":"옛날 교통수단과 움직이는 힘을 알맞게 이으세요.","pairs":[{"l":"가마","r":"사람의 힘"},{"l":"달구지","r":"동물의 힘"},{"l":"돛단배","r":"바람의 힘"}],"mis":"SO3-2-u2-X24","explanation":["가마꾼이 들어요.","소가 끌어요.","바람을 받아요."],"asset":{"type":"passage","lines":["㉠ 말 — 먼 거리를 이동하거나 빨리 갈 때 탔어요.","㉡ 달구지 — 소나 말이 끄는 수레로 무거운 짐을 옮겼어요.","㉢ 가마 — 사람을 태우고 가마꾼이 들어 옮겼어요.","㉣ 뗏목 — 통나무를 이어 붙여 긴 막대기로 밀었어요.","㉤ 나룻배 — 노를 저어 강의 양쪽을 오갔어요.","㉥ 돛단배 — 돛을 달고 강이나 바다를 건넜어요."],"title":"옛날 교통수단 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_basic#6','soc',3,2,'u2','L09','g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',2,'mc','auto','옛날 교통수단을 만든 재료의 공통점은 무엇인가요?',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"mc","stem":"옛날 교통수단을 만든 재료의 공통점은 무엇인가요?","options":[{"t":"자연에서 쉽게 얻을 수 있는 재료","correct":true},{"t":"석유로 만든 재료","mis":"SO3-2-u2-X24"},{"t":"쇠로만 만든 재료","mis":"SO3-2-u2-X24"},{"t":"전기로 만든 재료","mis":"SO3-2-u2-X24"}],"explanation":["통나무를 떠올려요.","나무와 풀 줄기예요.","자연의 재료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_basic#7','soc',3,2,'u2','L09','g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',2,'blank','auto','증기 기차와 증기선은 물을 끓이면 생기는 (    )의 힘으로 움직여요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X25','SO3-2-u2-X24']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"blank","stem":"증기 기차와 증기선은 물을 끓이면 생기는 (    )의 힘으로 움직여요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"수증기","correct":true},{"t":"바람","mis":"SO3-2-u2-X25"},{"t":"사람","mis":"SO3-2-u2-X24"},{"t":"소","mis":"SO3-2-u2-X24"}],"explanation":["이름에 증기가 있어요.","물을 끓여요.","수증기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_basic#8','soc',3,2,'u2','L09','g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',2,'mc','auto','카드 가운데 노를 저어 강의 양쪽을 오간 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X23']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"mc","stem":"카드 가운데 노를 저어 강의 양쪽을 오간 교통수단은 무엇인가요?","options":[{"t":"㉤ 나룻배","correct":true},{"t":"㉣ 뗏목","mis":"SO3-2-u2-X23"},{"t":"㉥ 돛단배","mis":"SO3-2-u2-X23"},{"t":"㉡ 달구지","mis":"SO3-2-u2-X23"}],"explanation":["노를 저어요.","강을 건너요.","나룻배예요."],"asset":{"type":"passage","lines":["㉠ 말 — 먼 거리를 이동하거나 빨리 갈 때 탔어요.","㉡ 달구지 — 소나 말이 끄는 수레로 무거운 짐을 옮겼어요.","㉢ 가마 — 사람을 태우고 가마꾼이 들어 옮겼어요.","㉣ 뗏목 — 통나무를 이어 붙여 긴 막대기로 밀었어요.","㉤ 나룻배 — 노를 저어 강의 양쪽을 오갔어요.","㉥ 돛단배 — 돛을 달고 강이나 바다를 건넜어요."],"title":"옛날 교통수단 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_basic#9','soc',3,2,'u2','L09','g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',2,'ox','auto','옛날 교통수단은 모두 동물의 힘으로 움직였어요.',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"ox","stem":"옛날 교통수단은 모두 동물의 힘으로 움직였어요.","answer":"X","reason_options":[{"t":"가마는 사람, 돛단배는 바람의 힘으로도 움직였기 때문에","correct":true},{"t":"옛날에는 동물만 교통수단을 움직일 수 있었기 때문에","mis":"SO3-2-u2-X24"}],"mis":"SO3-2-u2-X24","explanation":["가마를 봐요.","사람이 들어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 말 — 먼 거리를 이동하거나 빨리 갈 때 탔어요.","㉡ 달구지 — 소나 말이 끄는 수레로 무거운 짐을 옮겼어요.","㉢ 가마 — 사람을 태우고 가마꾼이 들어 옮겼어요.","㉣ 뗏목 — 통나무를 이어 붙여 긴 막대기로 밀었어요.","㉤ 나룻배 — 노를 저어 강의 양쪽을 오갔어요.","㉥ 돛단배 — 돛을 달고 강이나 바다를 건넜어요."],"title":"옛날 교통수단 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_basic#10','soc',3,2,'u2','L09','g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',3,'mc','auto','과학 기술이 발달하면서 생겨난 교통수단은 무엇의 힘으로 움직이나요?',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"mc","stem":"과학 기술이 발달하면서 생겨난 교통수단은 무엇의 힘으로 움직이나요?","options":[{"t":"기계의 힘","correct":true},{"t":"사람의 힘","mis":"SO3-2-u2-X24"},{"t":"동물의 힘","mis":"SO3-2-u2-X24"},{"t":"바람의 힘","mis":"SO3-2-u2-X24"}],"explanation":["증기 기차와 자동차예요.","수증기·석유를 써요.","기계의 힘이에요."],"asset":{"type":"passage","lines":["㉮ 증기 기차","㉯ 증기선","㉰ 자동차","㉱ 프로펠러 비행기"],"title":"과학 기술이 발달하면서 생겨난 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_challenge#1','soc',3,2,'u2','L09','g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',2,'sa','auto','통나무 여러 개를 이어 붙여 만들어 사람이 긴 막대기로 밀어 강을 건넌 교통수단을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"sa","stem":"통나무 여러 개를 이어 붙여 만들어 사람이 긴 막대기로 밀어 강을 건넌 교통수단을 두 글자로 쓰세요.","answer":["뗏목"],"explanation":["통나무예요.","뗏◯이에요.","뗏목이에요."],"mis":"SO3-2-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_challenge#2','soc',3,2,'u2','L09','g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',2,'ox','auto','자동차와 비행기는 석유의 힘으로 움직여요.',ARRAY['SO3-2-u2-X25']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"ox","stem":"자동차와 비행기는 석유의 힘으로 움직여요.","answer":"O","reason_options":[{"t":"과학 기술이 발달하면서 석유를 쓰는 기계의 힘으로 움직이게 됐기 때문에","correct":true},{"t":"자동차와 비행기는 바람의 힘으로 움직이기 때문에","mis":"SO3-2-u2-X25"}],"mis":"SO3-2-u2-X25","explanation":["기계의 힘이에요.","석유를 써요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 증기 기차","㉯ 증기선","㉰ 자동차","㉱ 프로펠러 비행기"],"title":"과학 기술이 발달하면서 생겨난 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_challenge#3','soc',3,2,'u2','L09','g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',3,'mc','auto','자료의 새 교통수단 가운데 수증기의 힘으로 움직이는 것끼리 모은 것은 무엇인가요?',ARRAY['SO3-2-u2-X25']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"mc","stem":"자료의 새 교통수단 가운데 수증기의 힘으로 움직이는 것끼리 모은 것은 무엇인가요?","options":[{"t":"㉮, ㉯","correct":true},{"t":"㉰, ㉱","mis":"SO3-2-u2-X25"},{"t":"㉮, ㉰","mis":"SO3-2-u2-X25"},{"t":"㉯, ㉱","mis":"SO3-2-u2-X25"}],"explanation":["이름에 증기가 있어요.","기차와 배예요.","㉮, ㉯예요."],"asset":{"type":"passage","lines":["㉮ 증기 기차","㉯ 증기선","㉰ 자동차","㉱ 프로펠러 비행기"],"title":"과학 기술이 발달하면서 생겨난 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_challenge#4','soc',3,2,'u2','L09','g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',3,'mc','auto','옛날 사람들이 교통로로 이용한 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"mc","stem":"옛날 사람들이 교통로로 이용한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"사람들이 많이 다녀서 자연스럽게 생긴 길과 강","correct":true},{"t":"고속 국도와 철도","mis":"SO3-2-u2-X21"},{"t":"항공로","mis":"SO3-2-u2-X21"},{"t":"지하철 길","mis":"SO3-2-u2-X21"}],"explanation":["옛날 길이에요.","많이 다녀 생겼어요.","자연스럽게 생긴 길과 강이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_challenge#5','soc',3,2,'u2','L09','g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',3,'error','auto','옛날 교통수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X23']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"error","stem":"옛날 교통수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「뗏목은 바람의 힘을 받는 돛으로 움직였어.」","correct":true,"mis_target":"SO3-2-u2-X23"},{"t":"친구 가 — 「달구지로 무거운 짐을 옮겼어.」","mis":"SO3-2-u2-X23"},{"t":"친구 다 — 「먼 거리를 빨리 갈 때는 말을 탔어.」","mis":"SO3-2-u2-X23"}],"explanation":["뗏목을 봐요.","막대기로 밀었어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 말 — 먼 거리를 이동하거나 빨리 갈 때 탔어요.","㉡ 달구지 — 소나 말이 끄는 수레로 무거운 짐을 옮겼어요.","㉢ 가마 — 사람을 태우고 가마꾼이 들어 옮겼어요.","㉣ 뗏목 — 통나무를 이어 붙여 긴 막대기로 밀었어요.","㉤ 나룻배 — 노를 저어 강의 양쪽을 오갔어요.","㉥ 돛단배 — 돛을 달고 강이나 바다를 건넜어요."],"title":"옛날 교통수단 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_challenge#6','soc',3,2,'u2','L09','g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',3,'ox','auto','과학 기술이 발달해도 교통수단을 움직이는 힘은 그대로예요.',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"ox","stem":"과학 기술이 발달해도 교통수단을 움직이는 힘은 그대로예요.","answer":"X","reason_options":[{"t":"사람·동물·바람의 힘에서 기계의 힘으로 바뀌었기 때문에","correct":true},{"t":"교통수단은 언제나 사람의 힘으로만 움직이기 때문에","mis":"SO3-2-u2-X24"}],"mis":"SO3-2-u2-X24","explanation":["힘이 바뀌었어요.","기계의 힘이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_challenge#7','soc',3,2,'u2','L09','g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',3,'mc','auto','옛날 교통수단의 좋은 점으로 교과서에 나온 것은 무엇인가요?',ARRAY['SO3-2-u2-X24','SO3-2-u2-X25']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"mc","stem":"옛날 교통수단의 좋은 점으로 교과서에 나온 것은 무엇인가요?","options":[{"t":"환경이 오염되지 않아요","correct":true},{"t":"아주 빠르게 먼 곳까지 가요","mis":"SO3-2-u2-X24"},{"t":"한꺼번에 아주 많은 짐을 실어요","mis":"SO3-2-u2-X24"},{"t":"석유를 넣으면 오래 가요","mis":"SO3-2-u2-X25"}],"explanation":["연기가 나지 않아요.","연료를 넣지 않아요.","환경이 오염되지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_challenge#8','soc',3,2,'u2','L09','g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',4,'mc','auto','기계의 힘으로 움직이는 교통수단이 생기면서 달라진 생활로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X28','SO3-2-u2-X24']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C9","difficulty":4,"kind":"mc","stem":"기계의 힘으로 움직이는 교통수단이 생기면서 달라진 생활로 가장 알맞은 것은 무엇인가요?","options":[{"t":"더 먼 곳을 더 빠르고 편하게 이동하고, 더 많은 물건을 한꺼번에 옮길 수 있게 됐어요","correct":true},{"t":"교통수단이 느려지고 더 불편해졌어요","mis":"SO3-2-u2-X28"},{"t":"사람들이 늘 걸어서만 이동하게 됐어요","mis":"SO3-2-u2-X24"},{"t":"물건을 옮길 수 없게 됐어요","mis":"SO3-2-u2-X28"}],"explanation":["기계의 힘이에요.","빠르고 많이요.","더 멀리 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_challenge#9','soc',3,2,'u2','L09','g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',4,'mc','auto','옛날 교통수단과 과학 기술이 발달하며 생겨난 교통수단을 가장 바르게 견준 것은 무엇인가요?',ARRAY['SO3-2-u2-X24','SO3-2-u2-X25']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C9","difficulty":4,"kind":"mc","stem":"옛날 교통수단과 과학 기술이 발달하며 생겨난 교통수단을 가장 바르게 견준 것은 무엇인가요?","options":[{"t":"옛날 것은 사람·동물·바람의 힘으로, 새로 생긴 것은 기계의 힘으로 움직여요","correct":true},{"t":"옛날 것과 새로 생긴 것 모두 석유로 움직여요","mis":"SO3-2-u2-X24"},{"t":"옛날 것은 기계의 힘, 새로 생긴 것은 동물의 힘으로 움직여요","mis":"SO3-2-u2-X24"},{"t":"둘 다 바람의 힘으로만 움직여요","mis":"SO3-2-u2-X25"}],"explanation":["옛날은 자연의 힘이에요.","오늘은 기계예요.","견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L09_challenge#10','soc',3,2,'u2','L09','g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',4,'essay','teacher','카드의 옛날 교통수단 가운데 타 보고 싶은 것을 하나 골라 무엇의 힘으로 움직이는지 쓰고, 타 보고 싶은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C9","difficulty":4,"kind":"essay","stem":"카드의 옛날 교통수단 가운데 타 보고 싶은 것을 하나 골라 무엇의 힘으로 움직이는지 쓰고, 타 보고 싶은 까닭을 쓰세요.","answer_guide":{"answer":"예: 돛단배를 타 보고 싶어요. 돛단배는 바람의 힘으로 움직여요. 바람의 힘만으로 강이나 바다를 건너 보면 신기할 것 같아서예요.","scoring_points":["교통수단을 하나 골랐는가","움직이는 힘을 바르게 썼는가","타 보고 싶은 까닭을 썼는가"]},"explanation":["하나를 골라요.","힘을 써요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉠ 말 — 먼 거리를 이동하거나 빨리 갈 때 탔어요.","㉡ 달구지 — 소나 말이 끄는 수레로 무거운 짐을 옮겼어요.","㉢ 가마 — 사람을 태우고 가마꾼이 들어 옮겼어요.","㉣ 뗏목 — 통나무를 이어 붙여 긴 막대기로 밀었어요.","㉤ 나룻배 — 노를 저어 강의 양쪽을 오갔어요.","㉥ 돛단배 — 돛을 달고 강이나 바다를 건넜어요."],"title":"옛날 교통수단 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_basic#1','soc',3,2,'u2','L10','g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',1,'mc','auto','자동차에 연료를 넣기 위해 생긴 교통 시설은 무엇인가요?',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C10","difficulty":1,"kind":"mc","stem":"자동차에 연료를 넣기 위해 생긴 교통 시설은 무엇인가요?","options":[{"t":"주유소","correct":true},{"t":"정비소","mis":"SO3-2-u2-X26"},{"t":"휴게소","mis":"SO3-2-u2-X26"},{"t":"관제탑","mis":"SO3-2-u2-X26"}],"explanation":["연료를 넣어요.","기름을 넣는 곳이에요.","주유소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_basic#2','soc',3,2,'u2','L10','g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',1,'sa','auto','비행기가 달리다가 하늘로 떠오르고 내려앉는 긴 길을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C10","difficulty":1,"kind":"sa","stem":"비행기가 달리다가 하늘로 떠오르고 내려앉는 긴 길을 세 글자로 쓰세요.","answer":["활주로"],"explanation":["공항에 있어요.","활◯◯예요.","활주로예요."],"mis":"SO3-2-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_basic#3','soc',3,2,'u2','L10','g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',1,'ox','auto','오늘날 교통수단은 대부분 석유, 가스, 전기 등을 연료로 사용해요.',ARRAY['SO3-2-u2-X25']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C10","difficulty":1,"kind":"ox","stem":"오늘날 교통수단은 대부분 석유, 가스, 전기 등을 연료로 사용해요.","answer":"O","reason_options":[{"t":"오늘날 교통수단은 대부분 기계의 힘으로 움직이기 때문에","correct":true},{"t":"오늘날 교통수단은 대부분 동물의 힘으로 움직이기 때문에","mis":"SO3-2-u2-X25"}],"mis":"SO3-2-u2-X25","explanation":["기계의 힘이에요.","연료가 필요해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_basic#4','soc',3,2,'u2','L10','g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',1,'mc','auto','오늘날 땅 위를 다니는 교통수단이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X23']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C10","difficulty":1,"kind":"mc","stem":"오늘날 땅 위를 다니는 교통수단이 아닌 것은 무엇인가요?","options":[{"t":"달구지","correct":true},{"t":"버스","mis":"SO3-2-u2-X23"},{"t":"지하철","mis":"SO3-2-u2-X23"},{"t":"트럭","mis":"SO3-2-u2-X23"}],"explanation":["오늘날 것을 찾아요.","소가 끄는 수레예요.","달구지는 옛날 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_basic#5','soc',3,2,'u2','L10','g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',2,'match','auto','사람들의 말과 필요한 교통 시설을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"match","stem":"사람들의 말과 필요한 교통 시설을 알맞게 이으세요.","pairs":[{"l":"가","r":"주유소"},{"l":"나","r":"자동차 정비소"},{"l":"다","r":"활주로"},{"l":"라","r":"등대"}],"mis":"SO3-2-u2-X26","explanation":["연료는 주유소예요.","수리는 정비소예요.","비행기와 배도 이어요."],"asset":{"type":"speech","turns":[{"who":"가","text":"자동차에 연료를 넣고 싶어요."},{"who":"나","text":"고장 난 자동차를 수리하고 싶어요."},{"who":"다","text":"비행기가 뜨고 내려야 해요."},{"who":"라","text":"배가 바다에서 안전하게 다니도록 알려 줘야 해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_basic#6','soc',3,2,'u2','L10','g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',2,'mc','auto','비행기가 다닐 수 있도록 신호를 알려 주는 교통 시설은 무엇인가요?',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"mc","stem":"비행기가 다닐 수 있도록 신호를 알려 주는 교통 시설은 무엇인가요?","options":[{"t":"관제탑","correct":true},{"t":"등대","mis":"SO3-2-u2-X26"},{"t":"주유소","mis":"SO3-2-u2-X26"},{"t":"휴게소","mis":"SO3-2-u2-X26"}],"explanation":["공항에 있어요.","신호를 알려요.","관제탑이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_basic#7','soc',3,2,'u2','L10','g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',2,'blank','auto','고속 국도를 지나다가 잠시 쉬고 간단하게 식사도 할 수 있는 (    )가 생겼어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"blank","stem":"고속 국도를 지나다가 잠시 쉬고 간단하게 식사도 할 수 있는 (    )가 생겼어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"휴게소","correct":true},{"t":"관제탑","mis":"SO3-2-u2-X26"},{"t":"활주로","mis":"SO3-2-u2-X26"},{"t":"등대","mis":"SO3-2-u2-X26"}],"explanation":["쉬는 곳이에요.","고속 국도에 있어요.","휴게소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_basic#8','soc',3,2,'u2','L10','g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',2,'mc','auto','배가 항구에서 나갈 때 빨간색 등대를 보았다면 어떻게 다녀야 하나요?',ARRAY['SO3-2-u2-X27']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"mc","stem":"배가 항구에서 나갈 때 빨간색 등대를 보았다면 어떻게 다녀야 하나요?","options":[{"t":"오른쪽으로 다녀요","correct":true},{"t":"왼쪽으로 다녀요","mis":"SO3-2-u2-X27"},{"t":"그 자리에 멈춰요","mis":"SO3-2-u2-X27"},{"t":"아무 쪽으로나 다녀요","mis":"SO3-2-u2-X27"}],"explanation":["빨간색 등대예요.","왼쪽에 장애물이 있어요.","오른쪽으로 다녀요."],"asset":{"type":"passage","lines":["빨간색 등대 — 왼쪽에 장애물이 있으니 오른쪽으로 다녀요.","흰색 등대 — 오른쪽에 장애물이 있으니 왼쪽으로 다녀요."],"title":"배가 항구에서 나갈 때 등대의 뜻"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_basic#9','soc',3,2,'u2','L10','g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',2,'ox','auto','교통 시설은 땅 위에만 있고 하늘과 바다에는 없어요.',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"ox","stem":"교통 시설은 땅 위에만 있고 하늘과 바다에는 없어요.","answer":"X","reason_options":[{"t":"활주로, 관제탑, 등대처럼 하늘과 바다에도 교통 시설이 있기 때문에","correct":true},{"t":"하늘과 바다에는 교통수단이 다니지 않기 때문에","mis":"SO3-2-u2-X26"}],"mis":"SO3-2-u2-X26","explanation":["공항을 떠올려요.","항구도 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_basic#10','soc',3,2,'u2','L10','g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',3,'mc','auto','교통 신호나 약속이 생겨난 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X27']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"mc","stem":"교통 신호나 약속이 생겨난 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"교통수단과 교통 시설이 다양해지고 이용하는 사람이 많아져 안전이 중요해졌기 때문이에요","correct":true},{"t":"교통수단이 모두 사라졌기 때문이에요","mis":"SO3-2-u2-X27"},{"t":"사람들이 교통수단을 이용하지 않기 때문이에요","mis":"SO3-2-u2-X27"},{"t":"옛날 교통수단만 이용하기 때문이에요","mis":"SO3-2-u2-X27"}],"explanation":["길에 사람이 많아요.","교통수단도 많아요.","안전을 위해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_challenge#1','soc',3,2,'u2','L10','g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',2,'sa','auto','배가 바다에서 안전하게 다닐 수 있도록 불빛으로 알려 주는 교통 시설을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"sa","stem":"배가 바다에서 안전하게 다닐 수 있도록 불빛으로 알려 주는 교통 시설을 두 글자로 쓰세요.","answer":["등대"],"explanation":["바닷가에 서 있어요.","등◯예요.","등대예요."],"mis":"SO3-2-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_challenge#2','soc',3,2,'u2','L10','g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',2,'ox','auto','나라마다 자연환경과 생활 모습이 달라서 사람들이 이용하는 교통수단의 모습도 다양해요.',ARRAY['SO3-2-u2-X22']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"ox","stem":"나라마다 자연환경과 생활 모습이 달라서 사람들이 이용하는 교통수단의 모습도 다양해요.","answer":"O","reason_options":[{"t":"땅이 부족하면 공중에 매달린 전동차를, 물길이 많으면 배를 이용하는 것처럼 환경에 맞추기 때문에","correct":true},{"t":"세계의 교통수단은 모두 똑같기 때문에","mis":"SO3-2-u2-X22"}],"mis":"SO3-2-u2-X22","explanation":["나라마다 달라요.","환경에 맞춰요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_challenge#3','soc',3,2,'u2','L10','g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',3,'mc','auto','흰색 등대가 뜻하는 것은 무엇인가요?',ARRAY['SO3-2-u2-X27']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"mc","stem":"흰색 등대가 뜻하는 것은 무엇인가요?","options":[{"t":"오른쪽에 장애물이 있으니 왼쪽으로 다녀요","correct":true},{"t":"왼쪽에 장애물이 있으니 오른쪽으로 다녀요","mis":"SO3-2-u2-X27"},{"t":"멈추라는 표시예요","mis":"SO3-2-u2-X27"},{"t":"기차가 지나간다는 표시예요","mis":"SO3-2-u2-X27"}],"explanation":["빨간색과 반대예요.","오른쪽에 장애물이에요.","왼쪽으로 다녀요."],"asset":{"type":"passage","lines":["빨간색 등대 — 왼쪽에 장애물이 있으니 오른쪽으로 다녀요.","흰색 등대 — 오른쪽에 장애물이 있으니 왼쪽으로 다녀요."],"title":"배가 항구에서 나갈 때 등대의 뜻"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_challenge#4','soc',3,2,'u2','L10','g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',3,'mc','auto','하늘과 바다를 다니는 교통수단이 발달하면서 달라진 생활 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"mc","stem":"하늘과 바다를 다니는 교통수단이 발달하면서 달라진 생활 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"먼 나라로 여행하거나 섬을 오가는 일이 쉬워졌어요","correct":true},{"t":"섬을 오가는 일이 더 어려워졌어요","mis":"SO3-2-u2-X28"},{"t":"많은 짐을 한꺼번에 옮길 수 없게 됐어요","mis":"SO3-2-u2-X28"},{"t":"다른 나라로 물건을 보낼 수 없게 됐어요","mis":"SO3-2-u2-X28"}],"explanation":["비행기와 배가 커졌어요.","빨라졌어요.","먼 곳이 쉬워졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_challenge#5','soc',3,2,'u2','L10','g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',3,'error','auto','교통 시설을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"error","stem":"교통 시설을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「크레인은 비행기에 연료를 넣는 시설이야.」","correct":true,"mis_target":"SO3-2-u2-X26"},{"t":"친구 나 — 「크레인으로 큰 화물들을 들어 화물선에 실어.」","mis":"SO3-2-u2-X26"},{"t":"친구 다 — 「기차를 타려면 기차역에 가.」","mis":"SO3-2-u2-X26"}],"explanation":["크레인을 봐요.","화물을 들어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_challenge#6','soc',3,2,'u2','L10','g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',3,'mc','auto','철도를 만들 땅이 부족해 생겨난 것으로, 공중에 매달려 다니는 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X22','SO3-2-u2-X23']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"mc","stem":"철도를 만들 땅이 부족해 생겨난 것으로, 공중에 매달려 다니는 교통수단은 무엇인가요?","options":[{"t":"공중에 매달려 다니는 전동차","correct":true},{"t":"오토바이로 만든 세 발 택시","mis":"SO3-2-u2-X22"},{"t":"물길을 따라 이동하는 배","mis":"SO3-2-u2-X22"},{"t":"소가 끄는 달구지","mis":"SO3-2-u2-X23"}],"explanation":["땅이 부족해요.","공중으로 다녀요.","매달린 전동차예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_challenge#7','soc',3,2,'u2','L10','g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',3,'ox','auto','교통수단이 다양해져도 필요한 교통 시설은 옛날과 똑같아요.',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"ox","stem":"교통수단이 다양해져도 필요한 교통 시설은 옛날과 똑같아요.","answer":"X","reason_options":[{"t":"자동차가 생기며 주유소, 비행기가 생기며 활주로처럼 새 시설이 필요해졌기 때문에","correct":true},{"t":"교통 시설은 옛날부터 하나도 바뀌지 않았기 때문에","mis":"SO3-2-u2-X26"}],"mis":"SO3-2-u2-X26","explanation":["새 교통수단이 생겼어요.","새 시설이 필요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_challenge#8','soc',3,2,'u2','L10','g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',4,'mc','auto','「오늘날의 교통수단과 교통 시설」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X26','SO3-2-u2-X27']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C10","difficulty":4,"kind":"mc","stem":"「오늘날의 교통수단과 교통 시설」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"교통수단이 다양해지면서 교통 시설이 새로 생기고 안전을 위한 신호와 약속도 생겼어요","correct":true},{"t":"교통 시설은 교통수단과 아무 관계가 없어요","mis":"SO3-2-u2-X26"},{"t":"교통수단이 다양해지면서 신호와 약속은 모두 없어졌어요","mis":"SO3-2-u2-X27"},{"t":"교통수단을 이용하는 사람이 줄어 교통 시설이 필요 없어졌어요","mis":"SO3-2-u2-X26"}],"explanation":["교통수단이 다양해졌어요.","시설이 생겼어요.","신호와 약속도요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_challenge#9','soc',3,2,'u2','L10','g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',4,'mc','auto','어떤 사람이 「다른 나라의 관광지로 여행을 가려고 해요」라고 말했어요. 이 사람이 이용할 교통수단과 교통 시설을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C10","difficulty":4,"kind":"mc","stem":"어떤 사람이 「다른 나라의 관광지로 여행을 가려고 해요」라고 말했어요. 이 사람이 이용할 교통수단과 교통 시설을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"비행기 — 활주로","correct":true},{"t":"비행기 — 주유소","mis":"SO3-2-u2-X26"},{"t":"잠수함 — 기차역","mis":"SO3-2-u2-X26"},{"t":"버스 — 등대","mis":"SO3-2-u2-X26"}],"explanation":["먼 나라예요.","하늘로 가요.","비행기와 활주로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L10_challenge#10','soc',3,2,'u2','L10','g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',4,'essay','teacher','사람들의 말 가운데 하나를 골라 필요한 교통 시설을 쓰고, 그 시설이 생기면서 교통수단을 이용하는 모습이 어떻게 편리해졌는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C10","difficulty":4,"kind":"essay","stem":"사람들의 말 가운데 하나를 골라 필요한 교통 시설을 쓰고, 그 시설이 생기면서 교통수단을 이용하는 모습이 어떻게 편리해졌는지 쓰세요.","answer_guide":{"answer":"예: 「다」는 비행기가 뜨고 내려야 한다고 했어요. 그래서 활주로가 생겼어요. 활주로 덕분에 비행기를 타고 먼 나라까지 빠르게 여행할 수 있게 됐어요.","scoring_points":["말 하나를 골랐는가","알맞은 교통 시설을 썼는가","편리해진 모습을 썼는가"]},"explanation":["말을 골라요.","시설을 써요.","편리해진 점을 써요."],"asset":{"type":"speech","turns":[{"who":"가","text":"자동차에 연료를 넣고 싶어요."},{"who":"나","text":"고장 난 자동차를 수리하고 싶어요."},{"who":"다","text":"비행기가 뜨고 내려야 해요."},{"who":"라","text":"배가 바다에서 안전하게 다니도록 알려 줘야 해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_basic#1','soc',3,2,'u2','L11','g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',1,'mc','auto','일정표에서 옛날 선비가 먼 길을 가는 데 걸린 시간은 얼마 정도인가요?',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C11","difficulty":1,"kind":"mc","stem":"일정표에서 옛날 선비가 먼 길을 가는 데 걸린 시간은 얼마 정도인가요?","options":[{"t":"15일 정도","correct":true},{"t":"반나절 정도","mis":"SO3-2-u2-X28"},{"t":"한 시간 정도","mis":"SO3-2-u2-X28"},{"t":"하루 정도","mis":"SO3-2-u2-X28"}],"explanation":["9월 1일에 출발했어요.","9월 15일에 도착했어요.","15일 정도예요."],"asset":{"type":"passage","lines":["옛날 선비 — 9월 1일 출발, 걸어서 → 말을 타고 → 나룻배를 타고 → 9월 15일 도착","오늘날 어린이 — 오전 6시 출발, 지하철 → 고속 열차 → 버스 → 낮 12시 도착","(두 사람 모두 같은 두 곳 사이를 이동했어요.)"],"title":"옛날과 오늘날의 먼 길 일정표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_basic#2','soc',3,2,'u2','L11','g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',1,'sa','auto','항구에 들어오는 큰 배에 타서 배들이 안전하게 항구를 드나들도록 안내하는 직업을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C11","difficulty":1,"kind":"sa","stem":"항구에 들어오는 큰 배에 타서 배들이 안전하게 항구를 드나들도록 안내하는 직업을 세 글자로 쓰세요.","answer":["도선사"],"explanation":["배를 안내해요.","도◯◯예요.","도선사예요."],"mis":"SO3-2-u2-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_basic#3','soc',3,2,'u2','L11','g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',1,'ox','auto','교통이 발달하면서 더 먼 곳으로 편하고 빠르게 이동할 수 있게 됐어요.',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C11","difficulty":1,"kind":"ox","stem":"교통이 발달하면서 더 먼 곳으로 편하고 빠르게 이동할 수 있게 됐어요.","answer":"O","reason_options":[{"t":"고속 열차처럼 빠른 교통수단이 생겼기 때문에","correct":true},{"t":"교통이 발달해도 이동 시간은 똑같기 때문에","mis":"SO3-2-u2-X28"}],"mis":"SO3-2-u2-X28","explanation":["일정표를 견줘요.","반나절이면 가요.","그래서 O예요."],"asset":{"type":"passage","lines":["옛날 선비 — 9월 1일 출발, 걸어서 → 말을 타고 → 나룻배를 타고 → 9월 15일 도착","오늘날 어린이 — 오전 6시 출발, 지하철 → 고속 열차 → 버스 → 낮 12시 도착","(두 사람 모두 같은 두 곳 사이를 이동했어요.)"],"title":"옛날과 오늘날의 먼 길 일정표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_basic#4','soc',3,2,'u2','L11','g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',1,'mc','auto','교통의 변화로 거의 사라진 직업은 무엇인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C11","difficulty":1,"kind":"mc","stem":"교통의 변화로 거의 사라진 직업은 무엇인가요?","options":[{"t":"가마꾼","correct":true},{"t":"철도 기관사","mis":"SO3-2-u2-X29"},{"t":"항공기 조종사","mis":"SO3-2-u2-X29"},{"t":"해양 경찰관","mis":"SO3-2-u2-X29"}],"explanation":["옛날 교통수단이에요.","가마를 들었어요.","가마꾼이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_basic#5','soc',3,2,'u2','L11','g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',2,'match','auto','옛날 교통수단과 오늘날 교통수단을 견주어 달라진 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"match","stem":"옛날 교통수단과 오늘날 교통수단을 견주어 달라진 점을 알맞게 이으세요.","pairs":[{"l":"말 → 고속 열차","r":"먼 곳까지 더 빠르고 편하게"},{"l":"돛단배 → 여객선","r":"가기 어려웠던 곳에 쉽고 빠르게"},{"l":"달구지 → 트럭","r":"더 많은 짐을 먼 곳까지"}],"mis":"SO3-2-u2-X28","explanation":["말은 빠르기예요.","배는 가기 어려운 곳이에요.","달구지는 짐이에요."],"asset":{"type":"passage","lines":["말 → 고속 열차","돛단배 → 여객선","달구지 → 트럭"],"title":"옛날과 오늘날의 교통수단 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_basic#6','soc',3,2,'u2','L11','g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',2,'mc','auto','오늘날 말이나 달구지를 이용하는 모습을 보기 힘든 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"mc","stem":"오늘날 말이나 달구지를 이용하는 모습을 보기 힘든 까닭은 무엇인가요?","options":[{"t":"더 편리하고 빠른 교통수단이 생겼기 때문이에요","correct":true},{"t":"말과 달구지가 모두 사라졌기 때문이에요","mis":"SO3-2-u2-X28"},{"t":"사람들이 먼 곳으로 이동하지 않기 때문이에요","mis":"SO3-2-u2-X28"},{"t":"길이 모두 없어졌기 때문이에요","mis":"SO3-2-u2-X28"}],"explanation":["오늘날 길을 봐요.","버스와 지하철이 있어요.","더 편리한 것이 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_basic#7','soc',3,2,'u2','L11','g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',2,'blank','auto','교통의 발달로 사람들의 생활 (    )이 더욱 넓어졌어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"blank","stem":"교통의 발달로 사람들의 생활 (    )이 더욱 넓어졌어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"공간","correct":true},{"t":"시간","mis":"SO3-2-u2-X28"},{"t":"규칙","mis":"SO3-2-u2-X28"},{"t":"명절","mis":"SO3-2-u2-X28"}],"explanation":["오가는 곳이 넓어요.","생활 ◯◯이에요.","공간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_basic#8','soc',3,2,'u2','L11','g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',2,'mc','auto','자료에서 바다와 관련 있는 오늘날의 직업이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"mc","stem":"자료에서 바다와 관련 있는 오늘날의 직업이 아닌 것은 무엇인가요?","options":[{"t":"항공 정비사","correct":true},{"t":"해양 경찰관","mis":"SO3-2-u2-X29"},{"t":"등대 관리원","mis":"SO3-2-u2-X29"},{"t":"선장","mis":"SO3-2-u2-X29"}],"explanation":["바다 줄을 봐요.","항공은 하늘이에요.","항공 정비사가 아니에요."],"asset":{"type":"passage","lines":["땅 위 — 철도 기관사, 자동차 정비사, 지하철 역무원, 버스 운전기사","하늘 — 항공기 조종사, 공항 안전 요원, 항공 정비사","바다 — 해양 경찰관, 등대 관리원, 도선사, 선장"],"title":"교통과 관련 있는 오늘날의 직업"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_basic#9','soc',3,2,'u2','L11','g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',2,'ox','auto','교통이 변해도 사람들이 하는 일은 옛날과 똑같아요.',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"ox","stem":"교통이 변해도 사람들이 하는 일은 옛날과 똑같아요.","answer":"X","reason_options":[{"t":"가마꾼처럼 사라진 직업도 있고 항공기 조종사처럼 새로 생긴 직업도 있기 때문에","correct":true},{"t":"직업은 교통과 아무 관계가 없기 때문에","mis":"SO3-2-u2-X29"}],"mis":"SO3-2-u2-X29","explanation":["직업이 바뀌었어요.","사라지고 생겼어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_basic#10','soc',3,2,'u2','L11','g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',3,'mc','auto','이동에 불편을 겪는 사람도 안전하고 편하게 이동하도록 돕는 오늘날의 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X23']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"mc","stem":"이동에 불편을 겪는 사람도 안전하고 편하게 이동하도록 돕는 오늘날의 교통수단은 무엇인가요?","options":[{"t":"교통 약자 택시","correct":true},{"t":"가마","mis":"SO3-2-u2-X23"},{"t":"달구지","mis":"SO3-2-u2-X23"},{"t":"뗏목","mis":"SO3-2-u2-X23"}],"explanation":["오늘날 생겼어요.","불편한 사람을 도와요.","교통 약자 택시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_challenge#1','soc',3,2,'u2','L11','g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',2,'sa','auto','일정표에서 오늘날 어린이가 이용한 교통수단 가운데 가장 먼 길을 빠르게 달린 것을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"sa","stem":"일정표에서 오늘날 어린이가 이용한 교통수단 가운데 가장 먼 길을 빠르게 달린 것을 쓰세요.","answer":["고속 열차","고속열차"],"explanation":["지하철과 버스 사이예요.","고속 ◯◯예요.","고속 열차예요."],"asset":{"type":"passage","lines":["옛날 선비 — 9월 1일 출발, 걸어서 → 말을 타고 → 나룻배를 타고 → 9월 15일 도착","오늘날 어린이 — 오전 6시 출발, 지하철 → 고속 열차 → 버스 → 낮 12시 도착","(두 사람 모두 같은 두 곳 사이를 이동했어요.)"],"title":"옛날과 오늘날의 먼 길 일정표"},"mis":"SO3-2-u2-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_challenge#2','soc',3,2,'u2','L11','g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',2,'ox','auto','트럭을 이용하면 달구지보다 더 많은 짐을 싣고 더 먼 곳까지 이동할 수 있어요.',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"ox","stem":"트럭을 이용하면 달구지보다 더 많은 짐을 싣고 더 먼 곳까지 이동할 수 있어요.","answer":"O","reason_options":[{"t":"트럭은 기계의 힘으로 움직여 한 번에 많이, 멀리 갈 수 있기 때문에","correct":true},{"t":"트럭은 달구지보다 짐을 적게 싣기 때문에","mis":"SO3-2-u2-X28"}],"mis":"SO3-2-u2-X28","explanation":["기계의 힘이에요.","짐이 많아요.","그래서 O예요."],"asset":{"type":"passage","lines":["말 → 고속 열차","돛단배 → 여객선","달구지 → 트럭"],"title":"옛날과 오늘날의 교통수단 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_challenge#3','soc',3,2,'u2','L11','g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',3,'mc','auto','일정표의 두 사람을 견주어 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X28','SO3-2-u2-X23']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"mc","stem":"일정표의 두 사람을 견주어 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"교통이 발달하면서 같은 거리를 훨씬 짧은 시간에 이동하게 됐어요","correct":true},{"t":"교통수단이 많아질수록 이동 시간이 더 오래 걸려요","mis":"SO3-2-u2-X28"},{"t":"옛날 사람들은 한 가지 교통수단만 이용했어요","mis":"SO3-2-u2-X23"},{"t":"두 사람이 걸린 시간은 비슷해요","mis":"SO3-2-u2-X28"}],"explanation":["15일과 반나절이에요.","훨씬 빨라졌어요.","짧은 시간이에요."],"asset":{"type":"passage","lines":["옛날 선비 — 9월 1일 출발, 걸어서 → 말을 타고 → 나룻배를 타고 → 9월 15일 도착","오늘날 어린이 — 오전 6시 출발, 지하철 → 고속 열차 → 버스 → 낮 12시 도착","(두 사람 모두 같은 두 곳 사이를 이동했어요.)"],"title":"옛날과 오늘날의 먼 길 일정표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_challenge#4','soc',3,2,'u2','L11','g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',3,'mc','auto','교통의 발달로 생활 공간이 넓어진 모습으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"mc","stem":"교통의 발달로 생활 공간이 넓어진 모습으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"집 가까운 곳에서만 지내고 먼 곳에는 가지 못해요","correct":true},{"t":"버스를 타고 먼 곳에 있는 직장에 다녀요","mis":"SO3-2-u2-X28"},{"t":"세계 여러 곳에서 만든 물건을 쉽게 구해요","mis":"SO3-2-u2-X28"},{"t":"다른 나라로 여행하는 사람이 많아졌어요","mis":"SO3-2-u2-X28"}],"explanation":["넓어지면 멀리 가요.","알맞지 않은 것을 찾아요.","가까운 곳만은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_challenge#5','soc',3,2,'u2','L11','g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',3,'error','auto','교통과 직업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"error","stem":"교통과 직업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「뱃사공은 교통의 변화로 새로 생긴 직업이야.」","correct":true,"mis_target":"SO3-2-u2-X29"},{"t":"친구 가 — 「철도 기관사는 열차를 운전해.」","mis":"SO3-2-u2-X29"},{"t":"친구 나 — 「가마꾼은 거의 사라졌어.」","mis":"SO3-2-u2-X29"}],"explanation":["뱃사공을 봐요.","거의 사라졌어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_challenge#6','soc',3,2,'u2','L11','g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',3,'mc','auto','도선사가 꼭 필요한 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X29','SO3-2-u2-X26']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"mc","stem":"도선사가 꼭 필요한 까닭은 무엇인가요?","options":[{"t":"항구의 바닷속 장애물이나 물의 흐름을 모르면 큰 배가 위험에 빠질 수 있기 때문이에요","correct":true},{"t":"배가 너무 느리게 가기 때문이에요","mis":"SO3-2-u2-X29"},{"t":"배에 연료를 넣어야 하기 때문이에요","mis":"SO3-2-u2-X26"},{"t":"비행기가 항구에 내리기 때문이에요","mis":"SO3-2-u2-X29"}],"explanation":["항구가 위험할 수 있어요.","바닷속을 알아야 해요.","그래서 안내해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_challenge#7','soc',3,2,'u2','L11','g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',3,'ox','auto','교통이 발달하면서 사람들의 생활 공간이 더욱 좁아졌어요.',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"ox","stem":"교통이 발달하면서 사람들의 생활 공간이 더욱 좁아졌어요.","answer":"X","reason_options":[{"t":"먼 곳의 직장과 학교에 다니고 먼 곳으로 여행을 가게 됐기 때문에","correct":true},{"t":"교통이 발달하면 집 밖에 나가지 않게 되기 때문에","mis":"SO3-2-u2-X28"}],"mis":"SO3-2-u2-X28","explanation":["멀리 다녀요.","넓어졌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_challenge#8','soc',3,2,'u2','L11','g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',4,'mc','auto','「교통의 변화로 달라진 생활」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X28','SO3-2-u2-X29']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C11","difficulty":4,"kind":"mc","stem":"「교통의 변화로 달라진 생활」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"교통이 발달하면서 먼 곳까지 빠르게 가고, 생활 공간이 넓어지고, 새로운 직업도 생겼어요","correct":true},{"t":"교통이 발달해도 이동하는 데 걸리는 시간은 옛날과 똑같아요","mis":"SO3-2-u2-X28"},{"t":"교통이 발달하면서 생활 공간이 좁아졌어요","mis":"SO3-2-u2-X28"},{"t":"교통이 변해도 직업은 하나도 달라지지 않았어요","mis":"SO3-2-u2-X29"}],"explanation":["빨라졌어요.","넓어졌어요.","직업도 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_challenge#9','soc',3,2,'u2','L11','g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',4,'mc','auto','항공기 조종사, 해양 경찰관, 철도 기관사가 공통으로 보여 주는 것은 무엇인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C11","difficulty":4,"kind":"mc","stem":"항공기 조종사, 해양 경찰관, 철도 기관사가 공통으로 보여 주는 것은 무엇인가요?","options":[{"t":"교통의 변화로 옛날에 없던 직업이 새로 생겼어요","correct":true},{"t":"교통의 변화로 모든 직업이 사라졌어요","mis":"SO3-2-u2-X29"},{"t":"옛날부터 있던 직업만 남았어요","mis":"SO3-2-u2-X29"},{"t":"교통과 관계없는 직업이에요","mis":"SO3-2-u2-X29"}],"explanation":["옛날에는 없었어요.","비행기·열차·바다예요.","새로 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L11_challenge#10','soc',3,2,'u2','L11','g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',4,'essay','teacher','일정표의 두 사람을 견주어 이용한 교통수단과 걸린 시간이 어떻게 다른지 쓰고, 교통의 발달로 달라진 생활 모습을 하나 더 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C11","difficulty":4,"kind":"essay","stem":"일정표의 두 사람을 견주어 이용한 교통수단과 걸린 시간이 어떻게 다른지 쓰고, 교통의 발달로 달라진 생활 모습을 하나 더 쓰세요.","answer_guide":{"answer":"예: 옛날 선비는 걸어서, 말을 타고, 나룻배를 타고 15일 정도 걸렸지만 오늘날 어린이는 지하철, 고속 열차, 버스로 반나절 만에 갔어요. 교통의 발달로 먼 곳에 있는 직장이나 학교에도 다닐 수 있게 됐어요.","scoring_points":["교통수단의 차이를 썼는가","걸린 시간의 차이를 썼는가","달라진 생활 모습을 더 썼는가"]},"explanation":["교통수단을 견줘요.","시간을 견줘요.","생활 모습을 더 써요."],"asset":{"type":"passage","lines":["옛날 선비 — 9월 1일 출발, 걸어서 → 말을 타고 → 나룻배를 타고 → 9월 15일 도착","오늘날 어린이 — 오전 6시 출발, 지하철 → 고속 열차 → 버스 → 낮 12시 도착","(두 사람 모두 같은 두 곳 사이를 이동했어요.)"],"title":"옛날과 오늘날의 먼 길 일정표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_basic#1','soc',3,2,'u2','L12','g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',1,'mc','auto','차가 너무 많이 모여 도로가 막히는 일을 무엇이라고 하나요?',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C12","difficulty":1,"kind":"mc","stem":"차가 너무 많이 모여 도로가 막히는 일을 무엇이라고 하나요?","options":[{"t":"교통 체증","correct":true},{"t":"교통 약자","mis":"SO3-2-u2-X30"},{"t":"교통 시설","mis":"SO3-2-u2-X30"},{"t":"교통안전","mis":"SO3-2-u2-X30"}],"explanation":["차가 많아요.","길이 막혀요.","교통 체증이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_basic#2','soc',3,2,'u2','L12','g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',1,'sa','auto','어린이의 안전을 지키려고 자동차가 천천히 다니도록 정한 곳을 「어린이 ○○ 구역」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C12","difficulty":1,"kind":"sa","stem":"어린이의 안전을 지키려고 자동차가 천천히 다니도록 정한 곳을 「어린이 ○○ 구역」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["보호"],"explanation":["어린이를 지켜요.","◯호예요.","보호예요."],"mis":"SO3-2-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_basic#3','soc',3,2,'u2','L12','g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',1,'ox','auto','스마트폰을 보면서 길을 걸어가지 않아야 해요.',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C12","difficulty":1,"kind":"ox","stem":"스마트폰을 보면서 길을 걸어가지 않아야 해요.","answer":"O","reason_options":[{"t":"화면만 보면 다가오는 차를 보지 못해 사고가 날 수 있기 때문에","correct":true},{"t":"스마트폰을 보면 길을 더 잘 볼 수 있기 때문에","mis":"SO3-2-u2-X31"}],"mis":"SO3-2-u2-X31","explanation":["화면만 봐요.","차를 못 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_basic#4','soc',3,2,'u2','L12','g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',1,'mc','auto','친환경 에너지를 사용하는 교통수단을 이용하면 무엇을 줄일 수 있나요?',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C12","difficulty":1,"kind":"mc","stem":"친환경 에너지를 사용하는 교통수단을 이용하면 무엇을 줄일 수 있나요?","options":[{"t":"환경 오염","correct":true},{"t":"이동 거리","mis":"SO3-2-u2-X30"},{"t":"버스 정류장","mis":"SO3-2-u2-X30"},{"t":"교통수단의 종류","mis":"SO3-2-u2-X30"}],"explanation":["공기를 더럽히지 않아요.","깨끗해요.","환경 오염이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_basic#5','soc',3,2,'u2','L12','g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',2,'match','auto','매듭의 문제점과 그것을 푸는 노력을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"match","stem":"매듭의 문제점과 그것을 푸는 노력을 알맞게 이으세요.","pairs":[{"l":"㉠ 길이 막혀요","r":"가. 막히는 길 정보 알리기"},{"l":"㉢ 대기 오염","r":"나. 친환경 에너지 사용"},{"l":"㉣ 주차할 곳 부족","r":"다. 새 주차 시설"},{"l":"㉡ 사고","r":"라. 교통안전 수칙"}],"mis":"SO3-2-u2-X30","explanation":["막힘은 정보예요.","오염은 친환경이에요.","주차와 사고도 이어요."],"asset":{"type":"passage","lines":["㉠ 먼 곳까지 이동할 수 있지만, 차가 너무 많이 모여 길이 막히기도 해요.","㉡ 빠르게 이동할 수 있지만, 사고가 일어나기도 해요.","㉢ 다양한 교통수단을 이용할 수 있지만, 대기 오염과 소음 문제가 일어나기도 해요.","㉣ 가고 싶은 곳으로 편하게 갈 수 있지만, 주차할 곳이 부족할 때가 있어요."],"title":"교통의 변화로 생긴 매듭 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_basic#6','soc',3,2,'u2','L12','g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',2,'mc','auto','다양한 교통수단을 이용할 수 있게 됐지만 함께 생긴 문제점은 무엇인가요?',ARRAY['SO3-2-u2-X30','SO3-2-u2-X32']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"mc","stem":"다양한 교통수단을 이용할 수 있게 됐지만 함께 생긴 문제점은 무엇인가요?","options":[{"t":"대기 오염과 소음 문제","correct":true},{"t":"자전거 도로가 늘어난 것","mis":"SO3-2-u2-X30"},{"t":"길이 모두 없어진 것","mis":"SO3-2-u2-X32"},{"t":"교통수단이 줄어든 것","mis":"SO3-2-u2-X32"}],"explanation":["공기와 소리예요.","교통수단이 많아요.","대기 오염과 소음이에요."],"asset":{"type":"passage","lines":["㉠ 먼 곳까지 이동할 수 있지만, 차가 너무 많이 모여 길이 막히기도 해요.","㉡ 빠르게 이동할 수 있지만, 사고가 일어나기도 해요.","㉢ 다양한 교통수단을 이용할 수 있지만, 대기 오염과 소음 문제가 일어나기도 해요.","㉣ 가고 싶은 곳으로 편하게 갈 수 있지만, 주차할 곳이 부족할 때가 있어요."],"title":"교통의 변화로 생긴 매듭 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_basic#7','soc',3,2,'u2','L12','g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',2,'blank','auto','막히는 길, 교통사고 상황 등의 정보를 빠르게 알려 교통을 관리하는 노력을 (    )인 교통 관리라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"blank","stem":"막히는 길, 교통사고 상황 등의 정보를 빠르게 알려 교통을 관리하는 노력을 (    )인 교통 관리라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"과학적","correct":true},{"t":"옛날식","mis":"SO3-2-u2-X30"},{"t":"우연한","mis":"SO3-2-u2-X30"},{"t":"느긋한","mis":"SO3-2-u2-X30"}],"explanation":["정보를 빠르게 알려요.","과학 기술을 써요.","과학적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_basic#8','soc',3,2,'u2','L12','g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',2,'mc','auto','길을 걷는 사람이 지켜야 할 교통안전 수칙으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"mc","stem":"길을 걷는 사람이 지켜야 할 교통안전 수칙으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"스마트폰을 보면서 길을 건너요","correct":true},{"t":"횡단보도를 건널 때는 주위를 잘 살펴요","mis":"SO3-2-u2-X31"},{"t":"무단 횡단을 하지 않아요","mis":"SO3-2-u2-X31"},{"t":"도로 옆에서 장난치지 않아요","mis":"SO3-2-u2-X31"}],"explanation":["알맞지 않은 것이에요.","화면만 보면 위험해요.","스마트폰이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_basic#9','soc',3,2,'u2','L12','g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',2,'ox','auto','교통이 변화하면서 생긴 문제점은 해결할 방법이 없어요.',ARRAY['SO3-2-u2-X32']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"ox","stem":"교통이 변화하면서 생긴 문제점은 해결할 방법이 없어요.","answer":"X","reason_options":[{"t":"과학적인 교통 관리, 친환경 에너지 사용처럼 해결하려는 노력이 있기 때문에","correct":true},{"t":"교통 문제는 사람의 노력과 상관이 없기 때문에","mis":"SO3-2-u2-X32"}],"mis":"SO3-2-u2-X32","explanation":["노력이 있어요.","매듭을 풀었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["가. 막히는 길, 교통사고 상황 등의 정보를 빠르게 알려 줘요.","나. 친환경 에너지를 사용하는 교통수단을 이용해요.","다. 새로운 주차 시설을 만들어요.","라. 보행자와 운전자가 교통안전 수칙을 잘 지켜요."],"title":"매듭을 푸는 노력 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_basic#10','soc',3,2,'u2','L12','g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',3,'mc','auto','자전거나 킥보드를 탈 때 지켜야 할 약속으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"mc","stem":"자전거나 킥보드를 탈 때 지켜야 할 약속으로 알맞은 것은 무엇인가요?","options":[{"t":"정해진 도로에서 안전 장비를 착용하고 타요","correct":true},{"t":"인도에서 빠르게 달려요","mis":"SO3-2-u2-X31"},{"t":"안전 장비 없이 타요","mis":"SO3-2-u2-X31"},{"t":"어린이는 지킬 약속이 없어요","mis":"SO3-2-u2-X31"}],"explanation":["어린이도 운전자예요.","정해진 도로예요.","안전 장비를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_challenge#1','soc',3,2,'u2','L12','g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',2,'sa','auto','신호를 지키지 않고 아무 곳에서나 길을 건너는 것을 「○○ 횡단」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"sa","stem":"신호를 지키지 않고 아무 곳에서나 길을 건너는 것을 「○○ 횡단」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["무단"],"explanation":["하지 말아야 해요.","◯단이에요.","무단이에요."],"mis":"SO3-2-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_challenge#2','soc',3,2,'u2','L12','g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',2,'ox','auto','교통안전 수칙은 자동차 운전자만 지키면 돼요.',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"ox","stem":"교통안전 수칙은 자동차 운전자만 지키면 돼요.","answer":"X","reason_options":[{"t":"보행자와 자전거·킥보드를 타는 어린이도 함께 지켜야 사고를 막을 수 있기 때문에","correct":true},{"t":"보행자는 교통과 관계가 없기 때문에","mis":"SO3-2-u2-X31"}],"mis":"SO3-2-u2-X31","explanation":["보행자도 있어요.","모두 지켜요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_challenge#3','soc',3,2,'u2','L12','g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',3,'mc','auto','어느 도시가 전기 자전거를 함께 쓰는 사업으로 줄이려고 한 문제는 무엇인가요?',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"mc","stem":"어느 도시가 전기 자전거를 함께 쓰는 사업으로 줄이려고 한 문제는 무엇인가요?","options":[{"t":"환경 문제와 교통 혼잡","correct":true},{"t":"주차장이 너무 많은 문제","mis":"SO3-2-u2-X30"},{"t":"길이 너무 넓은 문제","mis":"SO3-2-u2-X30"},{"t":"자전거가 너무 비싼 문제","mis":"SO3-2-u2-X30"}],"explanation":["미세 먼지를 줄여요.","차를 덜 타요.","환경과 혼잡이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_challenge#4','soc',3,2,'u2','L12','g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',3,'mc','auto','매듭 ㉣의 문제를 풀기 위한 노력으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"mc","stem":"매듭 ㉣의 문제를 풀기 위한 노력으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"SO3-2-u2-X30"},{"t":"나","mis":"SO3-2-u2-X30"},{"t":"라","mis":"SO3-2-u2-X30"}],"explanation":["주차할 곳이 부족해요.","주차 시설을 만들어요.","다예요."],"asset":{"type":"passage","lines":["가. 막히는 길, 교통사고 상황 등의 정보를 빠르게 알려 줘요.","나. 친환경 에너지를 사용하는 교통수단을 이용해요.","다. 새로운 주차 시설을 만들어요.","라. 보행자와 운전자가 교통안전 수칙을 잘 지켜요."],"title":"매듭을 푸는 노력 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_challenge#5','soc',3,2,'u2','L12','g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',3,'error','auto','교통 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X32','SO3-2-u2-X30']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"error","stem":"교통 문제를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「교통 문제를 줄이려면 교통수단을 모두 없애야 해.」","correct":true,"mis_target":"SO3-2-u2-X32"},{"t":"친구 나 — 「친환경 에너지를 쓰는 교통수단을 이용하면 좋아.」","mis":"SO3-2-u2-X30"},{"t":"친구 다 — 「대중교통 중심의 교통 환경을 만들기도 해.」","mis":"SO3-2-u2-X30"}],"explanation":["없애면 불편해요.","줄이는 노력이 있어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_challenge#6','soc',3,2,'u2','L12','g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',3,'mc','auto','어린이 보호 구역에서 자동차는 어떻게 다녀야 하나요?',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"mc","stem":"어린이 보호 구역에서 자동차는 어떻게 다녀야 하나요?","options":[{"t":"천천히 가요","correct":true},{"t":"더 빨리 지나가요","mis":"SO3-2-u2-X31"},{"t":"경적을 계속 울려요","mis":"SO3-2-u2-X31"},{"t":"길가에 오래 세워 둬요","mis":"SO3-2-u2-X31"}],"explanation":["어린이가 많아요.","사고를 막아요.","천천히 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_challenge#7','soc',3,2,'u2','L12','g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',3,'ox','auto','교통이 변화하면서 많은 사람이 편리하게 생활하게 됐지만 문제점도 나타났어요.',ARRAY['SO3-2-u2-X32']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"ox","stem":"교통이 변화하면서 많은 사람이 편리하게 생활하게 됐지만 문제점도 나타났어요.","answer":"O","reason_options":[{"t":"먼 곳까지 빠르게 가게 됐지만 교통 체증과 사고, 환경 문제도 생겼기 때문에","correct":true},{"t":"교통이 변화하면서 불편한 점은 모두 사라졌기 때문에","mis":"SO3-2-u2-X32"}],"mis":"SO3-2-u2-X32","explanation":["편리해졌어요.","문제도 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 먼 곳까지 이동할 수 있지만, 차가 너무 많이 모여 길이 막히기도 해요.","㉡ 빠르게 이동할 수 있지만, 사고가 일어나기도 해요.","㉢ 다양한 교통수단을 이용할 수 있지만, 대기 오염과 소음 문제가 일어나기도 해요.","㉣ 가고 싶은 곳으로 편하게 갈 수 있지만, 주차할 곳이 부족할 때가 있어요."],"title":"교통의 변화로 생긴 매듭 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_challenge#8','soc',3,2,'u2','L12','g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',4,'mc','auto','「교통의 문제점과 해결 노력」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X32','SO3-2-u2-X31']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C12","difficulty":4,"kind":"mc","stem":"「교통의 문제점과 해결 노력」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"교통이 변화하면서 편리해졌지만 문제점도 생겼고, 이를 해결하려고 다양하게 노력하며 우리도 안전 수칙을 지켜요","correct":true},{"t":"교통이 변화하면서 불편한 점은 모두 사라졌어요","mis":"SO3-2-u2-X32"},{"t":"교통 문제는 해결할 방법이 없어요","mis":"SO3-2-u2-X32"},{"t":"교통안전 수칙은 운전자만 지키면 돼요","mis":"SO3-2-u2-X31"}],"explanation":["편리함과 문제예요.","노력이 있어요.","우리도 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_challenge#9','soc',3,2,'u2','L12','g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',4,'mc','auto','학교 앞에 차가 많고 길을 건너는 어린이도 많아요. 우리가 할 수 있는 일로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C12","difficulty":4,"kind":"mc","stem":"학교 앞에 차가 많고 길을 건너는 어린이도 많아요. 우리가 할 수 있는 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"횡단보도에서 주위를 잘 살피고 무단 횡단을 하지 않아요","correct":true},{"t":"차가 오면 뛰어서 빨리 건너요","mis":"SO3-2-u2-X31"},{"t":"친구와 도로 옆에서 장난쳐요","mis":"SO3-2-u2-X31"},{"t":"스마트폰을 보면서 건너요","mis":"SO3-2-u2-X31"}],"explanation":["어린이가 할 일이에요.","안전 수칙이에요.","살피고 건너요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L12_challenge#10','soc',3,2,'u2','L12','g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',4,'essay','teacher','매듭의 문제점 가운데 하나를 골라 어떤 문제인지 쓰고, 그 문제를 해결하려는 노력과 내가 지킬 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C12","difficulty":4,"kind":"essay","stem":"매듭의 문제점 가운데 하나를 골라 어떤 문제인지 쓰고, 그 문제를 해결하려는 노력과 내가 지킬 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: ㉢ 다양한 교통수단을 이용하면서 대기 오염과 소음 문제가 생겼어요. 친환경 에너지를 사용하는 교통수단을 이용해 환경 오염을 줄이려고 노력해요. 나는 가까운 곳은 걸어가거나 자전거를 타고 가겠어요.","scoring_points":["문제점을 하나 골라 설명했는가","알맞은 해결 노력을 썼는가","내가 할 수 있는 일을 썼는가"]},"explanation":["매듭을 골라요.","노력을 써요.","내 일을 써요."],"asset":{"type":"passage","lines":["㉠ 먼 곳까지 이동할 수 있지만, 차가 너무 많이 모여 길이 막히기도 해요.","㉡ 빠르게 이동할 수 있지만, 사고가 일어나기도 해요.","㉢ 다양한 교통수단을 이용할 수 있지만, 대기 오염과 소음 문제가 일어나기도 해요.","㉣ 가고 싶은 곳으로 편하게 갈 수 있지만, 주차할 곳이 부족할 때가 있어요."],"title":"교통의 변화로 생긴 매듭 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_basic#1','soc',3,2,'u2','L13','g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',1,'mc','auto','사람이 직접 운전할 필요가 없는 미래 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C13","difficulty":1,"kind":"mc","stem":"사람이 직접 운전할 필요가 없는 미래 교통수단은 무엇인가요?","options":[{"t":"자율 주행 자동차","correct":true},{"t":"착용하는 로봇","mis":"SO3-2-u2-X33"},{"t":"달구지","mis":"SO3-2-u2-X33"},{"t":"나룻배","mis":"SO3-2-u2-X33"}],"explanation":["스스로 달려요.","운전하지 않아요.","자율 주행 자동차예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_basic#2','soc',3,2,'u2','L13','g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',1,'sa','auto','우주여행을 하거나 우주로 물건을 옮길 수 있는 미래 교통수단을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C13","difficulty":1,"kind":"sa","stem":"우주여행을 하거나 우주로 물건을 옮길 수 있는 미래 교통수단을 세 글자로 쓰세요.","answer":["우주선"],"explanation":["우주로 가요.","우주◯이에요.","우주선이에요."],"mis":"SO3-2-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_basic#3','soc',3,2,'u2','L13','g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',1,'ox','auto','자율 주행 휠체어는 장애인, 환자 등이 안전하게 이동하도록 도와요.',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C13","difficulty":1,"kind":"ox","stem":"자율 주행 휠체어는 장애인, 환자 등이 안전하게 이동하도록 도와요.","answer":"O","reason_options":[{"t":"몸이 불편한 사람도 쉽게 이동할 수 있게 해 주기 때문에","correct":true},{"t":"자율 주행 휠체어는 무거운 짐만 옮기기 때문에","mis":"SO3-2-u2-X33"}],"mis":"SO3-2-u2-X33","explanation":["휠체어예요.","몸이 불편한 사람이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_basic#4','soc',3,2,'u2','L13','g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',1,'mc','auto','무거운 물건을 쉽게 들 수 있도록 돕는 미래 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C13","difficulty":1,"kind":"mc","stem":"무거운 물건을 쉽게 들 수 있도록 돕는 미래 교통수단은 무엇인가요?","options":[{"t":"착용하는 로봇","correct":true},{"t":"우주선","mis":"SO3-2-u2-X33"},{"t":"자율 운항 선박","mis":"SO3-2-u2-X33"},{"t":"자율 주행 휠체어","mis":"SO3-2-u2-X33"}],"explanation":["몸에 입어요.","힘을 보태요.","착용하는 로봇이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_basic#5','soc',3,2,'u2','L13','g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',2,'match','auto','미래 교통수단과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"match","stem":"미래 교통수단과 특징을 알맞게 이으세요.","pairs":[{"l":"자율 운항 선박","r":"스스로 목적지까지 운항해요"},{"l":"초고속 자기 부상 열차","r":"터널을 통해 비행기보다 빠르게 달려요"},{"l":"자율 주행 휠체어","r":"장애인·환자의 안전한 이동을 도와요"}],"mis":"SO3-2-u2-X33","explanation":["선박은 바다예요.","열차는 빨라요.","휠체어는 이동을 도와요."],"asset":{"type":"passage","lines":["㉠ 자율 주행 휠체어","㉡ 착용하는 로봇","㉢ 우주선","㉣ 자율 주행 자동차","㉤ 자율 운항 선박","㉥ 초고속 자기 부상 열차"],"title":"연구, 개발 중인 미래 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_basic#6','soc',3,2,'u2','L13','g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',2,'mc','auto','자기 부상의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"mc","stem":"자기 부상의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"전기의 힘으로 물체를 들어 올리는 것","correct":true},{"t":"물 위에 떠서 움직이는 것","mis":"SO3-2-u2-X33"},{"t":"바람의 힘으로 날아가는 것","mis":"SO3-2-u2-X33"},{"t":"사람이 끌어서 움직이는 것","mis":"SO3-2-u2-X33"}],"explanation":["공중에 떠요.","전기의 힘이에요.","들어 올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_basic#7','soc',3,2,'u2','L13','g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',2,'blank','auto','미래 교통수단은 더 빠르고 안전하면서 (    )을 보호하는 방향으로 발전하고 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"blank","stem":"미래 교통수단은 더 빠르고 안전하면서 (    )을 보호하는 방향으로 발전하고 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"환경","correct":true},{"t":"명절","mis":"SO3-2-u2-X34"},{"t":"주차장","mis":"SO3-2-u2-X34"},{"t":"옛날 교통수단","mis":"SO3-2-u2-X34"}],"explanation":["공해를 줄여요.","지구를 생각해요.","환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_basic#8','soc',3,2,'u2','L13','g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',2,'mc','auto','도심 항공 교통의 장점으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X33','SO3-2-u2-X34']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"mc","stem":"도심 항공 교통의 장점으로 알맞은 것은 무엇인가요?","options":[{"t":"하늘로 다녀 땅에서와 같은 교통 혼잡 문제를 일으키지 않아요","correct":true},{"t":"공항처럼 아주 큰 시설이 꼭 있어야 해요","mis":"SO3-2-u2-X33"},{"t":"도로를 더 많이 만들어야 해요","mis":"SO3-2-u2-X33"},{"t":"공해와 소음이 아주 많아요","mis":"SO3-2-u2-X34"}],"explanation":["하늘을 길로 삼아요.","땅이 막혀도 괜찮아요.","혼잡이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_basic#9','soc',3,2,'u2','L13','g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',2,'ox','auto','미래에도 교통수단과 사람들의 생활 모습은 지금과 똑같을 거예요.',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"ox","stem":"미래에도 교통수단과 사람들의 생활 모습은 지금과 똑같을 거예요.","answer":"X","reason_options":[{"t":"새로운 교통수단이 연구, 개발되면서 생활 모습과 직업도 달라질 것이기 때문에","correct":true},{"t":"교통수단은 이제 더 발전하지 않기 때문에","mis":"SO3-2-u2-X34"}],"mis":"SO3-2-u2-X34","explanation":["연구하고 있어요.","달라질 거예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_basic#10','soc',3,2,'u2','L13','g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',3,'mc','auto','자율 주행 자동차가 발달하면 차 안은 어떤 공간으로 바뀔 수 있나요?',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"mc","stem":"자율 주행 자동차가 발달하면 차 안은 어떤 공간으로 바뀔 수 있나요?","options":[{"t":"이동뿐만 아니라 일하고 쉬는 공간","correct":true},{"t":"운전만 하는 공간","mis":"SO3-2-u2-X33"},{"t":"짐만 싣는 공간","mis":"SO3-2-u2-X33"},{"t":"아무도 탈 수 없는 공간","mis":"SO3-2-u2-X33"}],"explanation":["운전하지 않아요.","다른 일을 해요.","일하고 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_challenge#1','soc',3,2,'u2','L13','g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',2,'sa','auto','관광용 우주선이 발달하면 새로 생길 수 있는 직업을 「우주 관광 ○○○」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"sa","stem":"관광용 우주선이 발달하면 새로 생길 수 있는 직업을 「우주 관광 ○○○」라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["가이드"],"explanation":["여행을 안내해요.","가◯◯예요.","가이드예요."],"mis":"SO3-2-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_challenge#2','soc',3,2,'u2','L13','g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',2,'ox','auto','도심 항공 교통은 친환경 에너지로 움직여 공해와 소음이 적어요.',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"ox","stem":"도심 항공 교통은 친환경 에너지로 움직여 공해와 소음이 적어요.","answer":"O","reason_options":[{"t":"친환경 에너지를 쓰기 때문에","correct":true},{"t":"도심 항공 교통은 공해를 많이 내는 연료만 쓰기 때문에","mis":"SO3-2-u2-X34"}],"mis":"SO3-2-u2-X34","explanation":["친환경 에너지예요.","공해가 적어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_challenge#3','soc',3,2,'u2','L13','g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',3,'mc','auto','도심 항공 교통이 발달하면 새로 생길 수 있는 직업은 무엇인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"mc","stem":"도심 항공 교통이 발달하면 새로 생길 수 있는 직업은 무엇인가요?","options":[{"t":"이착륙장 관리자","correct":true},{"t":"나룻배를 젓는 뱃사공","mis":"SO3-2-u2-X29"},{"t":"가마를 메는 가마꾼","mis":"SO3-2-u2-X29"},{"t":"달구지를 끄는 사람","mis":"SO3-2-u2-X29"}],"explanation":["미래 교통수단과 관련 있어요.","뜨고 내리는 곳이에요.","이착륙장 관리자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_challenge#4','soc',3,2,'u2','L13','g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',3,'mc','auto','자료의 미래 교통수단 가운데 「몸이 불편한 사람」과 「무거운 물건을 드는 사람」을 돕는 것을 차례대로 고른 것은 무엇인가요?',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"mc","stem":"자료의 미래 교통수단 가운데 「몸이 불편한 사람」과 「무거운 물건을 드는 사람」을 돕는 것을 차례대로 고른 것은 무엇인가요?","options":[{"t":"㉠, ㉡","correct":true},{"t":"㉡, ㉠","mis":"SO3-2-u2-X33"},{"t":"㉢, ㉣","mis":"SO3-2-u2-X33"},{"t":"㉤, ㉥","mis":"SO3-2-u2-X33"}],"explanation":["휠체어가 먼저예요.","로봇이 다음이에요.","㉠, ㉡이에요."],"asset":{"type":"passage","lines":["㉠ 자율 주행 휠체어","㉡ 착용하는 로봇","㉢ 우주선","㉣ 자율 주행 자동차","㉤ 자율 운항 선박","㉥ 초고속 자기 부상 열차"],"title":"연구, 개발 중인 미래 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_challenge#5','soc',3,2,'u2','L13','g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',3,'error','auto','미래 교통을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"error","stem":"미래 교통을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「미래 교통수단은 빨리 가기만 하면 돼. 안전과 환경은 상관없어.」","correct":true,"mis_target":"SO3-2-u2-X34"},{"t":"친구 가 — 「미래 교통은 더 안전한 쪽으로 발전하고 있어.」","mis":"SO3-2-u2-X34"},{"t":"친구 다 — 「환경을 보호하는 쪽으로도 발전하고 있어.」","mis":"SO3-2-u2-X34"}],"explanation":["방향이 셋이에요.","빠르기만이 아니에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_challenge#6','soc',3,2,'u2','L13','g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',3,'ox','auto','미래 교통수단은 몸이 불편한 사람은 이용하기 어려울 거예요.',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"ox","stem":"미래 교통수단은 몸이 불편한 사람은 이용하기 어려울 거예요.","answer":"X","reason_options":[{"t":"자율 주행 휠체어처럼 이동이 불편했던 사람도 편하게 이용하도록 개발하고 있기 때문에","correct":true},{"t":"미래 교통수단은 몸이 건강한 사람만 탈 수 있기 때문에","mis":"SO3-2-u2-X34"}],"mis":"SO3-2-u2-X34","explanation":["휠체어를 봐요.","편하게 이동해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_challenge#7','soc',3,2,'u2','L13','g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',3,'mc','auto','초고속 자기 부상 열차가 다니게 되면 달라질 생활 모습으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X34','SO3-2-u2-X33']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"mc","stem":"초고속 자기 부상 열차가 다니게 되면 달라질 생활 모습으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"먼 곳을 지금보다 훨씬 빠르게 오갈 수 있어요","correct":true},{"t":"먼 곳에 가는 데 시간이 더 오래 걸려요","mis":"SO3-2-u2-X34"},{"t":"열차를 타려면 노를 저어야 해요","mis":"SO3-2-u2-X33"},{"t":"물건을 하나도 옮길 수 없어요","mis":"SO3-2-u2-X33"}],"explanation":["비행기보다 빨라요.","먼 곳이에요.","빠르게 오가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_challenge#8','soc',3,2,'u2','L13','g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',4,'mc','auto','「미래의 교통」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C13","difficulty":4,"kind":"mc","stem":"「미래의 교통」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"미래 교통은 빠르고 안전하며 환경을 보호하는 쪽으로 발전하고, 사람들은 더 먼 곳으로 가며 새 직업도 생길 거예요","correct":true},{"t":"미래 교통수단은 더 빨리 이동하는 방향으로만 발전해요","mis":"SO3-2-u2-X34"},{"t":"미래에는 이용할 교통수단이 지금보다 줄어들 거예요","mis":"SO3-2-u2-X34"},{"t":"미래에도 생활 모습은 지금과 똑같을 거예요","mis":"SO3-2-u2-X34"}],"explanation":["방향을 떠올려요.","생활이 달라져요.","직업도 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_challenge#9','soc',3,2,'u2','L13','g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',4,'mc','auto','자율 주행 자동차가 많아지면 더 필요해질 수 있는 일로 교과서에 나온 것은 무엇인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C13","difficulty":4,"kind":"mc","stem":"자율 주행 자동차가 많아지면 더 필요해질 수 있는 일로 교과서에 나온 것은 무엇인가요?","options":[{"t":"인공지능 개발자","correct":true},{"t":"가마꾼","mis":"SO3-2-u2-X29"},{"t":"뱃사공","mis":"SO3-2-u2-X29"},{"t":"말을 타고 소식을 전하는 사람","mis":"SO3-2-u2-X29"}],"explanation":["스스로 운전해요.","똑똑한 컴퓨터예요.","인공지능 개발자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L13_challenge#10','soc',3,2,'u2','L13','g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',4,'essay','teacher','자료의 미래 교통수단 가운데 하나를 골라 특징을 쓰고, 그 교통수단이 생기면 사람들의 생활이 어떻게 달라질지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C13","difficulty":4,"kind":"essay","stem":"자료의 미래 교통수단 가운데 하나를 골라 특징을 쓰고, 그 교통수단이 생기면 사람들의 생활이 어떻게 달라질지 쓰세요.","answer_guide":{"answer":"예: ㉣ 자율 주행 자동차는 사람이 직접 운전할 필요가 없어요. 이 자동차가 생기면 이동하는 동안 차 안에서 일하거나 쉴 수 있고, 운전하기 어려운 사람도 편하게 이동할 수 있을 거예요.","scoring_points":["교통수단을 하나 골랐는가","특징을 바르게 썼는가","달라질 생활 모습을 썼는가"]},"explanation":["하나를 골라요.","특징을 써요.","생활을 예상해요."],"asset":{"type":"passage","lines":["㉠ 자율 주행 휠체어","㉡ 착용하는 로봇","㉢ 우주선","㉣ 자율 주행 자동차","㉤ 자율 운항 선박","㉥ 초고속 자기 부상 열차"],"title":"연구, 개발 중인 미래 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_basic#1','soc',3,2,'u2','L14','g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',1,'mc','auto','돋보기 탐정의 단서 가운데 맞지 않는 설명은 무엇인가요?',ARRAY['SO3-2-u2-X32']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C14","difficulty":1,"kind":"mc","stem":"돋보기 탐정의 단서 가운데 맞지 않는 설명은 무엇인가요?","options":[{"t":"단서 2","correct":true},{"t":"단서 1","mis":"SO3-2-u2-X32"},{"t":"단서 3","mis":"SO3-2-u2-X32"},{"t":"셋 다 맞아요","mis":"SO3-2-u2-X32"}],"explanation":["문제점을 떠올려요.","모두 해결되지 않았어요.","단서 2예요."],"asset":{"type":"passage","lines":["단서 1 — 교통의 발달로 사람들과 물건의 이동이 빨라지고 편리해졌습니다.","단서 2 — 교통이 발달하면서 교통의 문제점이 모두 해결됐습니다.","단서 3 — 교통의 변화로 여러 가지 새로운 시설이 생기고 생활 모습이 달라졌습니다."],"title":"돋보기 탐정의 단서 세 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_basic#2','soc',3,2,'u2','L14','g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',1,'sa','auto','교통수단과 교통 시설이 다양해지면서 안전을 위해 생긴 것은 여러 가지 신호와 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C14","difficulty":1,"kind":"sa","stem":"교통수단과 교통 시설이 다양해지면서 안전을 위해 생긴 것은 여러 가지 신호와 무엇인가요? 두 글자로 쓰세요.","answer":["약속"],"explanation":["함께 지켜요.","약◯이에요.","약속이에요."],"mis":"SO3-2-u2-X27"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_basic#3','soc',3,2,'u2','L14','g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',1,'ox','auto','돛단배는 바람과 같은 자연의 힘을 이용했어요.',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C14","difficulty":1,"kind":"ox","stem":"돛단배는 바람과 같은 자연의 힘을 이용했어요.","answer":"O","reason_options":[{"t":"돛이 바람을 받아 배를 움직였기 때문에","correct":true},{"t":"돛단배는 석유의 힘으로 움직였기 때문에","mis":"SO3-2-u2-X24"}],"mis":"SO3-2-u2-X24","explanation":["돛이 있어요.","바람을 받아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_basic#4','soc',3,2,'u2','L14','g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',1,'mc','auto','교통이 변화하면서 생긴 문제를 해결하려는 노력으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X32','SO3-2-u2-X31']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C14","difficulty":1,"kind":"mc","stem":"교통이 변화하면서 생긴 문제를 해결하려는 노력으로 알맞은 것은 무엇인가요?","options":[{"t":"친환경 에너지를 사용해요","correct":true},{"t":"자동차를 더 많이 타요","mis":"SO3-2-u2-X32"},{"t":"교통안전 수칙을 지키지 않아요","mis":"SO3-2-u2-X31"},{"t":"교통 시설을 모두 없애요","mis":"SO3-2-u2-X32"}],"explanation":["노력을 골라요.","환경을 생각해요.","친환경 에너지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_basic#5','soc',3,2,'u2','L14','g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',2,'match','auto','여러 나라의 교통 표지판과 담긴 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"match","stem":"여러 나라의 교통 표지판과 담긴 뜻을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"동물을 조심해요"},{"l":"㉯","r":"걸으며 스마트폰을 쓰지 않아요"},{"l":"㉰","r":"보행자가 먼저예요"}],"mis":"SO3-2-u2-X27","explanation":["㉮는 동물이에요.","㉯는 스마트폰이에요.","㉰는 보행자예요."],"asset":{"type":"passage","lines":["㉮ 도로를 가로지르는 동물을 조심하라는 표지판","㉯ 거리를 걸으면서 스마트폰을 사용하지 말라는 표지판","㉰ 보행자 우선 도로임을 알리는 표지판"],"title":"여러 나라의 독특한 교통 표지판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_basic#6','soc',3,2,'u2','L14','g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',2,'mc','auto','교통의 발달로 달라진 생활 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X28','SO3-2-u2-X29']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"mc","stem":"교통의 발달로 달라진 생활 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"사람들의 생활 공간이 더욱 넓어졌어요","correct":true},{"t":"같은 거리를 가는 데 시간이 더 오래 걸려요","mis":"SO3-2-u2-X28"},{"t":"한 번에 실어 나를 수 있는 짐이 줄었어요","mis":"SO3-2-u2-X28"},{"t":"새로 생긴 직업이 하나도 없어요","mis":"SO3-2-u2-X29"}],"explanation":["더 멀리 오가요.","생활이 넓어졌어요.","생활 공간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_basic#7','soc',3,2,'u2','L14','g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',2,'blank','auto','어떤 장소에서 다른 장소로 사람이 이동하거나 물건을 옮기는 것을 (    )이라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X20']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"blank","stem":"어떤 장소에서 다른 장소로 사람이 이동하거나 물건을 옮기는 것을 (    )이라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"교통","correct":true},{"t":"교통수단","mis":"SO3-2-u2-X20"},{"t":"교통 시설","mis":"SO3-2-u2-X20"},{"t":"교통로","mis":"SO3-2-u2-X20"}],"explanation":["주제의 첫 낱말이에요.","수단도 길도 아니에요.","교통이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_basic#8','soc',3,2,'u2','L14','g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',2,'mc','auto','옛날 교통수단에 관한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X24']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"mc","stem":"옛날 교통수단에 관한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"자연에서 쉽게 얻을 수 있는 재료로 만들었어요","correct":true},{"t":"옛날에는 비행기로 먼 곳을 다녔어요","mis":"SO3-2-u2-X44"},{"t":"모두 기계의 힘으로 움직였어요","mis":"SO3-2-u2-X24"},{"t":"고속 열차로 짐을 옮겼어요","mis":"SO3-2-u2-X44"}],"explanation":["통나무를 떠올려요.","나무와 풀 줄기예요.","자연의 재료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_basic#9','soc',3,2,'u2','L14','g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',2,'ox','auto','교통이 발달하면서 교통의 문제점이 모두 해결됐어요.',ARRAY['SO3-2-u2-X32']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"ox","stem":"교통이 발달하면서 교통의 문제점이 모두 해결됐어요.","answer":"X","reason_options":[{"t":"교통 체증이나 환경 문제 같은 문제점이 생겨 지금도 해결하려고 노력하고 있기 때문에","correct":true},{"t":"교통이 발달하면 문제는 저절로 사라지기 때문에","mis":"SO3-2-u2-X32"}],"mis":"SO3-2-u2-X32","explanation":["단서 2예요.","지금도 노력해요.","그래서 X예요."],"asset":{"type":"passage","lines":["단서 1 — 교통의 발달로 사람들과 물건의 이동이 빨라지고 편리해졌습니다.","단서 2 — 교통이 발달하면서 교통의 문제점이 모두 해결됐습니다.","단서 3 — 교통의 변화로 여러 가지 새로운 시설이 생기고 생활 모습이 달라졌습니다."],"title":"돋보기 탐정의 단서 세 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_basic#10','soc',3,2,'u2','L14','g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',3,'mc','auto','옛날 사람들이 상상한 「하늘을 나는 신발」이 생긴다면 달라질 생활 모습으로 교과서 예시와 같은 것은 무엇인가요?',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"mc","stem":"옛날 사람들이 상상한 「하늘을 나는 신발」이 생긴다면 달라질 생활 모습으로 교과서 예시와 같은 것은 무엇인가요?","options":[{"t":"차를 타고 이동할 필요가 없어져 도로가 줄고 공원이 많아질 거예요","correct":true},{"t":"도로가 더 많아지고 공원이 사라질 거예요","mis":"SO3-2-u2-X34"},{"t":"가까운 곳도 가기 어려워질 거예요","mis":"SO3-2-u2-X34"},{"t":"사람들이 더 느리게 다닐 거예요","mis":"SO3-2-u2-X34"}],"explanation":["하늘을 날아요.","차가 필요 없어요.","공원이 많아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_challenge#1','soc',3,2,'u2','L14','g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',2,'sa','auto','교통에 이용하는 길을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"sa","stem":"교통에 이용하는 길을 세 글자로 쓰세요.","answer":["교통로"],"explanation":["도로·철도·수로예요.","교통◯예요.","교통로예요."],"mis":"SO3-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_challenge#2','soc',3,2,'u2','L14','g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',2,'ox','auto','단서 3은 맞는 설명이에요.',ARRAY['SO3-2-u2-X32']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"ox","stem":"단서 3은 맞는 설명이에요.","answer":"O","reason_options":[{"t":"교통의 변화로 주유소, 활주로 같은 새로운 시설이 생기고 생활 모습이 달라졌기 때문에","correct":true},{"t":"교통이 변해도 시설은 생기지 않기 때문에","mis":"SO3-2-u2-X32"}],"mis":"SO3-2-u2-X32","explanation":["새 시설이 생겼어요.","생활도 달라졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["단서 1 — 교통의 발달로 사람들과 물건의 이동이 빨라지고 편리해졌습니다.","단서 2 — 교통이 발달하면서 교통의 문제점이 모두 해결됐습니다.","단서 3 — 교통의 변화로 여러 가지 새로운 시설이 생기고 생활 모습이 달라졌습니다."],"title":"돋보기 탐정의 단서 세 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_challenge#3','soc',3,2,'u2','L14','g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',3,'mc','auto','단서 2를 맞는 설명으로 고친 것은 무엇인가요?',ARRAY['SO3-2-u2-X32','SO3-2-u2-X44']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"mc","stem":"단서 2를 맞는 설명으로 고친 것은 무엇인가요?","options":[{"t":"교통이 발달하면서 문제점도 생겨 해결하려고 노력하고 있어요","correct":true},{"t":"교통이 발달하면서 문제점이 모두 사라졌어요","mis":"SO3-2-u2-X32"},{"t":"교통은 옛날부터 오늘날까지 달라지지 않았어요","mis":"SO3-2-u2-X44"},{"t":"교통의 문제는 해결할 필요가 없어요","mis":"SO3-2-u2-X32"}],"explanation":["문제가 생겼어요.","노력하고 있어요.","그렇게 고쳐요."],"asset":{"type":"passage","lines":["단서 1 — 교통의 발달로 사람들과 물건의 이동이 빨라지고 편리해졌습니다.","단서 2 — 교통이 발달하면서 교통의 문제점이 모두 해결됐습니다.","단서 3 — 교통의 변화로 여러 가지 새로운 시설이 생기고 생활 모습이 달라졌습니다."],"title":"돋보기 탐정의 단서 세 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_challenge#4','soc',3,2,'u2','L14','g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',3,'mc','auto','표지판 ㉯와 가장 관계있는 교통안전 수칙은 무엇인가요?',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"mc","stem":"표지판 ㉯와 가장 관계있는 교통안전 수칙은 무엇인가요?","options":[{"t":"스마트폰을 보면서 길을 걸어가지 않아요","correct":true},{"t":"어린이 보호 구역에서 천천히 가요","mis":"SO3-2-u2-X31"},{"t":"자전거는 안전 장비를 착용하고 타요","mis":"SO3-2-u2-X31"},{"t":"도로를 건너는 동물을 조심해요","mis":"SO3-2-u2-X31"}],"explanation":["걸으며 스마트폰이에요.","보행자 수칙이에요.","보며 걷지 않아요."],"asset":{"type":"passage","lines":["㉮ 도로를 가로지르는 동물을 조심하라는 표지판","㉯ 거리를 걸으면서 스마트폰을 사용하지 말라는 표지판","㉰ 보행자 우선 도로임을 알리는 표지판"],"title":"여러 나라의 독특한 교통 표지판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_challenge#5','soc',3,2,'u2','L14','g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',3,'error','auto','교통 주제를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X28','SO3-2-u2-X29']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"error","stem":"교통 주제를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「교통이 발달하면서 사람들은 가까운 곳에서만 지내게 됐어.」","correct":true,"mis_target":"SO3-2-u2-X28"},{"t":"친구 가 — 「사람과 물건의 이동이 빨라졌어.」","mis":"SO3-2-u2-X28"},{"t":"친구 나 — 「새로운 시설과 직업이 생겼어.」","mis":"SO3-2-u2-X29"}],"explanation":["생활 공간을 봐요.","넓어졌어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_challenge#6','soc',3,2,'u2','L14','g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',3,'mc','auto','옛날과 오늘날의 교통을 바르게 견준 것은 무엇인가요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X24']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"mc","stem":"옛날과 오늘날의 교통을 바르게 견준 것은 무엇인가요?","options":[{"t":"옛날에는 말·가마·뗏목을, 오늘날에는 자동차·기차·여객선·비행기를 이용해요","correct":true},{"t":"옛날에는 비행기를, 오늘날에는 가마를 이용해요","mis":"SO3-2-u2-X44"},{"t":"옛날과 오늘날 모두 같은 교통수단을 이용해요","mis":"SO3-2-u2-X44"},{"t":"옛날에는 기계의 힘을, 오늘날에는 바람의 힘만 이용해요","mis":"SO3-2-u2-X24"}],"explanation":["옛날은 자연의 힘이에요.","오늘날은 기계예요.","견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_challenge#7','soc',3,2,'u2','L14','g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',3,'ox','auto','교통이 바뀌어도 사람들의 생활 모습은 그대로예요.',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"ox","stem":"교통이 바뀌어도 사람들의 생활 모습은 그대로예요.","answer":"X","reason_options":[{"t":"이동이 빨라지고 생활 공간이 넓어지는 등 생활 모습이 달라졌기 때문에","correct":true},{"t":"교통과 생활은 아무 관계가 없기 때문에","mis":"SO3-2-u2-X44"}],"mis":"SO3-2-u2-X44","explanation":["생활이 달라졌어요.","넓어졌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_challenge#8','soc',3,2,'u2','L14','g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',4,'mc','auto','주제 「교통의 변화로 달라진 생활 모습」을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X32','SO3-2-u2-X44','SO3-2-u2-X28']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C14","difficulty":4,"kind":"mc","stem":"주제 「교통의 변화로 달라진 생활 모습」을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"교통의 변화로 이동이 빨라지고 편리해졌으며, 새 시설이 생기고 생활 모습이 달라졌지만 문제점도 있어 해결하려고 노력해요","correct":true},{"t":"교통이 발달하면서 문제점이 모두 사라졌어요","mis":"SO3-2-u2-X32"},{"t":"교통은 옛날부터 달라지지 않았어요","mis":"SO3-2-u2-X44"},{"t":"교통이 발달하면서 사람들은 가까운 곳에서만 지내요","mis":"SO3-2-u2-X28"}],"explanation":["편리해졌어요.","달라졌어요.","문제와 노력도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_challenge#9','soc',3,2,'u2','L14','g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',4,'mc','auto','학교 앞에 새로운 교통 표지판을 만든다면 담을 뜻으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X31','SO3-2-u2-X27']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C14","difficulty":4,"kind":"mc","stem":"학교 앞에 새로운 교통 표지판을 만든다면 담을 뜻으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"횡단보도가 어디에 있는지 알려 주어 어린이가 안전하게 건너도록 해요","correct":true},{"t":"자동차가 학교 앞에서 빨리 달려도 된다고 알려요","mis":"SO3-2-u2-X31"},{"t":"길에서 스마트폰을 보며 걸어도 된다고 알려요","mis":"SO3-2-u2-X31"},{"t":"표지판에는 아무 뜻이 없어도 돼요","mis":"SO3-2-u2-X27"}],"explanation":["안전이 목적이에요.","어린이가 많아요.","횡단보도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L14_challenge#10','soc',3,2,'u2','L14','g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',4,'essay','teacher','미래에 있으면 좋겠다고 상상한 교통수단을 하나 쓰고, 그 특징과 그 교통수단으로 달라질 생활 모습을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C14","difficulty":4,"kind":"essay","stem":"미래에 있으면 좋겠다고 상상한 교통수단을 하나 쓰고, 그 특징과 그 교통수단으로 달라질 생활 모습을 쓰세요.","answer_guide":{"answer":"예: 하늘을 날 수 있고 안전하게 착륙하는 신발이 있으면 좋겠어요. 언제든지 쉽고 빠르게 이동할 수 있어요. 차를 탈 필요가 줄어 도로가 줄고 공원이 많아질 거예요.","scoring_points":["교통수단을 상상해 썼는가","특징을 썼는가","달라질 생활 모습을 썼는가"]},"explanation":["상상해요.","특징을 써요.","생활을 예상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_basic#1','soc',3,2,'u2','L15','g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',1,'mc','auto','소식이나 정보를 주고받는 것을 무엇이라고 하나요?',ARRAY['SO3-2-u2-X35']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C15","difficulty":1,"kind":"mc","stem":"소식이나 정보를 주고받는 것을 무엇이라고 하나요?","options":[{"t":"통신","correct":true},{"t":"교통","mis":"SO3-2-u2-X35"},{"t":"교통수단","mis":"SO3-2-u2-X35"},{"t":"교통 시설","mis":"SO3-2-u2-X35"}],"explanation":["소식을 주고받아요.","이동이 아니에요.","통신이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_basic#2','soc',3,2,'u2','L15','g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',1,'sa','auto','소식이나 정보를 주고받을 때 사용하는 방법이나 도구를 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C15","difficulty":1,"kind":"sa","stem":"소식이나 정보를 주고받을 때 사용하는 방법이나 도구를 네 글자로 쓰세요.","answer":["통신수단"],"explanation":["방법이나 도구예요.","통신◯◯이에요.","통신수단이에요."],"mis":"SO3-2-u2-X35"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_basic#3','soc',3,2,'u2','L15','g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',1,'ox','auto','일기 예보를 확인하면 날씨를 미리 알 수 있어요.',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C15","difficulty":1,"kind":"ox","stem":"일기 예보를 확인하면 날씨를 미리 알 수 있어요.","answer":"O","reason_options":[{"t":"통신수단으로 날씨 정보를 미리 얻을 수 있기 때문에","correct":true},{"t":"일기 예보는 날씨와 관계가 없기 때문에","mis":"SO3-2-u2-X36"}],"mis":"SO3-2-u2-X36","explanation":["예보를 봐요.","날씨 정보예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_basic#4','soc',3,2,'u2','L15','g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',1,'mc','auto','다음 가운데 통신수단이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X35']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C15","difficulty":1,"kind":"mc","stem":"다음 가운데 통신수단이 아닌 것은 무엇인가요?","options":[{"t":"자전거","correct":true},{"t":"전화","mis":"SO3-2-u2-X35"},{"t":"텔레비전","mis":"SO3-2-u2-X35"},{"t":"전자 우편","mis":"SO3-2-u2-X35"}],"explanation":["소식을 주고받나요?","타고 이동해요.","자전거는 교통수단이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_basic#5','soc',3,2,'u2','L15','g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',2,'match','auto','상황과 통신수단으로 할 수 있는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"match","stem":"상황과 통신수단으로 할 수 있는 일을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"위험을 알리고 도움을 청해요"},{"l":"㉡","r":"친구와 연락해 만날 곳을 정해요"},{"l":"㉢","r":"날씨를 미리 알아요"},{"l":"㉣","r":"길을 찾아요"}],"mis":"SO3-2-u2-X36","explanation":["늑대는 위험이에요.","친구는 연락이에요.","날씨와 길도 이어요."],"asset":{"type":"passage","lines":["㉠ 늑대가 막내 돼지의 집으로 가고 있어요.","㉡ 놀이공원에서 함께 온 친구가 보이지 않아요.","㉢ 일기 예보를 확인하지 않아 우산을 못 챙겼어요.","㉣ 자동차를 타고 처음 가 보는 곳을 찾아가야 해요."],"title":"통신수단이 필요한 네 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_basic#6','soc',3,2,'u2','L15','g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',2,'mc','auto','가족이 이용하는 통신수단에서 아버지가 확인하는 것은 무엇인가요?',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"mc","stem":"가족이 이용하는 통신수단에서 아버지가 확인하는 것은 무엇인가요?","options":[{"t":"인터폰","correct":true},{"t":"태블릿 컴퓨터","mis":"SO3-2-u2-X36"},{"t":"우편물","mis":"SO3-2-u2-X36"},{"t":"노트북","mis":"SO3-2-u2-X36"}],"explanation":["현관이에요.","누가 왔는지 봐요.","인터폰이에요."],"asset":{"type":"passage","lines":["어머니 — 우편물을 확인해요.","아버지 — 현관에서 누가 왔는지 인터폰으로 확인해요.","언니 — 텔레비전으로 새로운 소식을 얻어요.","남학생 — 노트북으로 정보를 찾아봐요."],"title":"어느 가족이 이용하는 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_basic#7','soc',3,2,'u2','L15','g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',2,'blank','auto','처음 가 보는 곳을 찾아갈 때는 (    )가 목적지까지 가는 길을 알려 줘요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X35']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"blank","stem":"처음 가 보는 곳을 찾아갈 때는 (    )가 목적지까지 가는 길을 알려 줘요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"길 도우미","correct":true},{"t":"봉수","mis":"SO3-2-u2-X35"},{"t":"달구지","mis":"SO3-2-u2-X35"},{"t":"가마","mis":"SO3-2-u2-X35"}],"explanation":["자동차에 있어요.","길을 알려요.","길 도우미예요."],"asset":{"type":"passage","lines":["㉠ 늑대가 막내 돼지의 집으로 가고 있어요.","㉡ 놀이공원에서 함께 온 친구가 보이지 않아요.","㉢ 일기 예보를 확인하지 않아 우산을 못 챙겼어요.","㉣ 자동차를 타고 처음 가 보는 곳을 찾아가야 해요."],"title":"통신수단이 필요한 네 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_basic#8','soc',3,2,'u2','L15','g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',2,'mc','auto','첫째와 둘째 돼지가 막내 돼지에게 늑대가 오는 것을 알리는 방법으로 통신수단을 쓴 것은 무엇인가요?',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"mc","stem":"첫째와 둘째 돼지가 막내 돼지에게 늑대가 오는 것을 알리는 방법으로 통신수단을 쓴 것은 무엇인가요?","options":[{"t":"막내 돼지에게 전화해 위험을 알려요","correct":true},{"t":"막내 돼지 집까지 달려가요","mis":"SO3-2-u2-X36"},{"t":"늑대 앞을 가로막아요","mis":"SO3-2-u2-X36"},{"t":"아무것도 하지 않아요","mis":"SO3-2-u2-X36"}],"explanation":["통신수단을 써요.","멀리서도 알려요.","전화해요."],"asset":{"type":"passage","lines":["㉠ 늑대가 막내 돼지의 집으로 가고 있어요.","㉡ 놀이공원에서 함께 온 친구가 보이지 않아요.","㉢ 일기 예보를 확인하지 않아 우산을 못 챙겼어요.","㉣ 자동차를 타고 처음 가 보는 곳을 찾아가야 해요."],"title":"통신수단이 필요한 네 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_basic#9','soc',3,2,'u2','L15','g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',2,'ox','auto','통신수단은 한 가지 목적으로만 이용하는 도구예요.',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"ox","stem":"통신수단은 한 가지 목적으로만 이용하는 도구예요.","answer":"X","reason_options":[{"t":"연락하기, 날씨 알아보기, 길 찾기처럼 다양한 목적으로 이용하기 때문에","correct":true},{"t":"통신수단은 위험을 알릴 때만 쓰기 때문에","mis":"SO3-2-u2-X36"}],"mis":"SO3-2-u2-X36","explanation":["네 상황을 봐요.","목적이 여러 가지예요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 늑대가 막내 돼지의 집으로 가고 있어요.","㉡ 놀이공원에서 함께 온 친구가 보이지 않아요.","㉢ 일기 예보를 확인하지 않아 우산을 못 챙겼어요.","㉣ 자동차를 타고 처음 가 보는 곳을 찾아가야 해요."],"title":"통신수단이 필요한 네 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_basic#10','soc',3,2,'u2','L15','g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',3,'mc','auto','전화가 없다면 어떤 일이 생길까요?',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"mc","stem":"전화가 없다면 어떤 일이 생길까요?","options":[{"t":"급하게 전해야 할 소식이 있을 때 직접 가서 전해야 해요","correct":true},{"t":"다른 지역의 소식을 더 쉽게 알 수 있어요","mis":"SO3-2-u2-X36"},{"t":"길을 더 빨리 찾을 수 있어요","mis":"SO3-2-u2-X36"},{"t":"친구와 더 자주 연락할 수 있어요","mis":"SO3-2-u2-X36"}],"explanation":["전화가 하던 일이에요.","누가 대신해야 할까요?","직접 가야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_challenge#1','soc',3,2,'u2','L15','g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',2,'sa','auto','사람이 이동하거나 물건을 옮기는 것은 교통이에요. 소식이나 정보를 주고받는 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"sa","stem":"사람이 이동하거나 물건을 옮기는 것은 교통이에요. 소식이나 정보를 주고받는 것은 무엇인가요? 두 글자로 쓰세요.","answer":["통신"],"explanation":["주고받아요.","통◯이에요.","통신이에요."],"mis":"SO3-2-u2-X35"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_challenge#2','soc',3,2,'u2','L15','g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',2,'ox','auto','편지를 써서 멀리 있는 사람과 소식을 주고받는 것도 통신수단을 이용한 것이에요.',ARRAY['SO3-2-u2-X35']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"ox","stem":"편지를 써서 멀리 있는 사람과 소식을 주고받는 것도 통신수단을 이용한 것이에요.","answer":"O","reason_options":[{"t":"편지도 소식을 주고받을 때 쓰는 방법이기 때문에","correct":true},{"t":"편지는 물건을 옮기는 교통수단이기 때문에","mis":"SO3-2-u2-X35"}],"mis":"SO3-2-u2-X35","explanation":["편지는 소식을 담아요.","주고받아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_challenge#3','soc',3,2,'u2','L15','g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',3,'mc','auto','네 상황에서 이용한 통신수단의 공통점은 무엇인가요?',ARRAY['SO3-2-u2-X35','SO3-2-u2-X36']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"mc","stem":"네 상황에서 이용한 통신수단의 공통점은 무엇인가요?","options":[{"t":"모두 소식이나 정보를 주고받을 때 사용하는 방법이나 도구예요","correct":true},{"t":"모두 사람이 이동하거나 물건을 옮길 때 이용하는 도구예요","mis":"SO3-2-u2-X35"},{"t":"모두 한 가지 목적으로만 이용하는 도구예요","mis":"SO3-2-u2-X36"},{"t":"모두 옛날에만 쓰던 도구예요","mis":"SO3-2-u2-X36"}],"explanation":["무엇을 주고받나요?","소식과 정보예요.","통신수단이에요."],"asset":{"type":"passage","lines":["㉠ 늑대가 막내 돼지의 집으로 가고 있어요.","㉡ 놀이공원에서 함께 온 친구가 보이지 않아요.","㉢ 일기 예보를 확인하지 않아 우산을 못 챙겼어요.","㉣ 자동차를 타고 처음 가 보는 곳을 찾아가야 해요."],"title":"통신수단이 필요한 네 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_challenge#4','soc',3,2,'u2','L15','g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',3,'mc','auto','텔레비전이 없다면 생길 수 있는 일로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X36','SO3-2-u2-X35']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"mc","stem":"텔레비전이 없다면 생길 수 있는 일로 알맞은 것은 무엇인가요?","options":[{"t":"다른 지역의 소식을 알기 어려워요","correct":true},{"t":"길을 더 쉽게 찾아요","mis":"SO3-2-u2-X36"},{"t":"짐을 더 많이 옮겨요","mis":"SO3-2-u2-X35"},{"t":"날씨를 더 빨리 알아요","mis":"SO3-2-u2-X36"}],"explanation":["텔레비전은 소식을 줘요.","없으면 몰라요.","알기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_challenge#5','soc',3,2,'u2','L15','g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',3,'error','auto','통신과 교통을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X35']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"error","stem":"통신과 교통을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「자동차는 소식을 주고받는 통신수단이야.」","correct":true,"mis_target":"SO3-2-u2-X35"},{"t":"친구 가 — 「전화는 통신수단이야.」","mis":"SO3-2-u2-X35"},{"t":"친구 다 — 「버스는 교통수단이야.」","mis":"SO3-2-u2-X35"}],"explanation":["자동차를 봐요.","이동하는 도구예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_challenge#6','soc',3,2,'u2','L15','g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',3,'ox','auto','통신수단이 없어도 멀리 있는 사람에게 소식을 바로 전할 수 있어요.',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"ox","stem":"통신수단이 없어도 멀리 있는 사람에게 소식을 바로 전할 수 있어요.","answer":"X","reason_options":[{"t":"통신수단이 없으면 직접 찾아가야 해서 소식이 늦게 전해지기 때문에","correct":true},{"t":"소식은 저절로 멀리 전해지기 때문에","mis":"SO3-2-u2-X36"}],"mis":"SO3-2-u2-X36","explanation":["없으면 어떻게 하나요?","직접 가야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_challenge#7','soc',3,2,'u2','L15','g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',3,'mc','auto','가족이 이용하는 통신수단 가운데 「새로운 소식을 얻는」 것과 「정보를 찾아보는」 것을 차례대로 고른 것은 무엇인가요?',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"mc","stem":"가족이 이용하는 통신수단 가운데 「새로운 소식을 얻는」 것과 「정보를 찾아보는」 것을 차례대로 고른 것은 무엇인가요?","options":[{"t":"텔레비전, 노트북","correct":true},{"t":"노트북, 텔레비전","mis":"SO3-2-u2-X36"},{"t":"인터폰, 우편물","mis":"SO3-2-u2-X36"},{"t":"우편물, 인터폰","mis":"SO3-2-u2-X36"}],"explanation":["언니가 소식을 얻어요.","남학생이 정보를 찾아요.","텔레비전, 노트북이에요."],"asset":{"type":"passage","lines":["어머니 — 우편물을 확인해요.","아버지 — 현관에서 누가 왔는지 인터폰으로 확인해요.","언니 — 텔레비전으로 새로운 소식을 얻어요.","남학생 — 노트북으로 정보를 찾아봐요."],"title":"어느 가족이 이용하는 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_challenge#8','soc',3,2,'u2','L15','g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',4,'mc','auto','「통신과 통신수단」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X36','SO3-2-u2-X35']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C15","difficulty":4,"kind":"mc","stem":"「통신과 통신수단」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"소식이나 정보를 주고받는 것을 통신, 이때 쓰는 방법이나 도구를 통신수단이라고 하고 사람들은 다양한 목적으로 이용해요","correct":true},{"t":"통신수단은 집 밖에서만 이용해요","mis":"SO3-2-u2-X36"},{"t":"통신수단은 사람이 이동할 때 쓰는 도구예요","mis":"SO3-2-u2-X35"},{"t":"통신수단은 위험을 알릴 때만 써요","mis":"SO3-2-u2-X36"}],"explanation":["통신의 뜻이에요.","통신수단의 뜻이에요.","목적이 다양해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_challenge#9','soc',3,2,'u2','L15','g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',4,'mc','auto','「친구에게 소식을 알리는 방법」으로 통신수단을 이용한 것끼리 모은 것은 무엇인가요?',ARRAY['SO3-2-u2-X35','SO3-2-u2-X36']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C15","difficulty":4,"kind":"mc","stem":"「친구에게 소식을 알리는 방법」으로 통신수단을 이용한 것끼리 모은 것은 무엇인가요?","options":[{"t":"전화하기, 전자 우편 보내기, 문자 메시지 보내기","correct":true},{"t":"자전거 타고 가기, 버스 타고 가기, 걸어가기","mis":"SO3-2-u2-X35"},{"t":"트럭으로 옮기기, 배로 옮기기, 비행기로 옮기기","mis":"SO3-2-u2-X35"},{"t":"소리치기, 손 흔들기, 뛰어가기","mis":"SO3-2-u2-X36"}],"explanation":["도구를 써요.","멀리서도 알려요.","전화·전자 우편·문자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L15_challenge#10','soc',3,2,'u2','L15','g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',4,'essay','teacher','통신수단이 필요했던 내 경험을 하나 쓰고, 그때 이용한 통신수단과 이용한 목적을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C15","difficulty":4,"kind":"essay","stem":"통신수단이 필요했던 내 경험을 하나 쓰고, 그때 이용한 통신수단과 이용한 목적을 쓰세요.","answer_guide":{"answer":"예: 학원이 늦게 끝나 부모님이 걱정하실 것 같았어요. 그때 휴대 전화로 부모님께 전화를 걸었어요. 늦는다는 소식을 알리려는 목적이었어요.","scoring_points":["경험을 썼는가","통신수단을 썼는가","이용한 목적을 썼는가"]},"explanation":["경험을 떠올려요.","통신수단을 써요.","목적을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_basic#1','soc',3,2,'u2','L16','g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',1,'mc','auto','낮에는 연기, 밤에는 불을 피워서 위급한 상황을 알렸던 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"mc","stem":"낮에는 연기, 밤에는 불을 피워서 위급한 상황을 알렸던 통신수단은 무엇인가요?","options":[{"t":"봉수","correct":true},{"t":"서찰","mis":"SO3-2-u2-X37"},{"t":"방","mis":"SO3-2-u2-X37"},{"t":"북","mis":"SO3-2-u2-X37"}],"explanation":["높은 곳에서 피워요.","연기와 불이에요.","봉수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_basic#2','soc',3,2,'u2','L16','g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',1,'sa','auto','일상생활의 안부나 소식을 글로 적어 사람이 직접 전달했던 통신수단을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"sa","stem":"일상생활의 안부나 소식을 글로 적어 사람이 직접 전달했던 통신수단을 두 글자로 쓰세요.","answer":["서찰"],"explanation":["글로 적어요.","서◯이에요.","서찰이에요."],"mis":"SO3-2-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_basic#3','soc',3,2,'u2','L16','g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',1,'ox','auto','옛날 사람들은 북을 쳐서 큰 소리로 소식이나 작전을 알렸어요.',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"ox","stem":"옛날 사람들은 북을 쳐서 큰 소리로 소식이나 작전을 알렸어요.","answer":"O","reason_options":[{"t":"큰 소리는 멀리까지 들리기 때문에","correct":true},{"t":"북은 글을 적어 보내는 도구이기 때문에","mis":"SO3-2-u2-X37"}],"mis":"SO3-2-u2-X37","explanation":["북은 소리가 커요.","멀리 들려요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 서찰 — 안부나 소식을 글로 적어 사람이 직접 전달해요.","㉡ 방 — 나라의 중요한 소식을 사람이 많이 모이는 곳에 붙여요.","㉢ 봉수 — 낮에는 연기, 밤에는 불을 피워 위급함을 알려요.","㉣ 파발 — 나라의 중요한 문서를 말을 타거나 걸어가서 전해요.","㉤ 신호 연 — 암호를 적은 연을 띄워 작전을 알려요.","㉥ 북 — 북을 쳐서 큰 소리로 소식이나 작전을 알려요."],"title":"옛날 통신수단 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_basic#4','soc',3,2,'u2','L16','g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',1,'mc','auto','나라의 중요한 소식을 사람들이 많이 모이는 곳에 글로 써서 붙인 것은 무엇인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"mc","stem":"나라의 중요한 소식을 사람들이 많이 모이는 곳에 글로 써서 붙인 것은 무엇인가요?","options":[{"t":"방","correct":true},{"t":"파발","mis":"SO3-2-u2-X37"},{"t":"봉수","mis":"SO3-2-u2-X37"},{"t":"신호 연","mis":"SO3-2-u2-X37"}],"explanation":["붙여요.","길거리예요.","방이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_basic#5','soc',3,2,'u2','L16','g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',2,'mc','auto','봉수에서 「적이 나타났다」는 것을 알릴 때 올린 연기나 불은 몇 개인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"mc","stem":"봉수에서 「적이 나타났다」는 것을 알릴 때 올린 연기나 불은 몇 개인가요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"SO3-2-u2-X37"},{"t":"3개","mis":"SO3-2-u2-X37"},{"t":"5개","mis":"SO3-2-u2-X37"}],"explanation":["평상시는 1개예요.","그다음이에요.","2개예요."],"asset":{"type":"passage","lines":["적이 없는 평상시 — 1개","적이 나타났어요 — 2개","적이 가까이 왔어요 — 3개","적이 쳐들어왔어요 — 4개","적과 싸움이 시작됐어요 — 5개"],"title":"봉수에 올리는 연기나 불의 개수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_basic#6','soc',3,2,'u2','L16','g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',2,'match','auto','옛날 통신수단과 소식을 전한 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"match","stem":"옛날 통신수단과 소식을 전한 방법을 알맞게 이으세요.","pairs":[{"l":"서찰","r":"글로 적어 사람이 직접 전달"},{"l":"방","r":"많이 모이는 곳에 붙임"},{"l":"파발","r":"말을 타고 문서를 전달"},{"l":"신호 연","r":"암호를 적어 띄움"}],"mis":"SO3-2-u2-X37","explanation":["서찰은 들고 가요.","방은 붙여요.","파발과 신호 연도 이어요."],"asset":{"type":"passage","lines":["㉠ 서찰 — 안부나 소식을 글로 적어 사람이 직접 전달해요.","㉡ 방 — 나라의 중요한 소식을 사람이 많이 모이는 곳에 붙여요.","㉢ 봉수 — 낮에는 연기, 밤에는 불을 피워 위급함을 알려요.","㉣ 파발 — 나라의 중요한 문서를 말을 타거나 걸어가서 전해요.","㉤ 신호 연 — 암호를 적은 연을 띄워 작전을 알려요.","㉥ 북 — 북을 쳐서 큰 소리로 소식이나 작전을 알려요."],"title":"옛날 통신수단 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_basic#7','soc',3,2,'u2','L16','g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',2,'blank','auto','옛날 통신수단은 (    )의 영향을 많이 받았어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"blank","stem":"옛날 통신수단은 (    )의 영향을 많이 받았어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"날씨","correct":true},{"t":"명절","mis":"SO3-2-u2-X38"},{"t":"전기","mis":"SO3-2-u2-X38"},{"t":"인터넷","mis":"SO3-2-u2-X38"}],"explanation":["안개를 떠올려요.","봉수가 안 보여요.","날씨예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_basic#8','soc',3,2,'u2','L16','g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',2,'mc','auto','나라의 중요한 일을 적은 문서를 말을 타고 가거나 걸어가서 전달한 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"mc","stem":"나라의 중요한 일을 적은 문서를 말을 타고 가거나 걸어가서 전달한 통신수단은 무엇인가요?","options":[{"t":"파발","correct":true},{"t":"봉수","mis":"SO3-2-u2-X37"},{"t":"방","mis":"SO3-2-u2-X37"},{"t":"나발","mis":"SO3-2-u2-X37"}],"explanation":["말을 타요.","문서를 전해요.","파발이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_basic#9','soc',3,2,'u2','L16','g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',2,'ox','auto','옛날 사람들은 한 번에 많은 정보를 빠르고 정확하게 주고받았어요.',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"ox","stem":"옛날 사람들은 한 번에 많은 정보를 빠르고 정확하게 주고받았어요.","answer":"X","reason_options":[{"t":"옛날 통신수단은 시간이 오래 걸리고 많은 내용을 자세하게 전하기 어려웠기 때문에","correct":true},{"t":"옛날에는 인터넷이 있었기 때문에","mis":"SO3-2-u2-X38"}],"mis":"SO3-2-u2-X38","explanation":["옛날 특징이에요.","오래 걸렸어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_basic#10','soc',3,2,'u2','L16','g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',3,'mc','auto','안개가 짙게 낀 날 적이 쳐들어왔어요. 봉수 대신 소식을 전하기에 알맞은 방법은 무엇인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X37']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"mc","stem":"안개가 짙게 낀 날 적이 쳐들어왔어요. 봉수 대신 소식을 전하기에 알맞은 방법은 무엇인가요?","options":[{"t":"파발로 문서를 말에 싣고 가서 전해요","correct":true},{"t":"봉수 4개를 그대로 올려요","mis":"SO3-2-u2-X38"},{"t":"방을 붙여 기다려요","mis":"SO3-2-u2-X37"},{"t":"아무것도 하지 않아요","mis":"SO3-2-u2-X38"}],"explanation":["봉수가 안 보여요.","다른 방법이에요.","파발이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_challenge#1','soc',3,2,'u2','L16','g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',2,'sa','auto','봉수에서 「적과 싸움이 시작됐다」는 것을 알릴 때 올린 연기나 불의 개수를 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"sa","stem":"봉수에서 「적과 싸움이 시작됐다」는 것을 알릴 때 올린 연기나 불의 개수를 숫자로 쓰세요.","answer":["5","5개"],"explanation":["가장 위급해요.","가장 많아요.","5개예요."],"asset":{"type":"passage","lines":["적이 없는 평상시 — 1개","적이 나타났어요 — 2개","적이 가까이 왔어요 — 3개","적이 쳐들어왔어요 — 4개","적과 싸움이 시작됐어요 — 5개"],"title":"봉수에 올리는 연기나 불의 개수"},"mis":"SO3-2-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_challenge#2','soc',3,2,'u2','L16','g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',2,'ox','auto','신호 연은 암호를 적은 연을 띄워서 작전이 시작되거나 바뀐 것을 알렸어요.',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"ox","stem":"신호 연은 암호를 적은 연을 띄워서 작전이 시작되거나 바뀐 것을 알렸어요.","answer":"O","reason_options":[{"t":"적들은 연에 표시한 암호를 몰라서 우리 편끼리만 알 수 있었기 때문에","correct":true},{"t":"신호 연은 안부를 적어 할머니께 보냈기 때문에","mis":"SO3-2-u2-X37"}],"mis":"SO3-2-u2-X37","explanation":["하늘에 띄워요.","암호예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_challenge#3','soc',3,2,'u2','L16','g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',3,'mc','auto','봉수에서 연기나 불을 3개 올렸다면 어떤 상황인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"mc","stem":"봉수에서 연기나 불을 3개 올렸다면 어떤 상황인가요?","options":[{"t":"적이 가까이 왔어요","correct":true},{"t":"적이 없는 평상시예요","mis":"SO3-2-u2-X37"},{"t":"적이 나타났어요","mis":"SO3-2-u2-X37"},{"t":"적과 싸움이 시작됐어요","mis":"SO3-2-u2-X37"}],"explanation":["개수를 세요.","세 번째 줄이에요.","가까이 왔어요."],"asset":{"type":"passage","lines":["적이 없는 평상시 — 1개","적이 나타났어요 — 2개","적이 가까이 왔어요 — 3개","적이 쳐들어왔어요 — 4개","적과 싸움이 시작됐어요 — 5개"],"title":"봉수에 올리는 연기나 불의 개수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_challenge#4','soc',3,2,'u2','L16','g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',3,'mc','auto','옛날 통신수단의 특징으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"mc","stem":"옛날 통신수단의 특징으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"여러 사람과 동시에 실시간으로 정보를 주고받았어요","correct":true},{"t":"소식을 전하는 데 시간이 오래 걸렸어요","mis":"SO3-2-u2-X38"},{"t":"날씨의 영향을 많이 받았어요","mis":"SO3-2-u2-X38"},{"t":"많은 내용을 자세하게 전하기 어려웠어요","mis":"SO3-2-u2-X38"}],"explanation":["알맞지 않은 것이에요.","실시간은 오늘날이에요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_challenge#5','soc',3,2,'u2','L16','g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',3,'error','auto','옛날 통신수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"error","stem":"옛날 통신수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「봉수는 일상생활의 안부를 전할 때 주로 썼어.」","correct":true,"mis_target":"SO3-2-u2-X37"},{"t":"친구 가 — 「봉수는 위급한 상황을 알렸어.」","mis":"SO3-2-u2-X37"},{"t":"친구 나 — 「서찰로 안부를 전했어.」","mis":"SO3-2-u2-X37"}],"explanation":["봉수를 봐요.","위급할 때예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 서찰 — 안부나 소식을 글로 적어 사람이 직접 전달해요.","㉡ 방 — 나라의 중요한 소식을 사람이 많이 모이는 곳에 붙여요.","㉢ 봉수 — 낮에는 연기, 밤에는 불을 피워 위급함을 알려요.","㉣ 파발 — 나라의 중요한 문서를 말을 타거나 걸어가서 전해요.","㉤ 신호 연 — 암호를 적은 연을 띄워 작전을 알려요.","㉥ 북 — 북을 쳐서 큰 소리로 소식이나 작전을 알려요."],"title":"옛날 통신수단 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_challenge#6','soc',3,2,'u2','L16','g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',3,'mc','auto','카드 가운데 「소리」로 소식을 알린 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"mc","stem":"카드 가운데 「소리」로 소식을 알린 통신수단은 무엇인가요?","options":[{"t":"㉥","correct":true},{"t":"㉠","mis":"SO3-2-u2-X37"},{"t":"㉢","mis":"SO3-2-u2-X37"},{"t":"㉤","mis":"SO3-2-u2-X37"}],"explanation":["귀로 들어요.","쳐서 소리를 내요.","북이에요."],"asset":{"type":"passage","lines":["㉠ 서찰 — 안부나 소식을 글로 적어 사람이 직접 전달해요.","㉡ 방 — 나라의 중요한 소식을 사람이 많이 모이는 곳에 붙여요.","㉢ 봉수 — 낮에는 연기, 밤에는 불을 피워 위급함을 알려요.","㉣ 파발 — 나라의 중요한 문서를 말을 타거나 걸어가서 전해요.","㉤ 신호 연 — 암호를 적은 연을 띄워 작전을 알려요.","㉥ 북 — 북을 쳐서 큰 소리로 소식이나 작전을 알려요."],"title":"옛날 통신수단 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_challenge#7','soc',3,2,'u2','L16','g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',3,'ox','auto','옛날에는 소식을 전하는 방법이 봉수 하나뿐이었어요.',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"ox","stem":"옛날에는 소식을 전하는 방법이 봉수 하나뿐이었어요.","answer":"X","reason_options":[{"t":"서찰, 방, 파발, 신호 연, 북처럼 다양한 통신수단을 이용했기 때문에","correct":true},{"t":"옛날 사람들은 소식을 주고받지 않았기 때문에","mis":"SO3-2-u2-X37"}],"mis":"SO3-2-u2-X37","explanation":["카드가 여섯 장이에요.","여러 가지예요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 서찰 — 안부나 소식을 글로 적어 사람이 직접 전달해요.","㉡ 방 — 나라의 중요한 소식을 사람이 많이 모이는 곳에 붙여요.","㉢ 봉수 — 낮에는 연기, 밤에는 불을 피워 위급함을 알려요.","㉣ 파발 — 나라의 중요한 문서를 말을 타거나 걸어가서 전해요.","㉤ 신호 연 — 암호를 적은 연을 띄워 작전을 알려요.","㉥ 북 — 북을 쳐서 큰 소리로 소식이나 작전을 알려요."],"title":"옛날 통신수단 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_challenge#8','soc',3,2,'u2','L16','g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',4,'mc','auto','「옛날의 통신수단」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X37','SO3-2-u2-X38']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C16","difficulty":4,"kind":"mc","stem":"「옛날의 통신수단」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"옛날 사람들은 다양한 통신수단을 이용했지만 시간이 오래 걸리고, 자세하게 전하기 어렵고, 날씨의 영향을 받았어요","correct":true},{"t":"옛날에는 위급한 상황이 생겨도 소식을 전할 방법이 없었어요","mis":"SO3-2-u2-X37"},{"t":"봉수만 있으면 날씨와 상관없이 많은 내용을 전할 수 있었어요","mis":"SO3-2-u2-X38"},{"t":"옛날 통신수단은 오늘날보다 빠르고 정확했어요","mis":"SO3-2-u2-X38"}],"explanation":["다양했어요.","특징이 셋이에요.","함께 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_challenge#9','soc',3,2,'u2','L16','g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',4,'mc','auto','봉수가 연기나 불의 「개수」로만 소식을 알렸다는 점에서 알 수 있는 옛날 통신수단의 특징은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C16","difficulty":4,"kind":"mc","stem":"봉수가 연기나 불의 「개수」로만 소식을 알렸다는 점에서 알 수 있는 옛날 통신수단의 특징은 무엇인가요?","options":[{"t":"많은 내용을 자세하고 정확하게 전하기 어려웠어요","correct":true},{"t":"소식을 실시간으로 아주 자세하게 전했어요","mis":"SO3-2-u2-X38"},{"t":"날씨의 영향을 전혀 받지 않았어요","mis":"SO3-2-u2-X38"},{"t":"누구나 집에서 쉽게 이용했어요","mis":"SO3-2-u2-X38"}],"explanation":["개수만 보여요.","자세한 내용은 몰라요.","자세히 전하기 어려웠어요."],"asset":{"type":"passage","lines":["적이 없는 평상시 — 1개","적이 나타났어요 — 2개","적이 가까이 왔어요 — 3개","적이 쳐들어왔어요 — 4개","적과 싸움이 시작됐어요 — 5개"],"title":"봉수에 올리는 연기나 불의 개수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L16_challenge#10','soc',3,2,'u2','L16','g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',4,'essay','teacher','카드의 옛날 통신수단 가운데 하나를 골라 어떻게 소식을 전했는지 쓰고, 그 통신수단의 불편한 점을 옛날 통신수단의 특징과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C16","difficulty":4,"kind":"essay","stem":"카드의 옛날 통신수단 가운데 하나를 골라 어떻게 소식을 전했는지 쓰고, 그 통신수단의 불편한 점을 옛날 통신수단의 특징과 이어 쓰세요.","answer_guide":{"answer":"예: ㉢ 봉수는 낮에는 연기, 밤에는 불을 피워 위급한 상황을 알렸어요. 하지만 안개가 짙거나 구름이 많은 날에는 잘 보이지 않아 소식을 전하기 어려웠어요. 날씨의 영향을 많이 받는 특징이 있어요.","scoring_points":["통신수단을 하나 골랐는가","전하는 방법을 썼는가","불편한 점을 특징과 이었는가"]},"explanation":["하나를 골라요.","방법을 써요.","불편한 점이에요."],"asset":{"type":"passage","lines":["㉠ 서찰 — 안부나 소식을 글로 적어 사람이 직접 전달해요.","㉡ 방 — 나라의 중요한 소식을 사람이 많이 모이는 곳에 붙여요.","㉢ 봉수 — 낮에는 연기, 밤에는 불을 피워 위급함을 알려요.","㉣ 파발 — 나라의 중요한 문서를 말을 타거나 걸어가서 전해요.","㉤ 신호 연 — 암호를 적은 연을 띄워 작전을 알려요.","㉥ 북 — 북을 쳐서 큰 소리로 소식이나 작전을 알려요."],"title":"옛날 통신수단 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_basic#1','soc',3,2,'u2','L17','g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',1,'mc','auto','스마트폰 등을 이용해 어디에서나 대화하거나 정보를 주고받을 수 있는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C17","difficulty":1,"kind":"mc","stem":"스마트폰 등을 이용해 어디에서나 대화하거나 정보를 주고받을 수 있는 통신수단은 무엇인가요?","options":[{"t":"모바일 메신저","correct":true},{"t":"봉수","mis":"SO3-2-u2-X38"},{"t":"신호 연","mis":"SO3-2-u2-X38"},{"t":"방","mis":"SO3-2-u2-X38"}],"explanation":["바로 답장이 와요.","오늘날 것이에요.","모바일 메신저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_basic#2','soc',3,2,'u2','L17','g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',1,'sa','auto','구급 대원이 들고 다니며 바로 말을 전해 구조 헬기를 요청할 때 쓰는 통신수단을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C17","difficulty":1,"kind":"sa","stem":"구급 대원이 들고 다니며 바로 말을 전해 구조 헬기를 요청할 때 쓰는 통신수단을 세 글자로 쓰세요.","answer":["무전기"],"explanation":["들고 다녀요.","무◯◯예요.","무전기예요."],"mis":"SO3-2-u2-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_basic#3','soc',3,2,'u2','L17','g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',1,'ox','auto','학교에서는 스피커로 수업 종소리나 안내 방송이 나와요.',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C17","difficulty":1,"kind":"ox","stem":"학교에서는 스피커로 수업 종소리나 안내 방송이 나와요.","answer":"O","reason_options":[{"t":"스피커는 여러 사람에게 소리로 소식을 알리는 통신수단이기 때문에","correct":true},{"t":"스피커는 학교에서 쓰지 않기 때문에","mis":"SO3-2-u2-X39"}],"mis":"SO3-2-u2-X39","explanation":["학교를 떠올려요.","종소리가 나요.","그래서 O예요."],"asset":{"type":"passage","lines":["· 텔레비전이나 전자 칠판으로 영상을 보면서 공부해요.","· 태블릿 컴퓨터로 궁금한 내용을 찾아봐요.","· 스피커로 수업 종소리나 안내 방송이 나와요.","· 전화기로 다른 교실에 있는 선생님들과 연락해요."],"title":"학교에서 이용하는 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_basic#4','soc',3,2,'u2','L17','g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',1,'mc','auto','부모님이 자녀의 등하교 상황을 확인할 수 있게 해 주는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X39','SO3-2-u2-X38']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C17","difficulty":1,"kind":"mc","stem":"부모님이 자녀의 등하교 상황을 확인할 수 있게 해 주는 통신수단은 무엇인가요?","options":[{"t":"등하교 알리미","correct":true},{"t":"대기 정보 알리미","mis":"SO3-2-u2-X39"},{"t":"디지털 안내판","mis":"SO3-2-u2-X39"},{"t":"신호 깃발","mis":"SO3-2-u2-X38"}],"explanation":["학교에 오가요.","알려 줘요.","등하교 알리미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_basic#5','soc',3,2,'u2','L17','g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',2,'match','auto','말풍선과 이용하는 통신수단을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"match","stem":"말풍선과 이용하는 통신수단을 알맞게 이으세요.","pairs":[{"l":"가","r":"모바일 메신저"},{"l":"나","r":"디지털 안내판"},{"l":"다","r":"대기 정보 알리미"},{"l":"라","r":"등하교 알리미"}],"mis":"SO3-2-u2-X39","explanation":["답장은 메신저예요.","버스는 안내판이에요.","미세 먼지와 등교도 이어요."],"asset":{"type":"speech","turns":[{"who":"가","text":"바로바로 답장을 확인할 수 있으니 편해."},{"who":"나","text":"곧 버스가 도착하겠군."},{"who":"다","text":"오늘은 미세 먼지 없이 깨끗하네."},{"who":"라","text":"학교에 잘 도착했네."},{"who":"마","text":"이쪽으로 구조 헬기를 보내 주세요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_basic#6','soc',3,2,'u2','L17','g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',2,'mc','auto','오늘날 통신수단의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"mc","stem":"오늘날 통신수단의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"여러 사람에게 실시간으로 빠르게 정보를 전달해요","correct":true},{"t":"날씨의 영향을 많이 받아요","mis":"SO3-2-u2-X38"},{"t":"소식을 전하는 데 시간이 오래 걸려요","mis":"SO3-2-u2-X38"},{"t":"많은 내용을 자세하게 전하기 어려워요","mis":"SO3-2-u2-X38"}],"explanation":["오늘날이에요.","빨라요.","실시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_basic#7','soc',3,2,'u2','L17','g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',2,'blank','auto','처음 가는 곳도 길을 찾아갈 수 있게 해 주는 통신수단은 길 도우미, 다른 말로 (    )이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X39','SO3-2-u2-X38']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"blank","stem":"처음 가는 곳도 길을 찾아갈 수 있게 해 주는 통신수단은 길 도우미, 다른 말로 (    )이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"내비게이션","correct":true},{"t":"무선 호출기","mis":"SO3-2-u2-X39"},{"t":"신호 연","mis":"SO3-2-u2-X38"},{"t":"봉수","mis":"SO3-2-u2-X38"}],"explanation":["자동차에 있어요.","길을 알려요.","내비게이션이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_basic#8','soc',3,2,'u2','L17','g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',2,'mc','auto','자료에서 「전화기」로 하는 일은 무엇인가요?',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"mc","stem":"자료에서 「전화기」로 하는 일은 무엇인가요?","options":[{"t":"다른 교실에 있는 선생님들과 연락해요","correct":true},{"t":"영상을 보면서 공부해요","mis":"SO3-2-u2-X39"},{"t":"궁금한 내용을 찾아봐요","mis":"SO3-2-u2-X39"},{"t":"수업 종소리를 내보내요","mis":"SO3-2-u2-X39"}],"explanation":["전화기 줄을 봐요.","선생님끼리예요.","연락해요."],"asset":{"type":"passage","lines":["· 텔레비전이나 전자 칠판으로 영상을 보면서 공부해요.","· 태블릿 컴퓨터로 궁금한 내용을 찾아봐요.","· 스피커로 수업 종소리나 안내 방송이 나와요.","· 전화기로 다른 교실에 있는 선생님들과 연락해요."],"title":"학교에서 이용하는 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_basic#9','soc',3,2,'u2','L17','g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',2,'ox','auto','오늘날에는 모든 장면에서 한 가지 통신수단만 이용해요.',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"ox","stem":"오늘날에는 모든 장면에서 한 가지 통신수단만 이용해요.","answer":"X","reason_options":[{"t":"메신저, 안내판, 알리미, 무전기처럼 장면에 따라 다양한 통신수단을 이용하기 때문에","correct":true},{"t":"오늘날 통신수단은 하나뿐이기 때문에","mis":"SO3-2-u2-X39"}],"mis":"SO3-2-u2-X39","explanation":["장면이 여러 가지예요.","딱지도 여러 장이에요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"가","text":"바로바로 답장을 확인할 수 있으니 편해."},{"who":"나","text":"곧 버스가 도착하겠군."},{"who":"다","text":"오늘은 미세 먼지 없이 깨끗하네."},{"who":"라","text":"학교에 잘 도착했네."},{"who":"마","text":"이쪽으로 구조 헬기를 보내 주세요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_basic#10','soc',3,2,'u2','L17','g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',3,'mc','auto','축구 심판이 규칙에 따라 경고나 퇴장을 알릴 때 쓰는 것은 무엇인가요?',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"mc","stem":"축구 심판이 규칙에 따라 경고나 퇴장을 알릴 때 쓰는 것은 무엇인가요?","options":[{"t":"여러 색의 카드","correct":true},{"t":"마을 안내 방송","mis":"SO3-2-u2-X39"},{"t":"전자 우편","mis":"SO3-2-u2-X39"},{"t":"디지털 안내판","mis":"SO3-2-u2-X39"}],"explanation":["경기장이에요.","노란색·빨간색이에요.","색 카드예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_challenge#1','soc',3,2,'u2','L17','g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',2,'sa','auto','버스 정류장에서 버스가 오는 시각을 미리 알려 주는 통신수단을 「디지털 ○○○」이라고 해요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"sa","stem":"버스 정류장에서 버스가 오는 시각을 미리 알려 주는 통신수단을 「디지털 ○○○」이라고 해요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["안내판"],"explanation":["정류장에 있어요.","안◯◯이에요.","안내판이에요."],"mis":"SO3-2-u2-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_challenge#2','soc',3,2,'u2','L17','g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',2,'ox','auto','교통경찰은 자동차들이 안전하게 이동하도록 수신호와 호루라기를 사용해요.',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"ox","stem":"교통경찰은 자동차들이 안전하게 이동하도록 수신호와 호루라기를 사용해요.","answer":"O","reason_options":[{"t":"하는 일에 따라 알맞은 통신수단을 쓰기 때문에","correct":true},{"t":"교통경찰은 통신수단을 쓰지 않기 때문에","mis":"SO3-2-u2-X39"}],"mis":"SO3-2-u2-X39","explanation":["손으로 신호해요.","소리도 내요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_challenge#3','soc',3,2,'u2','L17','g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',3,'mc','auto','말풍선 「마」에서 구급 대원이 쓰는 통신수단과 쓰는 까닭을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X39']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"mc","stem":"말풍선 「마」에서 구급 대원이 쓰는 통신수단과 쓰는 까닭을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"무전기 — 위급한 상황에서 바로 도움을 요청하려고","correct":true},{"t":"봉수 — 연기로 위급함을 알리려고","mis":"SO3-2-u2-X38"},{"t":"디지털 안내판 — 버스 시각을 알려고","mis":"SO3-2-u2-X39"},{"t":"등하교 알리미 — 등교를 확인하려고","mis":"SO3-2-u2-X39"}],"explanation":["구조 헬기예요.","바로 말해야 해요.","무전기예요."],"asset":{"type":"speech","turns":[{"who":"가","text":"바로바로 답장을 확인할 수 있으니 편해."},{"who":"나","text":"곧 버스가 도착하겠군."},{"who":"다","text":"오늘은 미세 먼지 없이 깨끗하네."},{"who":"라","text":"학교에 잘 도착했네."},{"who":"마","text":"이쪽으로 구조 헬기를 보내 주세요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_challenge#4','soc',3,2,'u2','L17','g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',3,'mc','auto','집들이 서로 떨어져 있거나 농사일을 주로 하는 곳에서 소식을 알리는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X39','SO3-2-u2-X38']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"mc","stem":"집들이 서로 떨어져 있거나 농사일을 주로 하는 곳에서 소식을 알리는 통신수단은 무엇인가요?","options":[{"t":"마을 안내 방송","correct":true},{"t":"축구 심판의 카드","mis":"SO3-2-u2-X39"},{"t":"수신호","mis":"SO3-2-u2-X39"},{"t":"봉수","mis":"SO3-2-u2-X38"}],"explanation":["마을 전체에 알려요.","스피커로 말해요.","마을 안내 방송이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_challenge#5','soc',3,2,'u2','L17','g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',3,'error','auto','오늘날 통신수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X39']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"error","stem":"오늘날 통신수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「오늘날 통신수단은 날씨의 영향을 많이 받아 소식이 늦게 전해져.」","correct":true,"mis_target":"SO3-2-u2-X38"},{"t":"친구 나 — 「모바일 메신저로 바로 답장을 받아.」","mis":"SO3-2-u2-X39"},{"t":"친구 다 — 「여러 사람과 동시에 정보를 주고받아.」","mis":"SO3-2-u2-X38"}],"explanation":["옛날 특징이에요.","오늘날은 빨라요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_challenge#6','soc',3,2,'u2','L17','g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',3,'mc','auto','야구 심판이 멀리서도 잘 보이도록 쓰는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"mc","stem":"야구 심판이 멀리서도 잘 보이도록 쓰는 통신수단은 무엇인가요?","options":[{"t":"수신호","correct":true},{"t":"전자 우편","mis":"SO3-2-u2-X39"},{"t":"무전기","mis":"SO3-2-u2-X39"},{"t":"마을 안내 방송","mis":"SO3-2-u2-X39"}],"explanation":["손으로 해요.","멀리서 보여요.","수신호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_challenge#7','soc',3,2,'u2','L17','g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',3,'ox','auto','오늘날 사람들은 통신수단 없이 직접 찾아가야만 소식을 전할 수 있어요.',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"ox","stem":"오늘날 사람들은 통신수단 없이 직접 찾아가야만 소식을 전할 수 있어요.","answer":"X","reason_options":[{"t":"휴대 전화, 메신저처럼 멀리서도 쉽고 빠르게 소식을 전하는 통신수단이 많기 때문에","correct":true},{"t":"오늘날에는 통신수단이 하나도 없기 때문에","mis":"SO3-2-u2-X38"}],"mis":"SO3-2-u2-X38","explanation":["휴대 전화가 있어요.","멀리서도 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_challenge#8','soc',3,2,'u2','L17','g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',4,'mc','auto','「오늘날의 통신수단」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X39']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C17","difficulty":4,"kind":"mc","stem":"「오늘날의 통신수단」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"과학 기술이 발달하며 생긴 다양한 통신수단으로 여러 사람과 동시에 많은 정보를 실시간으로 주고받아요","correct":true},{"t":"오늘날 통신수단은 날씨의 영향을 많이 받아 자세히 전하기 어려워요","mis":"SO3-2-u2-X38"},{"t":"오늘날 통신수단은 위급한 상황에서만 이용해요","mis":"SO3-2-u2-X39"},{"t":"오늘날에는 한 가지 통신수단만 이용해요","mis":"SO3-2-u2-X39"}],"explanation":["다양해요.","실시간이에요.","여러 사람과 함께예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_challenge#9','soc',3,2,'u2','L17','g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',4,'mc','auto','가족 여행을 준비하며 기차표를 미리 예매하고 방문할 장소를 검색하려고 해요. 알맞은 통신수단끼리 모은 것은 무엇인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X39']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C17","difficulty":4,"kind":"mc","stem":"가족 여행을 준비하며 기차표를 미리 예매하고 방문할 장소를 검색하려고 해요. 알맞은 통신수단끼리 모은 것은 무엇인가요?","options":[{"t":"스마트폰, 태블릿 컴퓨터","correct":true},{"t":"봉수, 파발","mis":"SO3-2-u2-X38"},{"t":"신호 연, 북","mis":"SO3-2-u2-X38"},{"t":"호루라기, 수신호","mis":"SO3-2-u2-X39"}],"explanation":["예매해요.","검색해요.","스마트폰과 태블릿이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L17_challenge#10','soc',3,2,'u2','L17','g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',4,'essay','teacher','말풍선의 장면 가운데 하나를 골라 이용하는 통신수단을 쓰고, 그 통신수단으로 생활이 어떻게 편리해졌는지 오늘날 통신수단의 특징과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C17","difficulty":4,"kind":"essay","stem":"말풍선의 장면 가운데 하나를 골라 이용하는 통신수단을 쓰고, 그 통신수단으로 생활이 어떻게 편리해졌는지 오늘날 통신수단의 특징과 이어 쓰세요.","answer_guide":{"answer":"예: 「나」는 디지털 안내판으로 버스가 오는 시각을 미리 확인해요. 버스가 언제 올지 몰라 오래 기다리지 않아도 돼요. 오늘날 통신수단은 여러 사람에게 실시간으로 정보를 빠르게 알려 줘요.","scoring_points":["장면을 하나 골랐는가","알맞은 통신수단을 썼는가","편리해진 점을 특징과 이었는가"]},"explanation":["장면을 골라요.","통신수단을 써요.","특징과 이어요."],"asset":{"type":"speech","turns":[{"who":"가","text":"바로바로 답장을 확인할 수 있으니 편해."},{"who":"나","text":"곧 버스가 도착하겠군."},{"who":"다","text":"오늘은 미세 먼지 없이 깨끗하네."},{"who":"라","text":"학교에 잘 도착했네."},{"who":"마","text":"이쪽으로 구조 헬기를 보내 주세요!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_basic#1','soc',3,2,'u2','L18','g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',1,'mc','auto','전화를 거는 사람과 받는 사람을 연결해 주다가 점차 사라진 직업은 무엇인가요?',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C18","difficulty":1,"kind":"mc","stem":"전화를 거는 사람과 받는 사람을 연결해 주다가 점차 사라진 직업은 무엇인가요?","options":[{"t":"교환원","correct":true},{"t":"통신 설비 기술자","mis":"SO3-2-u2-X41"},{"t":"촬영 기사","mis":"SO3-2-u2-X41"},{"t":"인공위성 개발자","mis":"SO3-2-u2-X41"}],"explanation":["초기의 전화기예요.","중간에서 이어 줘요.","교환원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_basic#2','soc',3,2,'u2','L18','g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',1,'sa','auto','크기가 작아 들고 다니며 이동하면서 통화할 수 있는 전화를 「○○ 전화」라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C18","difficulty":1,"kind":"sa","stem":"크기가 작아 들고 다니며 이동하면서 통화할 수 있는 전화를 「○○ 전화」라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["휴대"],"explanation":["들고 다녀요.","휴◯예요.","휴대예요."],"mis":"SO3-2-u2-X40"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_basic#3','soc',3,2,'u2','L18','g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',1,'ox','auto','통신수단이 발달하면서 어떤 장소에 직접 가지 않아도 할 수 있는 일이 많아졌어요.',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C18","difficulty":1,"kind":"ox","stem":"통신수단이 발달하면서 어떤 장소에 직접 가지 않아도 할 수 있는 일이 많아졌어요.","answer":"O","reason_options":[{"t":"집에서 인터넷으로 물건을 사고 은행 일을 볼 수 있기 때문에","correct":true},{"t":"통신수단이 발달하면 꼭 직접 가야 하기 때문에","mis":"SO3-2-u2-X44"}],"mis":"SO3-2-u2-X44","explanation":["집에서 해요.","쇼핑과 은행이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["예전 — 시장이나 은행에 직접 갔어요. / 오늘날 — 집에서 인터넷으로 물건을 사고 은행 일을 봐요.","예전 — 직접 만나 회의를 했어요. / 오늘날 — 먼 곳의 사람과 화상 회의를 해요.","예전 — 병원에 직접 가서 진료를 받았어요. / 오늘날 — 직접 가지 않아도 진료를 받을 수 있어요."],"title":"예전과 오늘날의 생활 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_basic#4','soc',3,2,'u2','L18','g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',1,'mc','auto','초기의 전화기의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X40']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C18","difficulty":1,"kind":"mc","stem":"초기의 전화기의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"전화번호를 누르는 숫자 번호판이 없어요","correct":true},{"t":"들고 다닐 수 있어요","mis":"SO3-2-u2-X40"},{"t":"사진을 찍을 수 있어요","mis":"SO3-2-u2-X40"},{"t":"은행 거래를 할 수 있어요","mis":"SO3-2-u2-X40"}],"explanation":["벽에 걸려 있어요.","교환원이 연결해요.","숫자 번호판이 없어요."],"asset":{"type":"passage","lines":["㉮ 벽에 걸려 있고 숫자 번호판이 없어요. 교환원이 중간에서 연결해 줘요.","㉯ 숫자 번호판이 있고 전화선으로 연결돼요. 전화기가 있는 곳으로 가야 통화해요.","㉰ 크기가 작아 들고 다니며 이동하면서 전화할 수 있어요.","㉱ 통화, 사진 촬영, 온라인 쇼핑, 은행 거래 등을 할 수 있어요."],"title":"전화기 카드 넷(차례 섞음 없음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_basic#5','soc',3,2,'u2','L18','g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',2,'match','auto','직업과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"match","stem":"직업과 하는 일을 알맞게 이으세요.","pairs":[{"l":"통신 설비 기술자","r":"기지국을 설치해요"},{"l":"인공위성 개발자","r":"정보를 모으는 인공위성을 만들어요"},{"l":"촬영 기사","r":"영상을 찍어 방송 시간에 맞춰 내보내요"}],"mis":"SO3-2-u2-X41","explanation":["기지국은 설비예요.","인공위성은 개발자예요.","영상은 촬영 기사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_basic#6','soc',3,2,'u2','L18','g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',2,'mc','auto','유선 전화를 쓸 때 사람들의 생활 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X40']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"mc","stem":"유선 전화를 쓸 때 사람들의 생활 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"통화하려면 전화기가 있는 곳으로 가야 해요","correct":true},{"t":"이동하면서 전화할 수 있어요","mis":"SO3-2-u2-X40"},{"t":"교환원과 먼저 이야기해야 해요","mis":"SO3-2-u2-X40"},{"t":"전화로 사진을 보내요","mis":"SO3-2-u2-X40"}],"explanation":["전화선이 있어요.","들고 다닐 수 없어요.","전화기 있는 곳으로 가요."],"asset":{"type":"passage","lines":["㉮ 벽에 걸려 있고 숫자 번호판이 없어요. 교환원이 중간에서 연결해 줘요.","㉯ 숫자 번호판이 있고 전화선으로 연결돼요. 전화기가 있는 곳으로 가야 통화해요.","㉰ 크기가 작아 들고 다니며 이동하면서 전화할 수 있어요.","㉱ 통화, 사진 촬영, 온라인 쇼핑, 은행 거래 등을 할 수 있어요."],"title":"전화기 카드 넷(차례 섞음 없음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_basic#7','soc',3,2,'u2','L18','g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',2,'blank','auto','휴대 전화나 컴퓨터의 통신을 원활하게 해 주는 시설을 (    )이라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"blank","stem":"휴대 전화나 컴퓨터의 통신을 원활하게 해 주는 시설을 (    )이라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"기지국","correct":true},{"t":"봉수대","mis":"SO3-2-u2-X41"},{"t":"주유소","mis":"SO3-2-u2-X41"},{"t":"활주로","mis":"SO3-2-u2-X41"}],"explanation":["전파를 이어 줘요.","기지◯이에요.","기지국이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_basic#8','soc',3,2,'u2','L18','g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',2,'mc','auto','자료에서 오늘날 먼 곳에 있는 사람과 만나지 않고 하는 회의는 무엇인가요?',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"mc","stem":"자료에서 오늘날 먼 곳에 있는 사람과 만나지 않고 하는 회의는 무엇인가요?","options":[{"t":"화상 회의","correct":true},{"t":"편지 회의","mis":"SO3-2-u2-X44"},{"t":"봉수 회의","mis":"SO3-2-u2-X44"},{"t":"파발 회의","mis":"SO3-2-u2-X44"}],"explanation":["화면으로 봐요.","먼 곳이에요.","화상 회의예요."],"asset":{"type":"passage","lines":["예전 — 시장이나 은행에 직접 갔어요. / 오늘날 — 집에서 인터넷으로 물건을 사고 은행 일을 봐요.","예전 — 직접 만나 회의를 했어요. / 오늘날 — 먼 곳의 사람과 화상 회의를 해요.","예전 — 병원에 직접 가서 진료를 받았어요. / 오늘날 — 직접 가지 않아도 진료를 받을 수 있어요."],"title":"예전과 오늘날의 생활 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_basic#9','soc',3,2,'u2','L18','g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',2,'ox','auto','통신수단이 발달하면서 새로운 직업은 하나도 생기지 않았어요.',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"ox","stem":"통신수단이 발달하면서 새로운 직업은 하나도 생기지 않았어요.","answer":"X","reason_options":[{"t":"통신 설비 기술자, 인공위성 개발자처럼 새로운 직업이 생겼기 때문에","correct":true},{"t":"직업은 통신수단과 관계가 없기 때문에","mis":"SO3-2-u2-X41"}],"mis":"SO3-2-u2-X41","explanation":["새 직업이 있어요.","기지국을 세워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_basic#10','soc',3,2,'u2','L18','g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',3,'mc','auto','전화기 카드를 옛날부터 오늘날까지 차례대로 놓은 것은 무엇인가요?',ARRAY['SO3-2-u2-X40']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"mc","stem":"전화기 카드를 옛날부터 오늘날까지 차례대로 놓은 것은 무엇인가요?","options":[{"t":"㉮ → ㉯ → ㉰ → ㉱","correct":true},{"t":"㉱ → ㉰ → ㉯ → ㉮","mis":"SO3-2-u2-X40"},{"t":"㉯ → ㉮ → ㉱ → ㉰","mis":"SO3-2-u2-X40"},{"t":"㉰ → ㉮ → ㉯ → ㉱","mis":"SO3-2-u2-X40"}],"explanation":["교환원이 먼저예요.","번호판, 휴대 순서예요.","㉮부터 ㉱예요."],"asset":{"type":"passage","lines":["㉮ 벽에 걸려 있고 숫자 번호판이 없어요. 교환원이 중간에서 연결해 줘요.","㉯ 숫자 번호판이 있고 전화선으로 연결돼요. 전화기가 있는 곳으로 가야 통화해요.","㉰ 크기가 작아 들고 다니며 이동하면서 전화할 수 있어요.","㉱ 통화, 사진 촬영, 온라인 쇼핑, 은행 거래 등을 할 수 있어요."],"title":"전화기 카드 넷(차례 섞음 없음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_challenge#1','soc',3,2,'u2','L18','g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',2,'sa','auto','전화번호나 음성 메시지를 남겨 호출하던 통신수단으로, 휴대 전화가 발달하면서 사라져 가는 것을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"sa","stem":"전화번호나 음성 메시지를 남겨 호출하던 통신수단으로, 휴대 전화가 발달하면서 사라져 가는 것을 쓰세요.","answer":["무선 호출기","무선호출기"],"explanation":["호출해요.","무선 ◯◯◯예요.","무선 호출기예요."],"mis":"SO3-2-u2-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_challenge#2','soc',3,2,'u2','L18','g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',2,'ox','auto','공중전화를 이용할 때는 동전이나 전화 카드가 필요해요.',ARRAY['SO3-2-u2-X40']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"ox","stem":"공중전화를 이용할 때는 동전이나 전화 카드가 필요해요.","answer":"O","reason_options":[{"t":"공중전화는 여러 사람이 함께 쓰는 유선 전화이기 때문에","correct":true},{"t":"공중전화는 사진을 찍는 기계이기 때문에","mis":"SO3-2-u2-X40"}],"mis":"SO3-2-u2-X40","explanation":["유선 전화예요.","동전을 넣어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_challenge#3','soc',3,2,'u2','L18','g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',3,'mc','auto','카드 ㉯에서 ㉰로 바뀌면서 달라진 생활 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X40']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"mc","stem":"카드 ㉯에서 ㉰로 바뀌면서 달라진 생활 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"자리를 비워도 이동하면서 전화를 받을 수 있게 됐어요","correct":true},{"t":"교환원이 꼭 연결해 줘야 하게 됐어요","mis":"SO3-2-u2-X40"},{"t":"전화기가 있는 곳으로 가야만 통화하게 됐어요","mis":"SO3-2-u2-X40"},{"t":"숫자 번호판이 없어졌어요","mis":"SO3-2-u2-X40"}],"explanation":["유선에서 휴대로요.","들고 다녀요.","이동하며 받아요."],"asset":{"type":"passage","lines":["㉮ 벽에 걸려 있고 숫자 번호판이 없어요. 교환원이 중간에서 연결해 줘요.","㉯ 숫자 번호판이 있고 전화선으로 연결돼요. 전화기가 있는 곳으로 가야 통화해요.","㉰ 크기가 작아 들고 다니며 이동하면서 전화할 수 있어요.","㉱ 통화, 사진 촬영, 온라인 쇼핑, 은행 거래 등을 할 수 있어요."],"title":"전화기 카드 넷(차례 섞음 없음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_challenge#4','soc',3,2,'u2','L18','g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',3,'mc','auto','스마트 시티 상황실에서 폐회로 텔레비전과 인터넷을 활용해 사람들의 안전을 지키는 직업은 무엇인가요?',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"mc","stem":"스마트 시티 상황실에서 폐회로 텔레비전과 인터넷을 활용해 사람들의 안전을 지키는 직업은 무엇인가요?","options":[{"t":"폐회로 텔레비전 통합 관제 요원","correct":true},{"t":"교환원","mis":"SO3-2-u2-X41"},{"t":"촬영 기사","mis":"SO3-2-u2-X41"},{"t":"인공위성 개발자","mis":"SO3-2-u2-X41"}],"explanation":["상황실에서 화면을 봐요.","안전을 지켜요.","관제 요원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_challenge#5','soc',3,2,'u2','L18','g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',3,'error','auto','전화기의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X40']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"error","stem":"전화기의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「오늘날 휴대 전화도 교환원이 연결해 줘야 통화할 수 있어.」","correct":true,"mis_target":"SO3-2-u2-X40"},{"t":"친구 가 — 「초기의 전화기는 교환원이 연결해 줬어.」","mis":"SO3-2-u2-X40"},{"t":"친구 다 — 「오늘날 휴대 전화로 은행 거래도 해.」","mis":"SO3-2-u2-X40"}],"explanation":["오늘날을 봐요.","직접 걸어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉮ 벽에 걸려 있고 숫자 번호판이 없어요. 교환원이 중간에서 연결해 줘요.","㉯ 숫자 번호판이 있고 전화선으로 연결돼요. 전화기가 있는 곳으로 가야 통화해요.","㉰ 크기가 작아 들고 다니며 이동하면서 전화할 수 있어요.","㉱ 통화, 사진 촬영, 온라인 쇼핑, 은행 거래 등을 할 수 있어요."],"title":"전화기 카드 넷(차례 섞음 없음)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_challenge#6','soc',3,2,'u2','L18','g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',3,'mc','auto','디지털 배움터에서 배울 수 있는 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X41']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"mc","stem":"디지털 배움터에서 배울 수 있는 것으로 알맞은 것은 무엇인가요?","options":[{"t":"키오스크에서 음식을 주문하는 방법","correct":true},{"t":"봉수 올리는 방법","mis":"SO3-2-u2-X38"},{"t":"파발 말 타는 방법","mis":"SO3-2-u2-X38"},{"t":"교환원이 되는 방법","mis":"SO3-2-u2-X41"}],"explanation":["새 기술을 익혀요.","주문 기계예요.","키오스크예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_challenge#7','soc',3,2,'u2','L18','g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',3,'ox','auto','통신수단의 변화로 생활이 편리해졌지만 변화의 속도를 따라가기 힘든 사람들도 있어요.',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"ox","stem":"통신수단의 변화로 생활이 편리해졌지만 변화의 속도를 따라가기 힘든 사람들도 있어요.","answer":"O","reason_options":[{"t":"새로운 기능을 익히기 어려운 사람이 있어 주변을 살피고 배려해야 하기 때문에","correct":true},{"t":"모든 사람이 새 통신수단을 똑같이 잘 쓰기 때문에","mis":"SO3-2-u2-X41"}],"mis":"SO3-2-u2-X41","explanation":["어려운 사람도 있어요.","배려가 필요해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_challenge#8','soc',3,2,'u2','L18','g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',4,'mc','auto','「통신수단의 변화로 달라진 생활」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X41','SO3-2-u2-X40']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C18","difficulty":4,"kind":"mc","stem":"「통신수단의 변화로 달라진 생활」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"통신수단이 발달하며 언제 어디서나 정보를 쉽고 빠르게 주고받고, 새로운 시설과 직업이 생기고 사라진 것도 있어요","correct":true},{"t":"통신수단이 발달해도 사람들의 생활 모습은 옛날과 똑같아요","mis":"SO3-2-u2-X44"},{"t":"통신수단이 발달하면서 새로운 직업은 하나도 생기지 않았어요","mis":"SO3-2-u2-X41"},{"t":"전화기는 모양만 바뀌었을 뿐 이용하는 모습은 그대로예요","mis":"SO3-2-u2-X40"}],"explanation":["편리해졌어요.","생기고 사라졌어요.","함께 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_challenge#9','soc',3,2,'u2','L18','g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',4,'mc','auto','예전에는 병원에 직접 가서 진료를 받았지만 오늘날에는 그러지 않아도 되는 경우가 생겼어요. 이것을 가장 바르게 설명한 것은 무엇인가요?',ARRAY['SO3-2-u2-X35','SO3-2-u2-X44','SO3-2-u2-X38']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C18","difficulty":4,"kind":"mc","stem":"예전에는 병원에 직접 가서 진료를 받았지만 오늘날에는 그러지 않아도 되는 경우가 생겼어요. 이것을 가장 바르게 설명한 것은 무엇인가요?","options":[{"t":"통신수단의 발달로 직접 가지 않아도 할 수 있는 일이 많아진 모습이에요","correct":true},{"t":"교통수단이 사라져서 생긴 모습이에요","mis":"SO3-2-u2-X35"},{"t":"병원이 모두 문을 닫아서 생긴 모습이에요","mis":"SO3-2-u2-X44"},{"t":"옛날 통신수단이 다시 쓰이게 된 모습이에요","mis":"SO3-2-u2-X38"}],"explanation":["직접 가지 않아요.","통신수단 덕분이에요.","할 수 있는 일이 늘었어요."],"asset":{"type":"passage","lines":["예전 — 시장이나 은행에 직접 갔어요. / 오늘날 — 집에서 인터넷으로 물건을 사고 은행 일을 봐요.","예전 — 직접 만나 회의를 했어요. / 오늘날 — 먼 곳의 사람과 화상 회의를 해요.","예전 — 병원에 직접 가서 진료를 받았어요. / 오늘날 — 직접 가지 않아도 진료를 받을 수 있어요."],"title":"예전과 오늘날의 생활 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L18_challenge#10','soc',3,2,'u2','L18','g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',4,'essay','teacher','자료의 예전과 오늘날 생활 가운데 하나를 골라 어떻게 달라졌는지 쓰고, 이 변화가 우리 생활에 준 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C18","difficulty":4,"kind":"essay","stem":"자료의 예전과 오늘날 생활 가운데 하나를 골라 어떻게 달라졌는지 쓰고, 이 변화가 우리 생활에 준 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 예전에는 시장이나 은행에 직접 갔지만 오늘날에는 집에서 인터넷으로 물건을 사고 은행 일을 봐요. 멀리 가지 않아도 되어 시간을 아끼고 생활이 편리해졌어요.","scoring_points":["하나를 골랐는가","예전과 오늘날을 견주었는가","좋은 점을 썼는가"]},"explanation":["하나를 골라요.","견줘요.","좋은 점을 써요."],"asset":{"type":"passage","lines":["예전 — 시장이나 은행에 직접 갔어요. / 오늘날 — 집에서 인터넷으로 물건을 사고 은행 일을 봐요.","예전 — 직접 만나 회의를 했어요. / 오늘날 — 먼 곳의 사람과 화상 회의를 해요.","예전 — 병원에 직접 가서 진료를 받았어요. / 오늘날 — 직접 가지 않아도 진료를 받을 수 있어요."],"title":"예전과 오늘날의 생활 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_basic#1','soc',3,2,'u2','L19','g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',1,'mc','auto','일상생활에 문제가 생길 정도로 스마트폰을 지나치게 사용하는 것을 무엇이라고 하나요?',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C19","difficulty":1,"kind":"mc","stem":"일상생활에 문제가 생길 정도로 스마트폰을 지나치게 사용하는 것을 무엇이라고 하나요?","options":[{"t":"스마트폰 과의존","correct":true},{"t":"스마트폰 예절","mis":"SO3-2-u2-X42"},{"t":"화상 회의","mis":"SO3-2-u2-X42"},{"t":"인터넷 검색","mis":"SO3-2-u2-X42"}],"explanation":["지나치게 기대요.","과◯◯이에요.","스마트폰 과의존이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_basic#2','soc',3,2,'u2','L19','g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',1,'sa','auto','공공장소에서는 휴대 전화 소리를 무엇으로 바꾸어야 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C19","difficulty":1,"kind":"sa","stem":"공공장소에서는 휴대 전화 소리를 무엇으로 바꾸어야 하나요? 두 글자로 쓰세요.","answer":["진동"],"explanation":["소리가 나지 않아요.","부르르 떨어요.","진동이에요."],"mis":"SO3-2-u2-X43"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_basic#3','soc',3,2,'u2','L19','g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',1,'ox','auto','다른 사람의 모습을 허락 없이 사진으로 찍으면 안 돼요.',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C19","difficulty":1,"kind":"ox","stem":"다른 사람의 모습을 허락 없이 사진으로 찍으면 안 돼요.","answer":"O","reason_options":[{"t":"찍힌 사람에게 피해를 줄 수 있기 때문에","correct":true},{"t":"사진은 아무나 마음대로 찍어도 되기 때문에","mis":"SO3-2-u2-X43"}],"mis":"SO3-2-u2-X43","explanation":["허락이 필요해요.","피해를 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_basic#4','soc',3,2,'u2','L19','g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',1,'mc','auto','공공장소에서 휴대 전화를 이용하는 바른 모습은 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C19","difficulty":1,"kind":"mc","stem":"공공장소에서 휴대 전화를 이용하는 바른 모습은 무엇인가요?","options":[{"t":"작은 소리로 짧게 통화해요","correct":true},{"t":"큰 소리로 오래 통화해요","mis":"SO3-2-u2-X43"},{"t":"걸어 다니면서 동영상을 봐요","mis":"SO3-2-u2-X43"},{"t":"다른 사람의 모습을 허락 없이 찍어요","mis":"SO3-2-u2-X43"}],"explanation":["여러 사람이 있어요.","피해를 주지 않아요.","작은 소리로 짧게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_basic#5','soc',3,2,'u2','L19','g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',2,'match','auto','빨간불 장면과 생길 수 있는 문제를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"match","stem":"빨간불 장면과 생길 수 있는 문제를 알맞게 이으세요.","pairs":[{"l":"㉠","r":"차가 다가와도 알아차리기 어려워요"},{"l":"㉡","r":"주변 사람들에게 피해를 줘요"},{"l":"㉢","r":"다른 사람의 마음을 아프게 해요"},{"l":"㉤","r":"몸이 아프고 건강을 해쳐요"}],"mis":"SO3-2-u2-X42","explanation":["㉠은 길이에요.","㉡은 공공장소예요.","㉢과 ㉤도 이어요."],"asset":{"type":"passage","lines":["㉠ 이어폰을 끼고 동영상을 보면서 길을 걸어요.","㉡ 여러 사람이 있는 곳에서 큰 소리로 통화해요.","㉢ 다른 사람에게 상처 주는 댓글을 써요.","㉣ 다른 사람의 모습을 허락 없이 사진으로 찍어요.","㉤ 나쁜 자세로 컴퓨터 게임을 오래 해요."],"title":"빨간불이 켜진 다섯 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_basic#6','soc',3,2,'u2','L19','g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',2,'mc','auto','통신수단을 안전하고 올바르게 사용해야 하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X42','SO3-2-u2-X43']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"mc","stem":"통신수단을 안전하고 올바르게 사용해야 하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"우리 모두의 몸과 마음의 건강을 위해서","correct":true},{"t":"통신수단을 더 오래 쓰기 위해서","mis":"SO3-2-u2-X42"},{"t":"새로운 통신수단을 빨리 사기 위해서","mis":"SO3-2-u2-X42"},{"t":"다른 사람의 사진을 많이 찍기 위해서","mis":"SO3-2-u2-X43"}],"explanation":["잘못 쓰면 해쳐요.","몸과 마음이에요.","건강을 위해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_basic#7','soc',3,2,'u2','L19','g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',2,'blank','auto','인터넷에서 글을 쓸 때는 바른 표현을 사용하고, (    ) 정보는 올리지 않아요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"blank","stem":"인터넷에서 글을 쓸 때는 바른 표현을 사용하고, (    ) 정보는 올리지 않아요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"확인되지 않은","correct":true},{"t":"재미있는","mis":"SO3-2-u2-X43"},{"t":"새로운","mis":"SO3-2-u2-X43"},{"t":"짧은","mis":"SO3-2-u2-X43"}],"explanation":["사실인지 몰라요.","확인이 필요해요.","확인되지 않은 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_basic#8','soc',3,2,'u2','L19','g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',2,'mc','auto','통신수단을 올바르게 이용하지 않는 사례는 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"mc","stem":"통신수단을 올바르게 이용하지 않는 사례는 무엇인가요?","options":[{"t":"개인 정보를 본인의 허락 없이 알려요","correct":true},{"t":"인터넷 예절을 지켜요","mis":"SO3-2-u2-X43"},{"t":"정한 시간에만 사용해요","mis":"SO3-2-u2-X43"},{"t":"공공장소에서 작은 소리로 통화해요","mis":"SO3-2-u2-X43"}],"explanation":["올바르지 않은 것이에요.","허락이 필요해요.","개인 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_basic#9','soc',3,2,'u2','L19','g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',2,'ox','auto','통신수단은 편리하니까 아무 때나 마음껏 이용해도 돼요.',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"ox","stem":"통신수단은 편리하니까 아무 때나 마음껏 이용해도 돼요.","answer":"X","reason_options":[{"t":"지나치게 쓰면 몸과 마음의 건강을 해치고 다른 사람에게 피해를 줄 수 있기 때문에","correct":true},{"t":"통신수단은 아무리 써도 문제가 생기지 않기 때문에","mis":"SO3-2-u2-X42"}],"mis":"SO3-2-u2-X42","explanation":["과의존이 있어요.","정한 시간에 써요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_basic#10','soc',3,2,'u2','L19','g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',3,'mc','auto','빨간불 장면 ㉠에 초록불을 켜는 약속으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C19","difficulty":3,"kind":"mc","stem":"빨간불 장면 ㉠에 초록불을 켜는 약속으로 알맞은 것은 무엇인가요?","options":[{"t":"걸어 다니면서 휴대 전화를 보지 않겠습니다","correct":true},{"t":"꼭 필요한 시간에만 사용하겠습니다","mis":"SO3-2-u2-X43"},{"t":"더 큰 소리로 통화하겠습니다","mis":"SO3-2-u2-X43"},{"t":"아무 때나 계속 확인하겠습니다","mis":"SO3-2-u2-X43"}],"explanation":["길에서 생긴 일이에요.","안전이에요.","걸으며 보지 않아요."],"asset":{"type":"passage","lines":["㉠ 이어폰을 끼고 동영상을 보면서 길을 걸어요.","㉡ 여러 사람이 있는 곳에서 큰 소리로 통화해요.","㉢ 다른 사람에게 상처 주는 댓글을 써요.","㉣ 다른 사람의 모습을 허락 없이 사진으로 찍어요.","㉤ 나쁜 자세로 컴퓨터 게임을 오래 해요."],"title":"빨간불이 켜진 다섯 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_challenge#1','soc',3,2,'u2','L19','g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',2,'sa','auto','학교나 가정에서 지켜야 하는 예절이 있듯이, 통신수단을 이용할 때 지켜야 하는 예절을 「○○ 예절」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"sa","stem":"학교나 가정에서 지켜야 하는 예절이 있듯이, 통신수단을 이용할 때 지켜야 하는 예절을 「○○ 예절」이라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["통신"],"explanation":["통신수단을 쓸 때예요.","통◯이에요.","통신이에요."],"mis":"SO3-2-u2-X43"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_challenge#2','soc',3,2,'u2','L19','g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',2,'ox','auto','통신수단을 잘못 이용해도 문제는 나 혼자에게만 생겨요.',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"ox","stem":"통신수단을 잘못 이용해도 문제는 나 혼자에게만 생겨요.","answer":"X","reason_options":[{"t":"큰 소리 통화나 상처 주는 댓글처럼 다른 사람에게도 피해를 주기 때문에","correct":true},{"t":"통신수단은 혼자만 쓰는 것이기 때문에","mis":"SO3-2-u2-X42"}],"mis":"SO3-2-u2-X42","explanation":["㉡, ㉢을 봐요.","다른 사람도 피해를 봐요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 이어폰을 끼고 동영상을 보면서 길을 걸어요.","㉡ 여러 사람이 있는 곳에서 큰 소리로 통화해요.","㉢ 다른 사람에게 상처 주는 댓글을 써요.","㉣ 다른 사람의 모습을 허락 없이 사진으로 찍어요.","㉤ 나쁜 자세로 컴퓨터 게임을 오래 해요."],"title":"빨간불이 켜진 다섯 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_challenge#3','soc',3,2,'u2','L19','g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',3,'mc','auto','빨간불 장면 ㉤에 초록불을 켜는 약속으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X42','SO3-2-u2-X43']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C19","difficulty":3,"kind":"mc","stem":"빨간불 장면 ㉤에 초록불을 켜는 약속으로 알맞은 것은 무엇인가요?","options":[{"t":"꼭 필요한 시간에만 사용하겠습니다","correct":true},{"t":"사용 시간을 정하지 않겠습니다","mis":"SO3-2-u2-X42"},{"t":"더 오래 게임하겠습니다","mis":"SO3-2-u2-X42"},{"t":"걸으면서 게임하겠습니다","mis":"SO3-2-u2-X43"}],"explanation":["오래 하면 아파요.","시간을 정해요.","필요한 시간에만요."],"asset":{"type":"passage","lines":["㉠ 이어폰을 끼고 동영상을 보면서 길을 걸어요.","㉡ 여러 사람이 있는 곳에서 큰 소리로 통화해요.","㉢ 다른 사람에게 상처 주는 댓글을 써요.","㉣ 다른 사람의 모습을 허락 없이 사진으로 찍어요.","㉤ 나쁜 자세로 컴퓨터 게임을 오래 해요."],"title":"빨간불이 켜진 다섯 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_challenge#4','soc',3,2,'u2','L19','g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',3,'mc','auto','스마트폰 과의존 표에 표시한 개수가 3~4개일 때의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C19","difficulty":3,"kind":"mc","stem":"스마트폰 과의존 표에 표시한 개수가 3~4개일 때의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"주의가 필요해요","correct":true},{"t":"괜찮아요","mis":"SO3-2-u2-X42"},{"t":"스마트폰을 더 많이 써도 돼요","mis":"SO3-2-u2-X42"},{"t":"아무 뜻이 없어요","mis":"SO3-2-u2-X42"}],"explanation":["0~2, 3~4, 5~8이에요.","가운데 칸이에요.","주의가 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_challenge#5','soc',3,2,'u2','L19','g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',3,'error','auto','통신 예절을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C19","difficulty":3,"kind":"error","stem":"통신 예절을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「재미있는 소문은 확인하지 않고 바로 올려도 돼.」","correct":true,"mis_target":"SO3-2-u2-X43"},{"t":"친구 가 — 「댓글은 바른 표현으로 써.」","mis":"SO3-2-u2-X43"},{"t":"친구 나 — 「개인 정보가 새어 나가지 않게 조심해.」","mis":"SO3-2-u2-X43"}],"explanation":["소문을 봐요.","확인해야 해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
