INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_challenge#7','soc',3,2,'u2','L19','g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',3,'ox','auto','통신수단을 올바르게 이용하려면 통신수단을 아예 쓰지 않아야 해요.',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C19","difficulty":3,"kind":"ox","stem":"통신수단을 올바르게 이용하려면 통신수단을 아예 쓰지 않아야 해요.","answer":"X","reason_options":[{"t":"통신 예절을 지키며 때와 장소에 맞게 안전하고 올바르게 쓰면 되기 때문에","correct":true},{"t":"통신수단은 나쁜 물건이기 때문에","mis":"SO3-2-u2-X42"}],"mis":"SO3-2-u2-X42","explanation":["아예 안 쓰는 것이 아니에요.","바르게 써요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_challenge#8','soc',3,2,'u2','L19','g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',4,'mc','auto','「통신수단의 올바른 이용」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X42','SO3-2-u2-X43']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C19","difficulty":4,"kind":"mc","stem":"「통신수단의 올바른 이용」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"통신수단을 올바르게 쓰지 않으면 건강을 해치고 남에게 피해를 주므로, 통신 예절을 지키며 때와 장소에 맞게 써요","correct":true},{"t":"통신수단은 언제 어디서 어떻게 써도 아무 문제가 없어요","mis":"SO3-2-u2-X42"},{"t":"통신수단을 쓸 때는 지켜야 할 예절이 따로 없어요","mis":"SO3-2-u2-X43"},{"t":"문제가 있으니 통신수단을 모두 버려야 해요","mis":"SO3-2-u2-X42"}],"explanation":["문제가 생겨요.","예절을 지켜요.","때와 장소에 맞게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_challenge#9','soc',3,2,'u2','L19','g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',4,'mc','auto','도서관에서 친구에게 전화가 왔어요. 가장 알맞게 행동한 것은 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C19","difficulty":4,"kind":"mc","stem":"도서관에서 친구에게 전화가 왔어요. 가장 알맞게 행동한 것은 무엇인가요?","options":[{"t":"진동으로 받아 작은 소리로 짧게 말하고, 길게 할 이야기는 밖에서 해요","correct":true},{"t":"큰 소리로 오래 통화해요","mis":"SO3-2-u2-X43"},{"t":"스피커를 켜고 모두 듣게 해요","mis":"SO3-2-u2-X43"},{"t":"전화를 받으며 다른 사람 사진을 찍어요","mis":"SO3-2-u2-X43"}],"explanation":["공공장소예요.","조용해야 해요.","작게, 짧게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L19_challenge#10','soc',3,2,'u2','L19','g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',4,'essay','teacher','빨간불 장면 가운데 하나를 골라 어떤 문제가 생기는지 쓰고, 그 장면에 초록불을 켜는 우리의 약속을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C19","difficulty":4,"kind":"essay","stem":"빨간불 장면 가운데 하나를 골라 어떤 문제가 생기는지 쓰고, 그 장면에 초록불을 켜는 우리의 약속을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: ㉢처럼 다른 사람에게 상처 주는 댓글을 쓰면 그 사람의 마음을 아프게 해요. 「인터넷에서는 바른 표현으로 글을 쓰겠습니다.」","scoring_points":["장면을 하나 골랐는가","생기는 문제를 썼는가","알맞은 약속을 썼는가"]},"explanation":["장면을 골라요.","문제를 써요.","약속을 써요."],"asset":{"type":"passage","lines":["㉠ 이어폰을 끼고 동영상을 보면서 길을 걸어요.","㉡ 여러 사람이 있는 곳에서 큰 소리로 통화해요.","㉢ 다른 사람에게 상처 주는 댓글을 써요.","㉣ 다른 사람의 모습을 허락 없이 사진으로 찍어요.","㉤ 나쁜 자세로 컴퓨터 게임을 오래 해요."],"title":"빨간불이 켜진 다섯 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_basic#1','soc',3,2,'u2','L20','g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',1,'mc','auto','잠금 단서 다섯 가운데 옳지 않은 설명은 무엇인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X41']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C20","difficulty":1,"kind":"mc","stem":"잠금 단서 다섯 가운데 옳지 않은 설명은 무엇인가요?","options":[{"t":"단서 2","correct":true},{"t":"단서 1","mis":"SO3-2-u2-X38"},{"t":"단서 3","mis":"SO3-2-u2-X38"},{"t":"단서 4","mis":"SO3-2-u2-X41"}],"explanation":["서찰·방·파발을 봐요.","옛날 것이에요.","단서 2예요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고 시간이 오래 걸렸어요.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용해요.","단서 3 — 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있어요.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났어요.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 해요."],"title":"휴대 전화 잠금 단서 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_basic#2','soc',3,2,'u2','L20','g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',1,'sa','auto','옛날 사람들이 소식을 전할 때 쓰던 통신수단 가운데, 나라의 중요한 문서를 말을 타고 전한 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C20","difficulty":1,"kind":"sa","stem":"옛날 사람들이 소식을 전할 때 쓰던 통신수단 가운데, 나라의 중요한 문서를 말을 타고 전한 것을 두 글자로 쓰세요.","answer":["파발"],"explanation":["말을 타요.","파◯이에요.","파발이에요."],"mis":"SO3-2-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_basic#3','soc',3,2,'u2','L20','g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',1,'ox','auto','통신수단이 발달하면서 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있어요.',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C20","difficulty":1,"kind":"ox","stem":"통신수단이 발달하면서 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있어요.","answer":"O","reason_options":[{"t":"휴대 전화와 인터넷으로 정보를 바로 주고받기 때문에","correct":true},{"t":"오늘날에도 봉수로만 소식을 전하기 때문에","mis":"SO3-2-u2-X38"}],"mis":"SO3-2-u2-X38","explanation":["단서 3이에요.","실시간이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고 시간이 오래 걸렸어요.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용해요.","단서 3 — 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있어요.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났어요.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 해요."],"title":"휴대 전화 잠금 단서 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_basic#4','soc',3,2,'u2','L20','g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',1,'mc','auto','옛날 사람들이 쓰던 통신수단이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C20","difficulty":1,"kind":"mc","stem":"옛날 사람들이 쓰던 통신수단이 아닌 것은 무엇인가요?","options":[{"t":"모바일 메신저","correct":true},{"t":"서찰","mis":"SO3-2-u2-X37"},{"t":"방","mis":"SO3-2-u2-X37"},{"t":"파발","mis":"SO3-2-u2-X37"}],"explanation":["오늘날 것을 찾아요.","스마트폰으로 써요.","모바일 메신저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_basic#5','soc',3,2,'u2','L20','g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',2,'match','auto','통신수단을 옛날과 오늘날로 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"match","stem":"통신수단을 옛날과 오늘날로 알맞게 이으세요.","pairs":[{"l":"봉수","r":"옛날 — 연기와 불"},{"l":"휴대 전화","r":"오늘날 — 통화와 인터넷"},{"l":"방","r":"옛날 — 글을 써서 붙임"},{"l":"길 도우미","r":"오늘날 — 길 안내"}],"mis":"SO3-2-u2-X44","explanation":["봉수와 방은 옛날이에요.","휴대 전화는 오늘날이에요.","길 도우미도 오늘날이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_basic#6','soc',3,2,'u2','L20','g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',2,'mc','auto','통신수단을 안전하고 올바르게 이용하는 모습은 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"mc","stem":"통신수단을 안전하고 올바르게 이용하는 모습은 무엇인가요?","options":[{"t":"공공장소에서 작은 소리로 짧게 통화해요","correct":true},{"t":"길에서 동영상을 보면서 걸어요","mis":"SO3-2-u2-X43"},{"t":"다른 사람의 모습을 허락 없이 찍어요","mis":"SO3-2-u2-X43"},{"t":"다른 사람에게 상처 주는 댓글을 써요","mis":"SO3-2-u2-X43"}],"explanation":["피해를 주지 않아요.","공공장소예요.","작게, 짧게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_basic#7','soc',3,2,'u2','L20','g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',2,'blank','auto','옛날 통신수단은 (    ) 정보를 전달하기 어렵고, 소식을 전하는 데 시간이 오래 걸렸어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"blank","stem":"옛날 통신수단은 (    ) 정보를 전달하기 어렵고, 소식을 전하는 데 시간이 오래 걸렸어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"자세한","correct":true},{"t":"짧은","mis":"SO3-2-u2-X38"},{"t":"쉬운","mis":"SO3-2-u2-X38"},{"t":"그림","mis":"SO3-2-u2-X38"}],"explanation":["개수만 보였어요.","내용이 적어요.","자세한 정보예요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고 시간이 오래 걸렸어요.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용해요.","단서 3 — 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있어요.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났어요.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 해요."],"title":"휴대 전화 잠금 단서 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_basic#8','soc',3,2,'u2','L20','g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',2,'mc','auto','이모티콘을 만들 때 가장 먼저 할 일은 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"mc","stem":"이모티콘을 만들 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"대화 속 상황에 들어갈 알맞은 말을 생각해요","correct":true},{"t":"어울리는 색을 칠해요","mis":"SO3-2-u2-X43"},{"t":"스케치를 해요","mis":"SO3-2-u2-X43"},{"t":"친구의 이모티콘을 그대로 따라 그려요","mis":"SO3-2-u2-X43"}],"explanation":["무슨 말을 할지 정해요.","그다음이 모습이에요.","말을 먼저 생각해요."],"asset":{"type":"passage","lines":["① 대화 속 상황에 들어갈 알맞은 말을 생각해요.","② 그 말을 사람·동물·물건·글자 등 어떤 모습으로 나타낼지 정해요.","③ 스케치한 뒤 어울리는 색을 칠해 완성해요."],"title":"나만의 이모티콘 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_basic#9','soc',3,2,'u2','L20','g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',2,'ox','auto','통신수단은 옛날부터 오늘날까지 하나도 달라지지 않았어요.',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"ox","stem":"통신수단은 옛날부터 오늘날까지 하나도 달라지지 않았어요.","answer":"X","reason_options":[{"t":"서찰·봉수에서 휴대 전화·인터넷으로 정보를 주고받는 방법이 달라졌기 때문에","correct":true},{"t":"통신수단은 한번 만들어지면 바뀌지 않기 때문에","mis":"SO3-2-u2-X44"}],"mis":"SO3-2-u2-X44","explanation":["옛날과 오늘날을 견줘요.","방법이 바뀌었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_basic#10','soc',3,2,'u2','L20','g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',3,'mc','auto','옳은 단서의 번호 1, 3, 4, 5 가운데 「제일 작은 숫자를 두 번째 칸에」 쓰면 두 번째 칸의 숫자는 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"mc","stem":"옳은 단서의 번호 1, 3, 4, 5 가운데 「제일 작은 숫자를 두 번째 칸에」 쓰면 두 번째 칸의 숫자는 무엇인가요?","options":[{"t":"1","correct":true},{"t":"3","mis":"SO3-2-u2-X38"},{"t":"4","mis":"SO3-2-u2-X38"},{"t":"5","mis":"SO3-2-u2-X38"}],"explanation":["네 숫자예요.","가장 작은 수예요.","1이에요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고 시간이 오래 걸렸어요.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용해요.","단서 3 — 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있어요.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났어요.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 해요."],"title":"휴대 전화 잠금 단서 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_challenge#1','soc',3,2,'u2','L20','g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',2,'sa','auto','단서 2가 옳지 않은 까닭을 생각하며, 서찰·방·파발은 언제 쓰던 통신수단인지 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"sa","stem":"단서 2가 옳지 않은 까닭을 생각하며, 서찰·방·파발은 언제 쓰던 통신수단인지 두 글자로 쓰세요.","answer":["옛날"],"explanation":["오늘날이 아니에요.","옛◯이에요.","옛날이에요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고 시간이 오래 걸렸어요.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용해요.","단서 3 — 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있어요.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났어요.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 해요."],"title":"휴대 전화 잠금 단서 다섯"},"mis":"SO3-2-u2-X38"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_challenge#2','soc',3,2,'u2','L20','g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',2,'ox','auto','오늘날에는 휴대 전화처럼 하나의 통신수단으로 전화, 문자 메시지, 인터넷 등 다양한 통신 방법을 이용할 수 있어요.',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"ox","stem":"오늘날에는 휴대 전화처럼 하나의 통신수단으로 전화, 문자 메시지, 인터넷 등 다양한 통신 방법을 이용할 수 있어요.","answer":"O","reason_options":[{"t":"오늘날 휴대 전화에는 여러 기능이 함께 들어 있기 때문에","correct":true},{"t":"하나의 통신수단으로는 한 가지 일만 할 수 있기 때문에","mis":"SO3-2-u2-X38"}],"mis":"SO3-2-u2-X38","explanation":["휴대 전화를 봐요.","여러 기능이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_challenge#3','soc',3,2,'u2','L20','g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',3,'mc','auto','단서 2를 옳은 설명으로 고친 것은 무엇인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X44','SO3-2-u2-X35']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"mc","stem":"단서 2를 옳은 설명으로 고친 것은 무엇인가요?","options":[{"t":"오늘날 사람들은 주로 휴대 전화, 인터넷 등의 통신수단을 사용해요","correct":true},{"t":"오늘날 사람들은 주로 봉수와 북을 사용해요","mis":"SO3-2-u2-X38"},{"t":"옛날 사람들은 주로 휴대 전화를 사용했어요","mis":"SO3-2-u2-X44"},{"t":"오늘날 사람들은 통신수단을 사용하지 않아요","mis":"SO3-2-u2-X35"}],"explanation":["오늘날 것으로 바꿔요.","휴대 전화예요.","그렇게 고쳐요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고 시간이 오래 걸렸어요.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용해요.","단서 3 — 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있어요.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났어요.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 해요."],"title":"휴대 전화 잠금 단서 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_challenge#4','soc',3,2,'u2','L20','g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',3,'mc','auto','미래의 통신수단을 상상해 그림일기를 쓸 때 맨 먼저 할 일은 무엇인가요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X43']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"mc","stem":"미래의 통신수단을 상상해 그림일기를 쓸 때 맨 먼저 할 일은 무엇인가요?","options":[{"t":"통신수단을 이용하면서 불편했거나 아쉬웠던 경험을 떠올려요","correct":true},{"t":"통신수단의 이름을 외워요","mis":"SO3-2-u2-X44"},{"t":"옛날 통신수단만 떠올려요","mis":"SO3-2-u2-X44"},{"t":"친구의 일기를 그대로 따라 써요","mis":"SO3-2-u2-X43"}],"explanation":["불편한 점이 출발점이에요.","해결할 것을 생각해요.","경험을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_challenge#5','soc',3,2,'u2','L20','g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',3,'error','auto','통신 주제를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X41','SO3-2-u2-X42']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"error","stem":"통신 주제를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「오늘날에는 옛날보다 소식을 전하는 데 시간이 더 오래 걸려.」","correct":true,"mis_target":"SO3-2-u2-X38"},{"t":"친구 나 — 「새로운 시설과 직업이 생겨났어.」","mis":"SO3-2-u2-X41"},{"t":"친구 다 — 「건강을 위해 올바르게 써야 해.」","mis":"SO3-2-u2-X42"}],"explanation":["시간을 견줘요.","오늘날이 빨라요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_challenge#6','soc',3,2,'u2','L20','g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',3,'mc','auto','단서 4와 관계있는 예로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"mc","stem":"단서 4와 관계있는 예로 알맞은 것은 무엇인가요?","options":[{"t":"기지국이 세워지고 통신 설비 기술자라는 직업이 생겼어요","correct":true},{"t":"봉수를 올리는 사람이 늘었어요","mis":"SO3-2-u2-X41"},{"t":"교환원이 새로 생겼어요","mis":"SO3-2-u2-X41"},{"t":"파발을 전하는 말이 늘었어요","mis":"SO3-2-u2-X41"}],"explanation":["새 시설과 직업이에요.","기지국이에요.","통신 설비 기술자예요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고 시간이 오래 걸렸어요.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용해요.","단서 3 — 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있어요.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났어요.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 해요."],"title":"휴대 전화 잠금 단서 다섯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_challenge#7','soc',3,2,'u2','L20','g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',3,'ox','auto','통신수단이 발달해도 사람들의 생활 모습은 그대로예요.',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"ox","stem":"통신수단이 발달해도 사람들의 생활 모습은 그대로예요.","answer":"X","reason_options":[{"t":"정보를 찾고 의사소통하는 방식이 바뀌고 직접 가지 않아도 되는 일이 늘었기 때문에","correct":true},{"t":"통신수단과 생활은 아무 관계가 없기 때문에","mis":"SO3-2-u2-X44"}],"mis":"SO3-2-u2-X44","explanation":["생활이 바뀌었어요.","직접 가지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_challenge#8','soc',3,2,'u2','L20','g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',4,'mc','auto','주제 「통신수단의 변화로 달라진 생활 모습」을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X44','SO3-2-u2-X42']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C20","difficulty":4,"kind":"mc","stem":"주제 「통신수단의 변화로 달라진 생활 모습」을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"옛날보다 많은 정보를 실시간으로 주고받게 되고 새 시설과 직업이 생겼으며, 건강을 위해 올바르게 써야 해요","correct":true},{"t":"오늘날 사람들은 주로 서찰, 방, 파발로 소식을 전해요","mis":"SO3-2-u2-X38"},{"t":"통신수단은 옛날부터 하나도 달라지지 않았어요","mis":"SO3-2-u2-X44"},{"t":"통신수단은 편리하니 아무렇게나 써도 돼요","mis":"SO3-2-u2-X42"}],"explanation":["실시간이에요.","시설과 직업이에요.","올바르게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_challenge#9','soc',3,2,'u2','L20','g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',4,'mc','auto','교과서 그림일기 예시처럼 「멀리 있는 반려동물과 영상 통화를 하면 짖는 소리가 우리말로 화면에 나오는」 통신수단이 생긴다면 좋은 점은 무엇일까요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X38']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C20","difficulty":4,"kind":"mc","stem":"교과서 그림일기 예시처럼 「멀리 있는 반려동물과 영상 통화를 하면 짖는 소리가 우리말로 화면에 나오는」 통신수단이 생긴다면 좋은 점은 무엇일까요?","options":[{"t":"말이 통하지 않던 상대와도 마음을 나눌 수 있어요","correct":true},{"t":"반려동물과 더 멀어질 거예요","mis":"SO3-2-u2-X44"},{"t":"소식을 전하는 데 시간이 더 걸려요","mis":"SO3-2-u2-X38"},{"t":"날씨 때문에 화면이 안 보여요","mis":"SO3-2-u2-X38"}],"explanation":["짖는 소리가 말이 돼요.","마음이 통해요.","마음을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_L20_challenge#10','soc',3,2,'u2','L20','g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',4,'essay','teacher','옛날 통신수단 하나와 오늘날 통신수단 하나를 골라 견주어 쓰고, 통신수단을 올바르게 쓰기 위한 나의 약속을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C20","difficulty":4,"kind":"essay","stem":"옛날 통신수단 하나와 오늘날 통신수단 하나를 골라 견주어 쓰고, 통신수단을 올바르게 쓰기 위한 나의 약속을 쓰세요.","answer_guide":{"answer":"예: 옛날에는 봉수로 위급한 소식을 알렸지만 연기나 불의 개수로만 전해 자세히 알 수 없었어요. 오늘날에는 휴대 전화로 많은 정보를 실시간으로 주고받아요. 나는 정한 시간에만 스마트폰을 쓰겠어요.","scoring_points":["옛날 통신수단을 바르게 썼는가","오늘날 통신수단과 견주었는가","올바른 이용 약속을 썼는가"]},"explanation":["옛날 것을 골라요.","오늘날 것과 견줘요.","약속을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#1','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C1',1,'mc','auto','해마다 일정한 때에 되풀이하는 풍습을 가리키는 말은 무엇인가요?',ARRAY['SO3-2-u2-X35','SO3-2-u2-X20']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"mc","stem":"해마다 일정한 때에 되풀이하는 풍습을 가리키는 말은 무엇인가요?","options":[{"t":"세시 풍속","correct":true},{"t":"교통수단","mis":"SO3-2-u2-X35"},{"t":"통신수단","mis":"SO3-2-u2-X35"},{"t":"교통로","mis":"SO3-2-u2-X20"}],"explanation":["해마다 돌아와요.","명절과 절기예요.","세시 풍속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#2','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C2',1,'mc','auto','옛날 사람들이 일손이 모자란 일을 서로 돌아가면서 도운 풍습은 무엇인가요?',ARRAY['SO3-2-u2-X04','SO3-2-u2-X05','SO3-2-u2-X07']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"mc","stem":"옛날 사람들이 일손이 모자란 일을 서로 돌아가면서 도운 풍습은 무엇인가요?","options":[{"t":"품앗이","correct":true},{"t":"두레","mis":"SO3-2-u2-X04"},{"t":"관례","mis":"SO3-2-u2-X05"},{"t":"폐백","mis":"SO3-2-u2-X07"}],"explanation":["돌아가며 도와요.","김장, 지붕 얹기예요.","품앗이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
