INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#4','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C6',1,'mc','auto','고누판에서 말을 옮기며 상대방의 말을 따거나 길을 막아 가두는 놀이는 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C6","difficulty":1,"kind":"mc","stem":"고누판에서 말을 옮기며 상대방의 말을 따거나 길을 막아 가두는 놀이는 무엇인가요?","options":[{"t":"고누","correct":true},{"t":"투호","mis":"SO3-2-u2-X18"},{"t":"제기차기","mis":"SO3-2-u2-X18"},{"t":"윷놀이","mis":"SO3-2-u2-X18"}],"explanation":["판이 있어요.","말을 가둬요.","고누예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
