INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#7','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C15',1,'mc','auto','전화, 텔레비전, 전자 우편을 함께 이르는 말로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X35']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C15","difficulty":1,"kind":"mc","stem":"전화, 텔레비전, 전자 우편을 함께 이르는 말로 알맞은 것은 무엇인가요?","options":[{"t":"통신수단","correct":true},{"t":"교통수단","mis":"SO3-2-u2-X35"},{"t":"교통 시설","mis":"SO3-2-u2-X35"},{"t":"세시 풍속","mis":"SO3-2-u2-X35"}],"explanation":["소식을 주고받아요.","도구예요.","통신수단이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#8','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C17',1,'mc','auto','미세 먼지 상황을 확인할 수 있게 해 주는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X39','SO3-2-u2-X38']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C17","difficulty":1,"kind":"mc","stem":"미세 먼지 상황을 확인할 수 있게 해 주는 통신수단은 무엇인가요?","options":[{"t":"대기 정보 알리미","correct":true},{"t":"등하교 알리미","mis":"SO3-2-u2-X39"},{"t":"무전기","mis":"SO3-2-u2-X39"},{"t":"봉수","mis":"SO3-2-u2-X38"}],"explanation":["공기예요.","알려 줘요.","대기 정보 알리미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#9','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C5',2,'mc','auto','신문 ①에서 옛날부터 이어져 오는 설날 모습은 무엇인가요?',ARRAY['SO3-2-u2-X15']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"mc","stem":"신문 ①에서 옛날부터 이어져 오는 설날 모습은 무엇인가요?","options":[{"t":"차례를 지내고 세배하기","correct":true},{"t":"가족 여행 가기","mis":"SO3-2-u2-X15"},{"t":"영화 보기","mis":"SO3-2-u2-X15"},{"t":"모두 달라진 모습이에요","mis":"SO3-2-u2-X15"}],"explanation":["옛날에도 했어요.","차례와 세배예요.","이어져 와요."],"asset":{"type":"passage","lines":["새싹반 친구들이 지난 설날에 한 일을 조사했다.","많은 집이 차례를 지내고, 세배를 하고, 떡국을 먹었다.","연휴에 가족 여행을 가거나 영화를 본 집도 있었다."],"title":"신문 ① — 새싹반의 설날 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#10','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C2',2,'mc','auto','신문 ②의 전시물 가운데 아기가 태어났을 때와 관련 있는 것은 무엇인가요?',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"mc","stem":"신문 ②의 전시물 가운데 아기가 태어났을 때와 관련 있는 것은 무엇인가요?","options":[{"t":"금줄","correct":true},{"t":"나무 기러기","mis":"SO3-2-u2-X05"},{"t":"회갑 상","mis":"SO3-2-u2-X05"},{"t":"돌잡이 상","mis":"SO3-2-u2-X05"}],"explanation":["대문에 쳤어요.","태어났을 때예요.","금줄이에요."],"asset":{"type":"passage","lines":["새싹반은 옛날 일생 풍습 전시를 보았다.","금줄, 돌잡이 상, 나무 기러기, 회갑 상이 차례대로 놓여 있었다.","안내판에는 「기쁨은 축하하고 슬픔은 위로하며 마음을 나눴어요」라고 적혀 있었다."],"title":"신문 ② — 옛날 일생 풍습 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#11','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C4',2,'mc','auto','신문 ③에서 친구들이 부럼을 깨문 까닭으로 옛날 사람들이 빈 것은 무엇인가요?',ARRAY['SO3-2-u2-X12']::text[],false,'{"seq":11,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"mc","stem":"신문 ③에서 친구들이 부럼을 깨문 까닭으로 옛날 사람들이 빈 것은 무엇인가요?","options":[{"t":"이가 튼튼해지고 피부병이 생기지 않기를","correct":true},{"t":"여름을 시원하게 보내기를","mis":"SO3-2-u2-X12"},{"t":"조상의 산소를 돌보기를","mis":"SO3-2-u2-X12"},{"t":"새해 달력을 받기를","mis":"SO3-2-u2-X12"}],"explanation":["단단한 열매예요.","이와 피부예요.","튼튼해지기를 빌어요."],"asset":{"type":"passage","lines":["학교에서 정월 대보름 행사를 열었다.","친구들은 부럼을 깨물고 오곡밥과 나물을 먹었다.","운동장에서는 모둠별로 윷놀이와 제기차기를 했다."],"title":"신문 ③ — 우리 학교 정월 대보름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#12','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C9',2,'mc','auto','신문 ④에서 할아버지가 어릴 때 짐을 실은 달구지는 무엇의 힘으로 움직였나요?',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":12,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"mc","stem":"신문 ④에서 할아버지가 어릴 때 짐을 실은 달구지는 무엇의 힘으로 움직였나요?","options":[{"t":"동물의 힘","correct":true},{"t":"석유의 힘","mis":"SO3-2-u2-X24"},{"t":"전기의 힘","mis":"SO3-2-u2-X24"},{"t":"수증기의 힘","mis":"SO3-2-u2-X24"}],"explanation":["소가 끌어요.","동물이에요.","동물의 힘이에요."],"asset":{"type":"passage","lines":["할아버지는 어릴 때 장에 가려면 한참을 걸어가셨다고 한다.","무거운 짐은 소가 끄는 달구지에 실었다고 한다.","지금은 버스를 타고 금방 가고, 짐은 트럭이 실어 나른다."],"title":"신문 ④ — 할아버지의 어린 시절 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#13','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C12',2,'mc','auto','신문 ⑤의 「차가 몰려 길이 막히는 일」을 무엇이라고 하나요?',ARRAY['SO3-2-u2-X30','SO3-2-u2-X20']::text[],false,'{"seq":13,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"mc","stem":"신문 ⑤의 「차가 몰려 길이 막히는 일」을 무엇이라고 하나요?","options":[{"t":"교통 체증","correct":true},{"t":"교통 시설","mis":"SO3-2-u2-X30"},{"t":"교통 약자","mis":"SO3-2-u2-X30"},{"t":"교통로","mis":"SO3-2-u2-X20"}],"explanation":["차가 많아요.","막혀요.","교통 체증이에요."],"asset":{"type":"passage","lines":["학교 앞 도로는 아침마다 차가 몰려 길이 막힌다.","스마트폰을 보며 횡단보도를 건너다 깜짝 놀란 친구도 있었다.","새싹반은 교통안전 약속을 함께 정했다."],"title":"신문 ⑤ — 학교 앞 아침 풍경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#14','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C13',2,'mc','auto','신문 ⑥의 「사람이 운전하지 않아도 스스로 달리는 자동차」는 무엇인가요?',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":14,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"mc","stem":"신문 ⑥의 「사람이 운전하지 않아도 스스로 달리는 자동차」는 무엇인가요?","options":[{"t":"자율 주행 자동차","correct":true},{"t":"자율 운항 선박","mis":"SO3-2-u2-X33"},{"t":"초고속 자기 부상 열차","mis":"SO3-2-u2-X33"},{"t":"착용하는 로봇","mis":"SO3-2-u2-X33"}],"explanation":["스스로 달려요.","자동차예요.","자율 주행 자동차예요."],"asset":{"type":"passage","lines":["새싹반 친구들이 미래 교통수단을 그렸다.","사람이 운전하지 않아도 스스로 달리는 자동차, 하늘로 다니는 택시가 많았다.","친구들은 빠르면서도 안전하고 환경을 지키는 모습을 그렸다."],"title":"신문 ⑥ — 우리가 그린 미래 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#15','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C16',2,'mc','auto','신문 ⑦의 봉수대 모형에서 연기 구멍 다섯 개를 모두 피웠다면 어떤 상황인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":15,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"mc","stem":"신문 ⑦의 봉수대 모형에서 연기 구멍 다섯 개를 모두 피웠다면 어떤 상황인가요?","options":[{"t":"적과 싸움이 시작됐어요","correct":true},{"t":"적이 없는 평상시예요","mis":"SO3-2-u2-X37"},{"t":"적이 나타났어요","mis":"SO3-2-u2-X37"},{"t":"적이 가까이 왔어요","mis":"SO3-2-u2-X37"}],"explanation":["가장 많아요.","가장 위급해요.","싸움이 시작됐어요."],"asset":{"type":"passage","lines":["새싹반은 옛날 통신수단 전시를 보았다.","봉수대 모형에는 연기 구멍이 다섯 개 있었다.","안내판에는 「안개 낀 날에는 봉수 대신 파발을 보냈어요」라고 적혀 있었다."],"title":"신문 ⑦ — 옛날 통신수단 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#16','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C17',2,'mc','auto','신문 ⑧에서 알림장을 받는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X39','SO3-2-u2-X38']::text[],false,'{"seq":16,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"mc","stem":"신문 ⑧에서 알림장을 받는 통신수단은 무엇인가요?","options":[{"t":"모바일 메신저","correct":true},{"t":"디지털 안내판","mis":"SO3-2-u2-X39"},{"t":"무전기","mis":"SO3-2-u2-X39"},{"t":"방","mis":"SO3-2-u2-X38"}],"explanation":["스마트폰으로 받아요.","바로 와요.","모바일 메신저예요."],"asset":{"type":"passage","lines":["새싹반은 모바일 메신저로 알림장을 받는다.","수업 시간에는 태블릿 컴퓨터로 궁금한 것을 찾는다.","밤늦게까지 스마트폰을 본 친구가 아침에 무척 피곤해했다."],"title":"신문 ⑧ — 새싹반의 통신 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#17','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C3',3,'mc','auto','옛날과 오늘날의 결혼 풍습에서 달라진 것이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X08']::text[],false,'{"seq":17,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"mc","stem":"옛날과 오늘날의 결혼 풍습에서 달라진 것이 아닌 것은 무엇인가요?","options":[{"t":"부부가 된 것을 알리고 미래를 축복하는 마음","correct":true},{"t":"결혼하는 장소","mis":"SO3-2-u2-X08"},{"t":"입는 옷","mis":"SO3-2-u2-X08"},{"t":"주고받는 물건","mis":"SO3-2-u2-X08"}],"explanation":["달라지지 않은 것이에요.","마음은 같아요.","축복하는 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#18','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C4',3,'mc','auto','설빔, 세배, 덕담, 떡국, 널뛰기를 모두 볼 수 있는 명절은 언제인가요?',ARRAY['SO3-2-u2-X10']::text[],false,'{"seq":18,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"mc","stem":"설빔, 세배, 덕담, 떡국, 널뛰기를 모두 볼 수 있는 명절은 언제인가요?","options":[{"t":"음력 1월 1일","correct":true},{"t":"음력 5월 5일","mis":"SO3-2-u2-X10"},{"t":"음력 8월 15일","mis":"SO3-2-u2-X10"},{"t":"음력 1월 15일","mis":"SO3-2-u2-X10"}],"explanation":["설날이에요.","한 해의 시작이에요.","음력 1월 1일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#19','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C9',3,'mc','auto','옛날 교통수단과 오늘날 교통수단을 견준 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":19,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"mc","stem":"옛날 교통수단과 오늘날 교통수단을 견준 것으로 알맞은 것은 무엇인가요?","options":[{"t":"옛날 것은 자연의 힘으로, 오늘날 것은 대부분 기계의 힘으로 움직여요","correct":true},{"t":"옛날 것은 석유로, 오늘날 것은 바람으로 움직여요","mis":"SO3-2-u2-X24"},{"t":"둘 다 동물의 힘으로 움직여요","mis":"SO3-2-u2-X24"},{"t":"둘 다 기계의 힘으로 움직여요","mis":"SO3-2-u2-X24"}],"explanation":["자연의 힘이에요.","기계의 힘이에요.","견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#20','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C12',3,'mc','auto','친환경 에너지를 사용하는 교통수단을 늘리는 노력으로 풀 수 있는 문제는 무엇인가요?',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":20,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"mc","stem":"친환경 에너지를 사용하는 교통수단을 늘리는 노력으로 풀 수 있는 문제는 무엇인가요?","options":[{"t":"대기 오염","correct":true},{"t":"주차할 곳 부족","mis":"SO3-2-u2-X30"},{"t":"횡단보도 부족","mis":"SO3-2-u2-X30"},{"t":"교통 약자 택시 부족","mis":"SO3-2-u2-X30"}],"explanation":["공기예요.","친환경이에요.","대기 오염이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#21','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C16',3,'mc','auto','옛날 통신수단과 오늘날 통신수단을 견준 것으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":21,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"mc","stem":"옛날 통신수단과 오늘날 통신수단을 견준 것으로 알맞은 것은 무엇인가요?","options":[{"t":"옛날에는 오래 걸리고 날씨의 영향을 받았지만 오늘날에는 실시간으로 빠르게 주고받아요","correct":true},{"t":"옛날에도 실시간으로 주고받았어요","mis":"SO3-2-u2-X38"},{"t":"오늘날에는 날씨 때문에 소식이 늦어요","mis":"SO3-2-u2-X38"},{"t":"둘 다 많은 내용을 자세히 전하기 어려워요","mis":"SO3-2-u2-X38"}],"explanation":["옛날은 느렸어요.","오늘날은 빨라요.","견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#22','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C20',3,'mc','auto','「2단원 옛날과 오늘날의 생활 모습」을 정리하며 알게 된 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X02']::text[],false,'{"seq":22,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"mc","stem":"「2단원 옛날과 오늘날의 생활 모습」을 정리하며 알게 된 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"풍습, 교통수단, 통신수단이 변화하면서 사람들의 생활 모습도 달라졌어요","correct":true},{"t":"옛날과 오늘날의 생활 모습은 하나도 달라지지 않았어요","mis":"SO3-2-u2-X44"},{"t":"교통수단과 통신수단은 옛날부터 그대로예요","mis":"SO3-2-u2-X44"},{"t":"오늘날에는 옛날부터 이어진 풍습이 하나도 없어요","mis":"SO3-2-u2-X02"}],"explanation":["세 가지가 변했어요.","생활도 달라졌어요.","함께 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#23','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C5',4,'essay','teacher','신문 ①을 보고 옛날부터 이어져 오는 설날 모습과 달라진 설날 모습을 하나씩 찾아 쓰고, 세시 풍속이 달라져도 변함없는 것을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-2-u2-C5","difficulty":4,"kind":"essay","stem":"신문 ①을 보고 옛날부터 이어져 오는 설날 모습과 달라진 설날 모습을 하나씩 찾아 쓰고, 세시 풍속이 달라져도 변함없는 것을 쓰세요.","answer_guide":{"answer":"예: 차례를 지내고 세배를 하는 것은 옛날부터 이어져 오는 모습이에요. 연휴에 가족 여행을 가는 것은 달라진 모습이에요. 그래도 가족이 함께 모여 기쁨을 나누는 것은 변함없어요.","scoring_points":["이어져 오는 모습을 찾았는가","달라진 모습을 찾았는가","변함없는 것을 썼는가"]},"explanation":["노란 형광펜이에요.","하늘색 형광펜이에요.","변함없는 것을 써요."],"asset":{"type":"passage","lines":["새싹반 친구들이 지난 설날에 한 일을 조사했다.","많은 집이 차례를 지내고, 세배를 하고, 떡국을 먹었다.","연휴에 가족 여행을 가거나 영화를 본 집도 있었다."],"title":"신문 ① — 새싹반의 설날 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#24','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C11',4,'essay','teacher','신문 ④를 보고 할아버지가 어릴 때와 지금의 교통수단을 견주어 쓰고, 교통이 발달하면서 달라진 생활 모습을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u2-C11","difficulty":4,"kind":"essay","stem":"신문 ④를 보고 할아버지가 어릴 때와 지금의 교통수단을 견주어 쓰고, 교통이 발달하면서 달라진 생활 모습을 쓰세요.","answer_guide":{"answer":"예: 할아버지가 어릴 때는 걸어가고 달구지로 짐을 옮겼지만 지금은 버스를 타고 트럭으로 짐을 옮겨요. 교통이 발달하면서 더 빨리, 더 멀리 이동하고 더 많은 짐을 옮길 수 있게 됐어요.","scoring_points":["옛날 교통수단을 썼는가","오늘날 교통수단과 견주었는가","달라진 생활 모습을 썼는가"]},"explanation":["옛날을 찾아요.","지금과 견줘요.","생활을 써요."],"asset":{"type":"passage","lines":["할아버지는 어릴 때 장에 가려면 한참을 걸어가셨다고 한다.","무거운 짐은 소가 끄는 달구지에 실었다고 한다.","지금은 버스를 타고 금방 가고, 짐은 트럭이 실어 나른다."],"title":"신문 ④ — 할아버지의 어린 시절 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_a#25','soc',3,2,'u2','','g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C16',4,'essay','teacher','신문 ⑦을 보고 옛날 통신수단의 특징을 두 가지 쓰고, 오늘날 통신수단과 견주어 달라진 점을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u2-C16","difficulty":4,"kind":"essay","stem":"신문 ⑦을 보고 옛날 통신수단의 특징을 두 가지 쓰고, 오늘날 통신수단과 견주어 달라진 점을 쓰세요.","answer_guide":{"answer":"예: 옛날 봉수는 연기나 불의 개수로만 알려 자세한 내용을 전하기 어려웠고, 안개 낀 날에는 보이지 않아 날씨의 영향을 받았어요. 오늘날에는 휴대 전화로 날씨와 관계없이 많은 정보를 실시간으로 주고받아요.","scoring_points":["옛날 특징을 두 가지 썼는가","오늘날 통신수단과 견주었는가","달라진 점을 바르게 썼는가"]},"explanation":["봉수를 봐요.","날씨도 봐요.","오늘날과 견줘요."],"asset":{"type":"passage","lines":["새싹반은 옛날 통신수단 전시를 보았다.","봉수대 모형에는 연기 구멍이 다섯 개 있었다.","안내판에는 「안개 낀 날에는 봉수 대신 파발을 보냈어요」라고 적혀 있었다."],"title":"신문 ⑦ — 옛날 통신수단 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#1','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C1',1,'sa','auto','옛날부터 되풀이되어 전해 오는 생활 습관과 생활 모습을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"sa","stem":"옛날부터 되풀이되어 전해 오는 생활 습관과 생활 모습을 두 글자로 쓰세요.","answer":["풍습"],"explanation":["전해 와요.","풍◯이에요.","풍습이에요."],"mis":"SO3-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#2','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C3',1,'sa','auto','신부가 처음으로 신랑 부모나 신랑 쪽 어른들께 큰절을 올리는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C3","difficulty":1,"kind":"sa","stem":"신부가 처음으로 신랑 부모나 신랑 쪽 어른들께 큰절을 올리는 것을 두 글자로 쓰세요.","answer":["폐백"],"explanation":["큰절이에요.","폐◯이에요.","폐백이에요."],"mis":"SO3-2-u2-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#3','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C4',1,'sa','auto','단오에 남자들이 즐긴 놀이를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"sa","stem":"단오에 남자들이 즐긴 놀이를 두 글자로 쓰세요.","answer":["씨름"],"explanation":["힘을 겨뤄요.","씨◯이에요.","씨름이에요."],"mis":"SO3-2-u2-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#4','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C6',1,'sa','auto','윷놀이에서 편마다 나누어 가지는 윷말은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO3-2-u2-C6","difficulty":1,"kind":"sa","stem":"윷놀이에서 편마다 나누어 가지는 윷말은 몇 개인가요? 숫자로 쓰세요.","answer":["4","4개"],"explanation":["출발점으로 들어와야 해요.","네 개예요.","4개예요."],"mis":"SO3-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#5','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C9',1,'sa','auto','먼 거리를 이동하거나 빨리 갈 때 옛날 사람들이 타고 다닌 동물을 한 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"sa","stem":"먼 거리를 이동하거나 빨리 갈 때 옛날 사람들이 타고 다닌 동물을 한 글자로 쓰세요.","answer":["말"],"explanation":["동물이에요.","빨리 달려요.","말이에요."],"mis":"SO3-2-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#6','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C11',1,'sa','auto','가마의 앞뒤에서 가마를 들고 가는 일을 하다 거의 사라진 직업을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C11","difficulty":1,"kind":"sa","stem":"가마의 앞뒤에서 가마를 들고 가는 일을 하다 거의 사라진 직업을 세 글자로 쓰세요.","answer":["가마꾼"],"explanation":["가마를 들어요.","가마◯이에요.","가마꾼이에요."],"mis":"SO3-2-u2-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#7','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C16',1,'sa','auto','낮에는 연기, 밤에는 불을 피워 위급함을 알린 옛날 통신수단을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"sa","stem":"낮에는 연기, 밤에는 불을 피워 위급함을 알린 옛날 통신수단을 두 글자로 쓰세요.","answer":["봉수"],"explanation":["높은 곳이에요.","봉◯예요.","봉수예요."],"mis":"SO3-2-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#8','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C18',1,'sa','auto','초기의 전화기에서 전화를 거는 사람과 받는 사람을 연결해 준 사람을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-2-u2-C18","difficulty":1,"kind":"sa","stem":"초기의 전화기에서 전화를 거는 사람과 받는 사람을 연결해 준 사람을 세 글자로 쓰세요.","answer":["교환원"],"explanation":["중간에서 이어 줘요.","교환◯이에요.","교환원이에요."],"mis":"SO3-2-u2-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#9','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C5',2,'mc','auto','신문 ①에서 옛날과 달라진 설날 모습은 무엇인가요?',ARRAY['SO3-2-u2-X15']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"mc","stem":"신문 ①에서 옛날과 달라진 설날 모습은 무엇인가요?","options":[{"t":"연휴에 가족 여행을 가는 것","correct":true},{"t":"떡국을 먹는 것","mis":"SO3-2-u2-X15"},{"t":"세배하는 것","mis":"SO3-2-u2-X15"},{"t":"차례를 지내는 것","mis":"SO3-2-u2-X15"}],"explanation":["옛날에 없던 모습이에요.","여행이에요.","달라진 모습이에요."],"asset":{"type":"passage","lines":["새싹반 친구들이 지난 설날에 한 일을 조사했다.","많은 집이 차례를 지내고, 세배를 하고, 떡국을 먹었다.","연휴에 가족 여행을 가거나 영화를 본 집도 있었다."],"title":"신문 ① — 새싹반의 설날 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#10','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C3',2,'mc','auto','신문 ②의 나무 기러기는 오늘날 결혼식에서 무엇과 비슷한 뜻을 가지나요?',ARRAY['SO3-2-u2-X07']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"mc","stem":"신문 ②의 나무 기러기는 오늘날 결혼식에서 무엇과 비슷한 뜻을 가지나요?","options":[{"t":"평생 함께할 것을 약속하며 주고받는 반지","correct":true},{"t":"신혼여행","mis":"SO3-2-u2-X07"},{"t":"웨딩드레스","mis":"SO3-2-u2-X07"},{"t":"결혼식장","mis":"SO3-2-u2-X07"}],"explanation":["평생 함께해요.","주고받는 물건이에요.","반지예요."],"asset":{"type":"passage","lines":["새싹반은 옛날 일생 풍습 전시를 보았다.","금줄, 돌잡이 상, 나무 기러기, 회갑 상이 차례대로 놓여 있었다.","안내판에는 「기쁨은 축하하고 슬픔은 위로하며 마음을 나눴어요」라고 적혀 있었다."],"title":"신문 ② — 옛날 일생 풍습 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#11','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C6',2,'mc','auto','신문 ③의 윷놀이에서 「모」가 나왔을 때 할 일은 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":11,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"mc","stem":"신문 ③의 윷놀이에서 「모」가 나왔을 때 할 일은 무엇인가요?","options":[{"t":"한 번 더 던져요","correct":true},{"t":"차례를 넘겨요","mis":"SO3-2-u2-X18"},{"t":"윷말을 처음으로 되돌려요","mis":"SO3-2-u2-X18"},{"t":"놀이를 끝내요","mis":"SO3-2-u2-X18"}],"explanation":["좋은 결과예요.","윷 또는 모예요.","한 번 더 던져요."],"asset":{"type":"passage","lines":["학교에서 정월 대보름 행사를 열었다.","친구들은 부럼을 깨물고 오곡밥과 나물을 먹었다.","운동장에서는 모둠별로 윷놀이와 제기차기를 했다."],"title":"신문 ③ — 우리 학교 정월 대보름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#12','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C11',2,'mc','auto','신문 ④에서 달구지 대신 트럭이 짐을 실어 나르게 되며 달라진 점은 무엇인가요?',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":12,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"mc","stem":"신문 ④에서 달구지 대신 트럭이 짐을 실어 나르게 되며 달라진 점은 무엇인가요?","options":[{"t":"더 많은 짐을 먼 곳까지 빠르게 옮겨요","correct":true},{"t":"짐을 실을 수 없게 됐어요","mis":"SO3-2-u2-X28"},{"t":"더 가까운 곳까지만 가요","mis":"SO3-2-u2-X28"},{"t":"더 느려졌어요","mis":"SO3-2-u2-X28"}],"explanation":["트럭은 기계예요.","많이, 멀리예요.","빠르게 옮겨요."],"asset":{"type":"passage","lines":["할아버지는 어릴 때 장에 가려면 한참을 걸어가셨다고 한다.","무거운 짐은 소가 끄는 달구지에 실었다고 한다.","지금은 버스를 타고 금방 가고, 짐은 트럭이 실어 나른다."],"title":"신문 ④ — 할아버지의 어린 시절 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#13','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C12',2,'mc','auto','신문 ⑤에서 깜짝 놀란 친구에게 알려 줄 교통안전 수칙은 무엇인가요?',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":13,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"mc","stem":"신문 ⑤에서 깜짝 놀란 친구에게 알려 줄 교통안전 수칙은 무엇인가요?","options":[{"t":"스마트폰을 보면서 길을 건너지 않아요","correct":true},{"t":"더 빨리 뛰어서 건너요","mis":"SO3-2-u2-X31"},{"t":"무단 횡단을 해요","mis":"SO3-2-u2-X31"},{"t":"도로 옆에서 장난쳐요","mis":"SO3-2-u2-X31"}],"explanation":["스마트폰이에요.","주위를 살펴요.","보며 건너지 않아요."],"asset":{"type":"passage","lines":["학교 앞 도로는 아침마다 차가 몰려 길이 막힌다.","스마트폰을 보며 횡단보도를 건너다 깜짝 놀란 친구도 있었다.","새싹반은 교통안전 약속을 함께 정했다."],"title":"신문 ⑤ — 학교 앞 아침 풍경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#14','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C13',2,'mc','auto','신문 ⑥의 「하늘로 다니는 택시」 같은 도심 항공 교통의 좋은 점은 무엇인가요?',ARRAY['SO3-2-u2-X33','SO3-2-u2-X34']::text[],false,'{"seq":14,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"mc","stem":"신문 ⑥의 「하늘로 다니는 택시」 같은 도심 항공 교통의 좋은 점은 무엇인가요?","options":[{"t":"땅에서와 같은 교통 혼잡을 일으키지 않아요","correct":true},{"t":"도로를 더 많이 만들어야 해요","mis":"SO3-2-u2-X33"},{"t":"공해와 소음이 아주 많아요","mis":"SO3-2-u2-X34"},{"t":"아주 큰 공항이 꼭 필요해요","mis":"SO3-2-u2-X33"}],"explanation":["하늘이 길이에요.","땅이 막혀도 괜찮아요.","혼잡이 없어요."],"asset":{"type":"passage","lines":["새싹반 친구들이 미래 교통수단을 그렸다.","사람이 운전하지 않아도 스스로 달리는 자동차, 하늘로 다니는 택시가 많았다.","친구들은 빠르면서도 안전하고 환경을 지키는 모습을 그렸다."],"title":"신문 ⑥ — 우리가 그린 미래 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#15','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C16',2,'mc','auto','신문 ⑦에서 안개 낀 날 봉수 대신 파발을 보낸 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X37']::text[],false,'{"seq":15,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"mc","stem":"신문 ⑦에서 안개 낀 날 봉수 대신 파발을 보낸 까닭은 무엇인가요?","options":[{"t":"안개가 짙으면 봉수의 연기나 불이 잘 보이지 않기 때문이에요","correct":true},{"t":"파발이 봉수보다 빨랐기 때문이에요","mis":"SO3-2-u2-X38"},{"t":"봉수는 밤에만 쓸 수 있었기 때문이에요","mis":"SO3-2-u2-X37"},{"t":"파발로는 위급한 소식을 전하지 않았기 때문이에요","mis":"SO3-2-u2-X37"}],"explanation":["안개예요.","보이지 않아요.","날씨의 영향이에요."],"asset":{"type":"passage","lines":["새싹반은 옛날 통신수단 전시를 보았다.","봉수대 모형에는 연기 구멍이 다섯 개 있었다.","안내판에는 「안개 낀 날에는 봉수 대신 파발을 보냈어요」라고 적혀 있었다."],"title":"신문 ⑦ — 옛날 통신수단 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#16','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C19',2,'mc','auto','신문 ⑧의 피곤해한 친구에게 알맞은 약속은 무엇인가요?',ARRAY['SO3-2-u2-X42','SO3-2-u2-X43']::text[],false,'{"seq":16,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"mc","stem":"신문 ⑧의 피곤해한 친구에게 알맞은 약속은 무엇인가요?","options":[{"t":"스마트폰은 정한 시간에만 사용하겠습니다","correct":true},{"t":"밤늦게까지 계속 확인하겠습니다","mis":"SO3-2-u2-X42"},{"t":"더 큰 소리로 통화하겠습니다","mis":"SO3-2-u2-X43"},{"t":"걸으면서 동영상을 보겠습니다","mis":"SO3-2-u2-X43"}],"explanation":["밤늦게까지 봤어요.","시간을 정해요.","정한 시간에만요."],"asset":{"type":"passage","lines":["새싹반은 모바일 메신저로 알림장을 받는다.","수업 시간에는 태블릿 컴퓨터로 궁금한 것을 찾는다.","밤늦게까지 스마트폰을 본 친구가 아침에 무척 피곤해했다."],"title":"신문 ⑧ — 새싹반의 통신 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#17','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C5',3,'mc','auto','옛날에 세시 풍속이 계절마다 다양했던 것과 가장 관계있는 생활은 무엇인가요?',ARRAY['SO3-2-u2-X13','SO3-2-u2-X14','SO3-2-u2-X15']::text[],false,'{"seq":17,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"mc","stem":"옛날에 세시 풍속이 계절마다 다양했던 것과 가장 관계있는 생활은 무엇인가요?","options":[{"t":"계절에 따라 할 일이 정해진 농사","correct":true},{"t":"공장에서 물건 만들기","mis":"SO3-2-u2-X13"},{"t":"해외여행","mis":"SO3-2-u2-X14"},{"t":"영화 보기","mis":"SO3-2-u2-X15"}],"explanation":["계절이 중요해요.","논밭의 일이에요.","농사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#18','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C4',3,'mc','auto','송편에 담긴 마음으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X12']::text[],false,'{"seq":18,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"mc","stem":"송편에 담긴 마음으로 알맞은 것은 무엇인가요?","options":[{"t":"반달이 보름달이 되듯 집안이나 나라가 점점 나아지기를 바라는 마음","correct":true},{"t":"나쁜 기운을 쫓는 마음","mis":"SO3-2-u2-X12"},{"t":"여름을 시원하게 보내려는 마음","mis":"SO3-2-u2-X12"},{"t":"이가 튼튼해지기를 바라는 마음","mis":"SO3-2-u2-X12"}],"explanation":["반달 모양이에요.","점점 커져요.","나아지기를 바라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#19','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C11',3,'mc','auto','돛단배 대신 여객선을 타게 되면서 달라진 생활 모습은 무엇인가요?',ARRAY['SO3-2-u2-X28','SO3-2-u2-X24']::text[],false,'{"seq":19,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"mc","stem":"돛단배 대신 여객선을 타게 되면서 달라진 생활 모습은 무엇인가요?","options":[{"t":"가기 어려웠던 섬에 쉽고 빠르게 갈 수 있어요","correct":true},{"t":"섬에 가는 일이 더 어려워졌어요","mis":"SO3-2-u2-X28"},{"t":"바다를 건널 수 없게 됐어요","mis":"SO3-2-u2-X28"},{"t":"바람이 없으면 더 빨라져요","mis":"SO3-2-u2-X24"}],"explanation":["여객선은 기계예요.","섬이에요.","쉽고 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#20','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C13',3,'mc','auto','초고속 자기 부상 열차에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":20,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"mc","stem":"초고속 자기 부상 열차에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"전기의 힘으로 떠서 터널을 통해 비행기보다 빠르게 달려요","correct":true},{"t":"바람의 힘으로 물 위를 떠다녀요","mis":"SO3-2-u2-X33"},{"t":"사람이 직접 끌어서 움직여요","mis":"SO3-2-u2-X33"},{"t":"스스로 바다를 건너는 배예요","mis":"SO3-2-u2-X33"}],"explanation":["자기 부상이에요.","전기의 힘이에요.","아주 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#21','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C18',3,'mc','auto','유선 전화에서 휴대 전화로 바뀌며 달라진 생활은 무엇인가요?',ARRAY['SO3-2-u2-X40']::text[],false,'{"seq":21,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"mc","stem":"유선 전화에서 휴대 전화로 바뀌며 달라진 생활은 무엇인가요?","options":[{"t":"이동하면서도 전화를 걸고 받을 수 있게 됐어요","correct":true},{"t":"교환원이 꼭 연결해야 하게 됐어요","mis":"SO3-2-u2-X40"},{"t":"전화기가 있는 곳으로 가야만 통화하게 됐어요","mis":"SO3-2-u2-X40"},{"t":"숫자 번호판이 사라졌어요","mis":"SO3-2-u2-X40"}],"explanation":["들고 다녀요.","어디서나요.","이동하며 통화해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#22','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C14',3,'mc','auto','교통의 변화로 새로 생긴 교통 시설끼리 모은 것은 무엇인가요?',ARRAY['SO3-2-u2-X35','SO3-2-u2-X24']::text[],false,'{"seq":22,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"mc","stem":"교통의 변화로 새로 생긴 교통 시설끼리 모은 것은 무엇인가요?","options":[{"t":"버스 터미널, 공항","correct":true},{"t":"봉수대, 파발","mis":"SO3-2-u2-X35"},{"t":"서찰, 방","mis":"SO3-2-u2-X35"},{"t":"가마, 뗏목","mis":"SO3-2-u2-X24"}],"explanation":["옛날에 없었어요.","오늘날 교통이에요.","터미널과 공항이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#23','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C3',4,'essay','teacher','신문 ②의 전시물 가운데 나무 기러기를 보고 옛날과 오늘날의 결혼 풍습을 두 가지 견주어 쓰고, 변함없는 마음을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-2-u2-C3","difficulty":4,"kind":"essay","stem":"신문 ②의 전시물 가운데 나무 기러기를 보고 옛날과 오늘날의 결혼 풍습을 두 가지 견주어 쓰고, 변함없는 마음을 쓰세요.","answer_guide":{"answer":"예: 옛날에는 신부 집에서 혼례복을 입고 결혼했지만 오늘날에는 결혼식장에서 턱시도와 웨딩드레스를 입어요. 옛날에는 나무 기러기를, 오늘날에는 반지를 주고받아요. 부부가 된 것을 알리고 미래를 축복하는 마음은 변함없어요.","scoring_points":["결혼 풍습을 두 가지 견주었는가","옛날과 오늘날을 바르게 짝지었는가","변함없는 마음을 썼는가"]},"explanation":["장소와 옷을 견줘요.","물건도 견줘요.","마음을 써요."],"asset":{"type":"passage","lines":["새싹반은 옛날 일생 풍습 전시를 보았다.","금줄, 돌잡이 상, 나무 기러기, 회갑 상이 차례대로 놓여 있었다.","안내판에는 「기쁨은 축하하고 슬픔은 위로하며 마음을 나눴어요」라고 적혀 있었다."],"title":"신문 ② — 옛날 일생 풍습 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#24','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C12',4,'essay','teacher','신문 ⑤에서 교통 문제를 두 가지 찾아 쓰고, 그 문제를 해결하려는 노력과 새싹반이 정할 교통안전 약속을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u2-C12","difficulty":4,"kind":"essay","stem":"신문 ⑤에서 교통 문제를 두 가지 찾아 쓰고, 그 문제를 해결하려는 노력과 새싹반이 정할 교통안전 약속을 쓰세요.","answer_guide":{"answer":"예: 아침마다 차가 몰려 길이 막히는 교통 체증과 스마트폰을 보며 건너다 사고가 날 뻔한 일이 있어요. 막히는 길 정보를 빠르게 알려 교통을 관리할 수 있어요. 새싹반은 「횡단보도에서는 스마트폰을 보지 않고 주위를 살피며 건너요」라고 약속할 수 있어요.","scoring_points":["문제를 두 가지 찾았는가","해결 노력을 썼는가","알맞은 약속을 썼는가"]},"explanation":["문제를 찾아요.","노력을 써요.","약속을 써요."],"asset":{"type":"passage","lines":["학교 앞 도로는 아침마다 차가 몰려 길이 막힌다.","스마트폰을 보며 횡단보도를 건너다 깜짝 놀란 친구도 있었다.","새싹반은 교통안전 약속을 함께 정했다."],"title":"신문 ⑤ — 학교 앞 아침 풍경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_b#25','soc',3,2,'u2','','g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C19',4,'essay','teacher','신문 ⑧에서 통신수단을 잘 쓴 모습과 올바르게 쓰지 못한 모습을 하나씩 찾아 쓰고, 새싹반이 지킬 통신 약속을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u2-C19","difficulty":4,"kind":"essay","stem":"신문 ⑧에서 통신수단을 잘 쓴 모습과 올바르게 쓰지 못한 모습을 하나씩 찾아 쓰고, 새싹반이 지킬 통신 약속을 쓰세요.","answer_guide":{"answer":"예: 모바일 메신저로 알림장을 받고 태블릿 컴퓨터로 궁금한 것을 찾는 것은 잘 쓴 모습이에요. 밤늦게까지 스마트폰을 보다 아침에 피곤해한 것은 올바르게 쓰지 못한 모습이에요. 「스마트폰은 정한 시간에만 사용해요」라고 약속할 수 있어요.","scoring_points":["잘 쓴 모습을 찾았는가","올바르게 쓰지 못한 모습을 찾았는가","알맞은 약속을 썼는가"]},"explanation":["잘 쓴 모습이에요.","고칠 모습이에요.","약속을 써요."],"asset":{"type":"passage","lines":["새싹반은 모바일 메신저로 알림장을 받는다.","수업 시간에는 태블릿 컴퓨터로 궁금한 것을 찾는다.","밤늦게까지 스마트폰을 본 친구가 아침에 무척 피곤해했다."],"title":"신문 ⑧ — 새싹반의 통신 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#1','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C1',1,'ox','auto','생일날 미역국을 먹는 것도 풍습이에요.',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"ox","stem":"생일날 미역국을 먹는 것도 풍습이에요.","answer":"O","reason_options":[{"t":"옛날부터 되풀이되어 전해 오는 생활 모습이기 때문에","correct":true},{"t":"풍습은 명절에 하는 일만 말하기 때문에","mis":"SO3-2-u2-X01"}],"mis":"SO3-2-u2-X01","explanation":["옛날부터 해요.","되풀이돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#2','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C3',1,'ox','auto','금줄 치기는 오늘날 사라져 가는 풍습이에요.',ARRAY['SO3-2-u2-X09']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C3","difficulty":1,"kind":"ox","stem":"금줄 치기는 오늘날 사라져 가는 풍습이에요.","answer":"O","reason_options":[{"t":"오늘날 아기가 태어나도 금줄을 치는 집을 거의 볼 수 없기 때문에","correct":true},{"t":"오늘날 모든 집이 금줄을 치기 때문에","mis":"SO3-2-u2-X09"}],"mis":"SO3-2-u2-X09","explanation":["오늘날을 봐요.","거의 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#3','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C5',1,'ox','auto','오늘날에는 농사와 관련 있는 세시 풍속보다 큰 명절을 중심으로 한 세시 풍속이 이어져 와요.',ARRAY['SO3-2-u2-X14']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C5","difficulty":1,"kind":"ox","stem":"오늘날에는 농사와 관련 있는 세시 풍속보다 큰 명절을 중심으로 한 세시 풍속이 이어져 와요.","answer":"O","reason_options":[{"t":"직업이 다양해져 농사짓는 사람이 줄었기 때문에","correct":true},{"t":"오늘날 사람들은 모두 농사를 짓기 때문에","mis":"SO3-2-u2-X14"}],"mis":"SO3-2-u2-X14","explanation":["오늘날 직업을 봐요.","농사짓는 사람이 줄었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#4','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C7',1,'ox','auto','시험을 치르는 사람에게 엿을 주는 풍습에는 합격을 기원하는 마음이 담겨 있어요.',ARRAY['SO3-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C7","difficulty":1,"kind":"ox","stem":"시험을 치르는 사람에게 엿을 주는 풍습에는 합격을 기원하는 마음이 담겨 있어요.","answer":"O","reason_options":[{"t":"시험 점수가 높게 나오고 합격하기를 바라기 때문에","correct":true},{"t":"엿은 더운 여름을 시원하게 보내라는 뜻이기 때문에","mis":"SO3-2-u2-X19"}],"mis":"SO3-2-u2-X19","explanation":["시험이에요.","합격을 빌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#5','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C9',1,'ox','auto','나룻배는 사람이 노를 저어 강의 양쪽을 오갔어요.',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"ox","stem":"나룻배는 사람이 노를 저어 강의 양쪽을 오갔어요.","answer":"O","reason_options":[{"t":"나룻배는 사람의 힘으로 움직였기 때문에","correct":true},{"t":"나룻배는 석유의 힘으로 움직였기 때문에","mis":"SO3-2-u2-X24"}],"mis":"SO3-2-u2-X24","explanation":["노를 저어요.","사람의 힘이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#6','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C12',1,'ox','auto','교통이 변화하면서 교통 체증과 교통사고 같은 문제점도 생겼어요.',ARRAY['SO3-2-u2-X32']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C12","difficulty":1,"kind":"ox","stem":"교통이 변화하면서 교통 체증과 교통사고 같은 문제점도 생겼어요.","answer":"O","reason_options":[{"t":"교통수단이 많아지면서 길이 막히고 사고가 일어나기도 하기 때문에","correct":true},{"t":"교통이 변화하면 문제는 모두 사라지기 때문에","mis":"SO3-2-u2-X32"}],"mis":"SO3-2-u2-X32","explanation":["편리해졌어요.","문제도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#7','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C16',1,'ox','auto','옛날 통신수단은 소식을 전하는 데 시간이 오래 걸렸어요.',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"ox","stem":"옛날 통신수단은 소식을 전하는 데 시간이 오래 걸렸어요.","answer":"O","reason_options":[{"t":"사람이 직접 가거나 말을 타고 가서 전했기 때문에","correct":true},{"t":"옛날에도 소식이 실시간으로 전해졌기 때문에","mis":"SO3-2-u2-X38"}],"mis":"SO3-2-u2-X38","explanation":["직접 갔어요.","오래 걸려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#8','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C19',1,'ox','auto','인터넷에서 다른 사람에게 상처 주는 댓글을 쓰면 안 돼요.',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C19","difficulty":1,"kind":"ox","stem":"인터넷에서 다른 사람에게 상처 주는 댓글을 쓰면 안 돼요.","answer":"O","reason_options":[{"t":"다른 사람의 마음을 아프게 하기 때문에","correct":true},{"t":"댓글은 아무렇게나 써도 되기 때문에","mis":"SO3-2-u2-X43"}],"mis":"SO3-2-u2-X43","explanation":["마음이 아파요.","바른 표현이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#9','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C5',2,'ox','auto','신문 ①의 설날 모습은 옛날과 모두 똑같아요.',ARRAY['SO3-2-u2-X15']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"ox","stem":"신문 ①의 설날 모습은 옛날과 모두 똑같아요.","answer":"X","reason_options":[{"t":"차례·세배처럼 이어지는 모습도 있지만 여행·영화처럼 달라진 모습도 있기 때문에","correct":true},{"t":"오늘날 설날에는 옛날 모습이 하나도 없기 때문에","mis":"SO3-2-u2-X15"}],"mis":"SO3-2-u2-X15","explanation":["두 가지가 섞여 있어요.","달라진 것도 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["새싹반 친구들이 지난 설날에 한 일을 조사했다.","많은 집이 차례를 지내고, 세배를 하고, 떡국을 먹었다.","연휴에 가족 여행을 가거나 영화를 본 집도 있었다."],"title":"신문 ① — 새싹반의 설날 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#10','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C2',2,'ox','auto','신문 ②의 전시물은 일생 동안의 풍습을 태어날 때부터 늙을 때까지 차례대로 놓은 것이에요.',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"ox","stem":"신문 ②의 전시물은 일생 동안의 풍습을 태어날 때부터 늙을 때까지 차례대로 놓은 것이에요.","answer":"O","reason_options":[{"t":"금줄(출생) → 돌잡이(첫돌) → 기러기(혼례) → 회갑 차례이기 때문에","correct":true},{"t":"전시물은 아무렇게나 놓여 있기 때문에","mis":"SO3-2-u2-X05"}],"mis":"SO3-2-u2-X05","explanation":["금줄이 먼저예요.","회갑이 나중이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["새싹반은 옛날 일생 풍습 전시를 보았다.","금줄, 돌잡이 상, 나무 기러기, 회갑 상이 차례대로 놓여 있었다.","안내판에는 「기쁨은 축하하고 슬픔은 위로하며 마음을 나눴어요」라고 적혀 있었다."],"title":"신문 ② — 옛날 일생 풍습 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#11','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C4',2,'ox','auto','신문 ③의 오곡밥과 나물은 정월 대보름의 세시 음식이에요.',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":11,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"ox","stem":"신문 ③의 오곡밥과 나물은 정월 대보름의 세시 음식이에요.","answer":"O","reason_options":[{"t":"정월 대보름에 다섯 가지 곡식으로 만든 밥과 나물을 먹었기 때문에","correct":true},{"t":"오곡밥은 추석에만 먹는 음식이기 때문에","mis":"SO3-2-u2-X11"}],"mis":"SO3-2-u2-X11","explanation":["대보름 음식이에요.","다섯 곡식이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["학교에서 정월 대보름 행사를 열었다.","친구들은 부럼을 깨물고 오곡밥과 나물을 먹었다.","운동장에서는 모둠별로 윷놀이와 제기차기를 했다."],"title":"신문 ③ — 우리 학교 정월 대보름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#12','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C11',2,'ox','auto','신문 ④처럼 교통이 발달하면서 같은 곳에 가는 데 걸리는 시간이 줄었어요.',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":12,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"ox","stem":"신문 ④처럼 교통이 발달하면서 같은 곳에 가는 데 걸리는 시간이 줄었어요.","answer":"O","reason_options":[{"t":"걸어가던 길을 버스로 금방 가기 때문에","correct":true},{"t":"버스는 걷는 것보다 느리기 때문에","mis":"SO3-2-u2-X28"}],"mis":"SO3-2-u2-X28","explanation":["한참 걸었어요.","지금은 금방이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["할아버지는 어릴 때 장에 가려면 한참을 걸어가셨다고 한다.","무거운 짐은 소가 끄는 달구지에 실었다고 한다.","지금은 버스를 타고 금방 가고, 짐은 트럭이 실어 나른다."],"title":"신문 ④ — 할아버지의 어린 시절 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#13','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C12',2,'ox','auto','신문 ⑤의 길 막힘은 막히는 길 정보를 빠르게 알리는 과학적인 교통 관리로 줄일 수 있어요.',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":13,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"ox","stem":"신문 ⑤의 길 막힘은 막히는 길 정보를 빠르게 알리는 과학적인 교통 관리로 줄일 수 있어요.","answer":"O","reason_options":[{"t":"정보를 알면 사람들이 막히는 길을 피해 갈 수 있기 때문에","correct":true},{"t":"길 막힘은 어떤 노력으로도 줄일 수 없기 때문에","mis":"SO3-2-u2-X30"}],"mis":"SO3-2-u2-X30","explanation":["정보를 알려요.","다른 길로 가요.","그래서 O예요."],"asset":{"type":"passage","lines":["학교 앞 도로는 아침마다 차가 몰려 길이 막힌다.","스마트폰을 보며 횡단보도를 건너다 깜짝 놀란 친구도 있었다.","새싹반은 교통안전 약속을 함께 정했다."],"title":"신문 ⑤ — 학교 앞 아침 풍경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#14','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C13',2,'ox','auto','신문 ⑥의 그림은 미래 교통이 발전하는 방향과 잘 맞아요.',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":14,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"ox","stem":"신문 ⑥의 그림은 미래 교통이 발전하는 방향과 잘 맞아요.","answer":"O","reason_options":[{"t":"빠르고 안전하며 환경을 지키는 방향으로 발전하고 있기 때문에","correct":true},{"t":"미래 교통은 빠르기만 하면 되기 때문에","mis":"SO3-2-u2-X34"}],"mis":"SO3-2-u2-X34","explanation":["빠르고 안전해요.","환경도 지켜요.","그래서 O예요."],"asset":{"type":"passage","lines":["새싹반 친구들이 미래 교통수단을 그렸다.","사람이 운전하지 않아도 스스로 달리는 자동차, 하늘로 다니는 택시가 많았다.","친구들은 빠르면서도 안전하고 환경을 지키는 모습을 그렸다."],"title":"신문 ⑥ — 우리가 그린 미래 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#15','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C16',2,'ox','auto','신문 ⑦의 내용은 옛날 통신수단이 날씨의 영향을 많이 받았다는 것을 보여 줘요.',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":15,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"ox","stem":"신문 ⑦의 내용은 옛날 통신수단이 날씨의 영향을 많이 받았다는 것을 보여 줘요.","answer":"O","reason_options":[{"t":"안개 때문에 봉수를 쓸 수 없는 날이 있었기 때문에","correct":true},{"t":"옛날 통신수단은 날씨와 관계가 없었기 때문에","mis":"SO3-2-u2-X38"}],"mis":"SO3-2-u2-X38","explanation":["안개 낀 날이에요.","봉수가 안 보여요.","그래서 O예요."],"asset":{"type":"passage","lines":["새싹반은 옛날 통신수단 전시를 보았다.","봉수대 모형에는 연기 구멍이 다섯 개 있었다.","안내판에는 「안개 낀 날에는 봉수 대신 파발을 보냈어요」라고 적혀 있었다."],"title":"신문 ⑦ — 옛날 통신수단 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#16','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C18',2,'ox','auto','신문 ⑧처럼 태블릿 컴퓨터로 궁금한 것을 바로 찾는 것은 통신수단의 발달로 달라진 생활 모습이에요.',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":16,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"ox","stem":"신문 ⑧처럼 태블릿 컴퓨터로 궁금한 것을 바로 찾는 것은 통신수단의 발달로 달라진 생활 모습이에요.","answer":"O","reason_options":[{"t":"언제 어디서나 필요한 정보를 쉽고 빠르게 얻게 되었기 때문에","correct":true},{"t":"태블릿 컴퓨터는 옛날부터 있던 통신수단이기 때문에","mis":"SO3-2-u2-X41"}],"mis":"SO3-2-u2-X41","explanation":["바로 찾아요.","쉽고 빨라요.","그래서 O예요."],"asset":{"type":"passage","lines":["새싹반은 모바일 메신저로 알림장을 받는다.","수업 시간에는 태블릿 컴퓨터로 궁금한 것을 찾는다.","밤늦게까지 스마트폰을 본 친구가 아침에 무척 피곤해했다."],"title":"신문 ⑧ — 새싹반의 통신 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#17','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C3',3,'ox','auto','폐백과 회갑잔치는 모습을 바꾸어 오늘날까지 이어져 내려오는 풍습이에요.',ARRAY['SO3-2-u2-X09']::text[],false,'{"seq":17,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"ox","stem":"폐백과 회갑잔치는 모습을 바꾸어 오늘날까지 이어져 내려오는 풍습이에요.","answer":"O","reason_options":[{"t":"오늘날에도 결혼식 뒤 폐백을 하고 회갑잔치를 하기 때문에","correct":true},{"t":"폐백과 회갑잔치는 이미 사라졌기 때문에","mis":"SO3-2-u2-X09"}],"mis":"SO3-2-u2-X09","explanation":["이어지는 풍습이에요.","오늘날에도 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#18','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C4',3,'ox','auto','단오에는 창포 삶은 물에 머리를 감으며 건강을 빌었어요.',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":18,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"ox","stem":"단오에는 창포 삶은 물에 머리를 감으며 건강을 빌었어요.","answer":"O","reason_options":[{"t":"더운 여름을 맞기 전에 건강을 기원했기 때문에","correct":true},{"t":"단오는 겨울 명절이기 때문에","mis":"SO3-2-u2-X11"}],"mis":"SO3-2-u2-X11","explanation":["여름이 오기 전이에요.","건강을 빌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#19','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C11',3,'ox','auto','교통이 발달하면서 세계 여러 곳에서 만든 물건을 쉽게 구할 수 있게 됐어요.',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":19,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"ox","stem":"교통이 발달하면서 세계 여러 곳에서 만든 물건을 쉽게 구할 수 있게 됐어요.","answer":"O","reason_options":[{"t":"먼 곳의 물건도 빠르고 많이 실어 나를 수 있게 됐기 때문에","correct":true},{"t":"교통이 발달하면 물건을 옮기기 어려워지기 때문에","mis":"SO3-2-u2-X28"}],"mis":"SO3-2-u2-X28","explanation":["멀리서 와요.","많이 실어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#20','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C14',3,'ox','auto','교통의 변화는 편리함만 주고 문제는 남기지 않았어요.',ARRAY['SO3-2-u2-X32']::text[],false,'{"seq":20,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"ox","stem":"교통의 변화는 편리함만 주고 문제는 남기지 않았어요.","answer":"X","reason_options":[{"t":"교통 체증, 사고, 환경 문제가 생겨 지금도 해결하려고 노력하기 때문에","correct":true},{"t":"교통의 변화로 생긴 문제는 하나도 없기 때문에","mis":"SO3-2-u2-X32"}],"mis":"SO3-2-u2-X32","explanation":["문제도 있어요.","노력하고 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#21','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C17',3,'ox','auto','오늘날 통신수단으로 여러 사람과 동시에 많은 정보를 주고받을 수 있어요.',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":21,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"ox","stem":"오늘날 통신수단으로 여러 사람과 동시에 많은 정보를 주고받을 수 있어요.","answer":"O","reason_options":[{"t":"모바일 메신저처럼 여러 사람에게 한 번에 실시간으로 전할 수 있기 때문에","correct":true},{"t":"오늘날 통신수단은 한 사람에게만 소식을 전하기 때문에","mis":"SO3-2-u2-X38"}],"mis":"SO3-2-u2-X38","explanation":["여러 사람이에요.","동시에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#22','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C20',3,'ox','auto','통신수단이 변화해도 사람들이 정보를 찾거나 의사소통하는 방식은 옛날과 같아요.',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":22,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"ox","stem":"통신수단이 변화해도 사람들이 정보를 찾거나 의사소통하는 방식은 옛날과 같아요.","answer":"X","reason_options":[{"t":"휴대 전화, 인터넷으로 정보를 찾고 의사소통하는 방식이 달라졌기 때문에","correct":true},{"t":"정보를 찾는 방식은 바뀌지 않기 때문에","mis":"SO3-2-u2-X44"}],"mis":"SO3-2-u2-X44","explanation":["방식이 바뀌었어요.","인터넷이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#23','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C4',4,'essay','teacher','신문 ③의 정월 대보름 행사에서 세시 풍속을 두 가지 찾아 쓰고, 그 속에 담긴 옛날 사람들의 바람을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-2-u2-C4","difficulty":4,"kind":"essay","stem":"신문 ③의 정월 대보름 행사에서 세시 풍속을 두 가지 찾아 쓰고, 그 속에 담긴 옛날 사람들의 바람을 쓰세요.","answer_guide":{"answer":"예: 부럼을 깨무는 것과 오곡밥과 나물을 먹는 것이 정월 대보름의 세시 풍속이에요. 옛날 사람들은 부럼을 깨물며 이가 튼튼해지고 피부병이 생기지 않기를 빌었어요. 새해 첫 보름달에 소원을 빌고 풍년을 기원했어요.","scoring_points":["세시 풍속을 두 가지 찾았는가","정월 대보름과 바르게 이었는가","담긴 바람을 썼는가"]},"explanation":["부럼을 찾아요.","오곡밥도요.","바람을 써요."],"asset":{"type":"passage","lines":["학교에서 정월 대보름 행사를 열었다.","친구들은 부럼을 깨물고 오곡밥과 나물을 먹었다.","운동장에서는 모둠별로 윷놀이와 제기차기를 했다."],"title":"신문 ③ — 우리 학교 정월 대보름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#24','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C13',4,'essay','teacher','신문 ⑥의 미래 교통수단 가운데 하나를 골라 특징을 쓰고, 그 교통수단이 미래 교통이 발전하는 방향과 어떻게 맞는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u2-C13","difficulty":4,"kind":"essay","stem":"신문 ⑥의 미래 교통수단 가운데 하나를 골라 특징을 쓰고, 그 교통수단이 미래 교통이 발전하는 방향과 어떻게 맞는지 쓰세요.","answer_guide":{"answer":"예: 하늘로 다니는 택시는 땅의 도로가 아니라 하늘을 교통로로 삼아요. 땅에서와 같은 교통 혼잡을 일으키지 않아 빠르고, 친환경 에너지로 움직여 공해와 소음이 적어요. 빠르고 환경을 보호하는 방향과 잘 맞아요.","scoring_points":["교통수단을 하나 골랐는가","특징을 썼는가","발전 방향과 이었는가"]},"explanation":["하나를 골라요.","특징을 써요.","방향과 이어요."],"asset":{"type":"passage","lines":["새싹반 친구들이 미래 교통수단을 그렸다.","사람이 운전하지 않아도 스스로 달리는 자동차, 하늘로 다니는 택시가 많았다.","친구들은 빠르면서도 안전하고 환경을 지키는 모습을 그렸다."],"title":"신문 ⑥ — 우리가 그린 미래 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_c#25','soc',3,2,'u2','','g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C18',4,'essay','teacher','전화기가 초기의 전화기에서 오늘날의 휴대 전화까지 바뀌어 온 모습을 두 단계 이상 쓰고, 그에 따라 사람들의 생활이 어떻게 달라졌는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u2-C18","difficulty":4,"kind":"essay","stem":"전화기가 초기의 전화기에서 오늘날의 휴대 전화까지 바뀌어 온 모습을 두 단계 이상 쓰고, 그에 따라 사람들의 생활이 어떻게 달라졌는지 쓰세요.","answer_guide":{"answer":"예: 초기의 전화기는 교환원이 연결해 줬고, 유선 전화는 전화기가 있는 곳으로 가야 통화할 수 있었어요. 휴대 전화가 생기며 들고 다니며 통화하고, 오늘날에는 사진 촬영과 은행 거래도 해요. 그래서 언제 어디서나 쉽게 연락하고 직접 가지 않아도 일을 볼 수 있게 됐어요.","scoring_points":["변화 단계를 두 개 이상 썼는가","차례가 바른가","달라진 생활을 썼는가"]},"explanation":["초기부터 써요.","차례대로 써요.","생활을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#1','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C1',1,'mc','auto','설을 맞이해 새로 마련해 입는 옷이나 신발을 무엇이라고 하나요?',ARRAY['SO3-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"mc","stem":"설을 맞이해 새로 마련해 입는 옷이나 신발을 무엇이라고 하나요?","options":[{"t":"설빔","correct":true},{"t":"덕담","mis":"SO3-2-u2-X03"},{"t":"차례","mis":"SO3-2-u2-X03"},{"t":"세배","mis":"SO3-2-u2-X03"}],"explanation":["새 옷이에요.","설에 입어요.","설빔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#2','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C2',1,'mc','auto','부모님이 60년 동안 건강하게 사신 것을 축하하는 잔치는 무엇인가요?',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"mc","stem":"부모님이 60년 동안 건강하게 사신 것을 축하하는 잔치는 무엇인가요?","options":[{"t":"회갑","correct":true},{"t":"백일","mis":"SO3-2-u2-X05"},{"t":"관례","mis":"SO3-2-u2-X05"},{"t":"돌잔치","mis":"SO3-2-u2-X05"}],"explanation":["60년이에요.","환갑이라고도 해요.","회갑이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#3','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C4',1,'mc','auto','붉은팥이 나쁜 기운을 쫓는다고 여겨 팥죽을 먹은 날은 언제인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"mc","stem":"붉은팥이 나쁜 기운을 쫓는다고 여겨 팥죽을 먹은 날은 언제인가요?","options":[{"t":"동지","correct":true},{"t":"설날","mis":"SO3-2-u2-X11"},{"t":"추석","mis":"SO3-2-u2-X11"},{"t":"단오","mis":"SO3-2-u2-X11"}],"explanation":["밤이 가장 길어요.","작은 설이에요.","동지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
