INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#5','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C8',1,'mc','auto','지하철이 다니는 교통로는 무엇인가요?',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C8","difficulty":1,"kind":"mc","stem":"지하철이 다니는 교통로는 무엇인가요?","options":[{"t":"철도","correct":true},{"t":"수로","mis":"SO3-2-u2-X21"},{"t":"항공로","mis":"SO3-2-u2-X21"},{"t":"자전거 도로","mis":"SO3-2-u2-X21"}],"explanation":["레일 위를 달려요.","열차의 길이에요.","철도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#6','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C13',1,'mc','auto','스스로 목적지까지 운항하는 미래 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C13","difficulty":1,"kind":"mc","stem":"스스로 목적지까지 운항하는 미래 교통수단은 무엇인가요?","options":[{"t":"자율 운항 선박","correct":true},{"t":"자율 주행 휠체어","mis":"SO3-2-u2-X33"},{"t":"착용하는 로봇","mis":"SO3-2-u2-X33"},{"t":"달구지","mis":"SO3-2-u2-X33"}],"explanation":["배예요.","스스로 가요.","자율 운항 선박이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#7','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C16',1,'mc','auto','나라의 중요한 소식을 사람들이 많이 모이는 곳에 글로 써 붙인 것은 무엇인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"mc","stem":"나라의 중요한 소식을 사람들이 많이 모이는 곳에 글로 써 붙인 것은 무엇인가요?","options":[{"t":"방","correct":true},{"t":"서찰","mis":"SO3-2-u2-X37"},{"t":"봉수","mis":"SO3-2-u2-X37"},{"t":"신호 연","mis":"SO3-2-u2-X37"}],"explanation":["붙였어요.","여러 사람이 봐요.","방이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#8','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C18',1,'mc','auto','오늘날 휴대 전화로 할 수 있는 일로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X40','SO3-2-u2-X38']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C18","difficulty":1,"kind":"mc","stem":"오늘날 휴대 전화로 할 수 있는 일로 알맞은 것은 무엇인가요?","options":[{"t":"사진 촬영과 은행 거래","correct":true},{"t":"교환원 부르기","mis":"SO3-2-u2-X40"},{"t":"봉수 올리기","mis":"SO3-2-u2-X38"},{"t":"전화선 꽂기","mis":"SO3-2-u2-X40"}],"explanation":["여러 기능이 있어요.","사진도 찍어요.","촬영과 은행 거래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#9','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C5',2,'mc','auto','신문 ①의 여러 집 설날 모습에서 공통으로 찾을 수 있는 변함없는 마음은 무엇인가요?',ARRAY['SO3-2-u2-X13','SO3-2-u2-X16']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"mc","stem":"신문 ①의 여러 집 설날 모습에서 공통으로 찾을 수 있는 변함없는 마음은 무엇인가요?","options":[{"t":"가족과 함께 기쁨을 나누는 마음","correct":true},{"t":"농사의 풍년을 비는 마음","mis":"SO3-2-u2-X13"},{"t":"혼자 쉬려는 마음","mis":"SO3-2-u2-X16"},{"t":"옛것을 버리려는 마음","mis":"SO3-2-u2-X16"}],"explanation":["가족이 모여요.","함께해요.","기쁨을 나눠요."],"asset":{"type":"passage","lines":["새싹반 친구들이 지난 설날에 한 일을 조사했다.","많은 집이 차례를 지내고, 세배를 하고, 떡국을 먹었다.","연휴에 가족 여행을 가거나 영화를 본 집도 있었다."],"title":"신문 ① — 새싹반의 설날 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#10','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C2',2,'mc','auto','신문 ② 안내판의 글로 알 수 있는 옛날 사람들의 마음은 무엇인가요?',ARRAY['SO3-2-u2-X06']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"mc","stem":"신문 ② 안내판의 글로 알 수 있는 옛날 사람들의 마음은 무엇인가요?","options":[{"t":"중요한 일이 있을 때 서로 축하하고 위로하며 마음을 나눴어요","correct":true},{"t":"기쁜 일만 혼자 즐겼어요","mis":"SO3-2-u2-X06"},{"t":"슬픈 일은 모른 척했어요","mis":"SO3-2-u2-X06"},{"t":"풍습에는 마음이 담겨 있지 않아요","mis":"SO3-2-u2-X06"}],"explanation":["축하와 위로예요.","함께 나눴어요.","마음을 나눴어요."],"asset":{"type":"passage","lines":["새싹반은 옛날 일생 풍습 전시를 보았다.","금줄, 돌잡이 상, 나무 기러기, 회갑 상이 차례대로 놓여 있었다.","안내판에는 「기쁨은 축하하고 슬픔은 위로하며 마음을 나눴어요」라고 적혀 있었다."],"title":"신문 ② — 옛날 일생 풍습 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#11','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C7',2,'mc','auto','신문 ③의 행사로 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X02','SO3-2-u2-X18','SO3-2-u2-X11']::text[],false,'{"seq":11,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"mc","stem":"신문 ③의 행사로 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"옛날 세시 풍속과 전통 놀이가 오늘날까지 전해 내려와요","correct":true},{"t":"옛날 풍습은 오늘날 모두 사라졌어요","mis":"SO3-2-u2-X02"},{"t":"전통 놀이는 혼자서만 해요","mis":"SO3-2-u2-X18"},{"t":"정월 대보름에는 송편을 먹어요","mis":"SO3-2-u2-X11"}],"explanation":["학교에서 했어요.","오늘날에도 해요.","전해 내려와요."],"asset":{"type":"passage","lines":["학교에서 정월 대보름 행사를 열었다.","친구들은 부럼을 깨물고 오곡밥과 나물을 먹었다.","운동장에서는 모둠별로 윷놀이와 제기차기를 했다."],"title":"신문 ③ — 우리 학교 정월 대보름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#12','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C10',2,'mc','auto','신문 ④의 버스와 트럭은 대부분 무엇을 연료로 사용하나요?',ARRAY['SO3-2-u2-X25']::text[],false,'{"seq":12,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"mc","stem":"신문 ④의 버스와 트럭은 대부분 무엇을 연료로 사용하나요?","options":[{"t":"석유, 가스, 전기","correct":true},{"t":"사람의 힘","mis":"SO3-2-u2-X25"},{"t":"동물의 힘","mis":"SO3-2-u2-X25"},{"t":"바람의 힘","mis":"SO3-2-u2-X25"}],"explanation":["기계예요.","연료가 필요해요.","석유·가스·전기예요."],"asset":{"type":"passage","lines":["할아버지는 어릴 때 장에 가려면 한참을 걸어가셨다고 한다.","무거운 짐은 소가 끄는 달구지에 실었다고 한다.","지금은 버스를 타고 금방 가고, 짐은 트럭이 실어 나른다."],"title":"신문 ④ — 할아버지의 어린 시절 길"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#13','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C12',2,'mc','auto','신문 ⑤의 학교 앞이 어린이 보호 구역이라면 자동차가 지킬 일은 무엇인가요?',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":13,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"mc","stem":"신문 ⑤의 학교 앞이 어린이 보호 구역이라면 자동차가 지킬 일은 무엇인가요?","options":[{"t":"천천히 가요","correct":true},{"t":"경적을 계속 울려요","mis":"SO3-2-u2-X31"},{"t":"더 빨리 지나가요","mis":"SO3-2-u2-X31"},{"t":"길가에 오래 세워 둬요","mis":"SO3-2-u2-X31"}],"explanation":["어린이가 많아요.","사고를 막아요.","천천히 가요."],"asset":{"type":"passage","lines":["학교 앞 도로는 아침마다 차가 몰려 길이 막힌다.","스마트폰을 보며 횡단보도를 건너다 깜짝 놀란 친구도 있었다.","새싹반은 교통안전 약속을 함께 정했다."],"title":"신문 ⑤ — 학교 앞 아침 풍경"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#14','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C13',2,'mc','auto','신문 ⑥의 하늘을 다니는 택시가 많아지면 새로 생길 수 있는 직업은 무엇인가요?',ARRAY['SO3-2-u2-X29','SO3-2-u2-X41']::text[],false,'{"seq":14,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"mc","stem":"신문 ⑥의 하늘을 다니는 택시가 많아지면 새로 생길 수 있는 직업은 무엇인가요?","options":[{"t":"도심 항공 관제사","correct":true},{"t":"가마꾼","mis":"SO3-2-u2-X29"},{"t":"뱃사공","mis":"SO3-2-u2-X29"},{"t":"교환원","mis":"SO3-2-u2-X41"}],"explanation":["하늘을 안내해요.","도심이에요.","도심 항공 관제사예요."],"asset":{"type":"passage","lines":["새싹반 친구들이 미래 교통수단을 그렸다.","사람이 운전하지 않아도 스스로 달리는 자동차, 하늘로 다니는 택시가 많았다.","친구들은 빠르면서도 안전하고 환경을 지키는 모습을 그렸다."],"title":"신문 ⑥ — 우리가 그린 미래 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#15','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C16',2,'mc','auto','신문 ⑦의 파발은 어떻게 소식을 전했나요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":15,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"mc","stem":"신문 ⑦의 파발은 어떻게 소식을 전했나요?","options":[{"t":"나라의 중요한 문서를 말을 타거나 걸어가서 전했어요","correct":true},{"t":"연기를 피워 알렸어요","mis":"SO3-2-u2-X37"},{"t":"글을 써서 길거리에 붙였어요","mis":"SO3-2-u2-X37"},{"t":"연을 띄워 알렸어요","mis":"SO3-2-u2-X37"}],"explanation":["말을 타요.","문서를 들고 가요.","직접 전했어요."],"asset":{"type":"passage","lines":["새싹반은 옛날 통신수단 전시를 보았다.","봉수대 모형에는 연기 구멍이 다섯 개 있었다.","안내판에는 「안개 낀 날에는 봉수 대신 파발을 보냈어요」라고 적혀 있었다."],"title":"신문 ⑦ — 옛날 통신수단 전시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#16','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C19',2,'mc','auto','신문 ⑧의 친구처럼 스마트폰을 지나치게 쓰면 생길 수 있는 문제는 무엇인가요?',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":16,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"mc","stem":"신문 ⑧의 친구처럼 스마트폰을 지나치게 쓰면 생길 수 있는 문제는 무엇인가요?","options":[{"t":"몸과 마음의 건강을 해칠 수 있어요","correct":true},{"t":"공부를 더 잘하게 돼요","mis":"SO3-2-u2-X42"},{"t":"잠을 더 푹 자요","mis":"SO3-2-u2-X42"},{"t":"아무 문제도 없어요","mis":"SO3-2-u2-X42"}],"explanation":["피곤해했어요.","건강이에요.","해칠 수 있어요."],"asset":{"type":"passage","lines":["새싹반은 모바일 메신저로 알림장을 받는다.","수업 시간에는 태블릿 컴퓨터로 궁금한 것을 찾는다.","밤늦게까지 스마트폰을 본 친구가 아침에 무척 피곤해했다."],"title":"신문 ⑧ — 새싹반의 통신 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#17','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C7',3,'error','auto','풍습 공부를 되돌아보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X06','SO3-2-u2-X02']::text[],false,'{"seq":17,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"error","stem":"풍습 공부를 되돌아보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「옛날 풍습은 오늘날 우리 생활과 아무 관계가 없어.」","correct":true,"mis_target":"SO3-2-u2-X44"},{"t":"친구 가 — 「풍습에는 옛날 사람들의 생각이 담겨 있어.」","mis":"SO3-2-u2-X06"},{"t":"친구 다 — 「떡국 먹기는 오늘날까지 이어져.」","mis":"SO3-2-u2-X02"}],"explanation":["관계가 있어요.","이어져요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#18','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C4',3,'error','auto','명절과 음식을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":18,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"error","stem":"명절과 음식을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「단오에는 팥죽을 먹었어.」","correct":true,"mis_target":"SO3-2-u2-X11"},{"t":"친구 가 — 「추석에는 송편을 먹었어.」","mis":"SO3-2-u2-X11"},{"t":"친구 나 — 「정월 대보름에는 오곡밥을 먹었어.」","mis":"SO3-2-u2-X11"}],"explanation":["단오 음식을 봐요.","수리취떡이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#19','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C9',3,'error','auto','교통수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X24','SO3-2-u2-X25','SO3-2-u2-X23']::text[],false,'{"seq":19,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"error","stem":"교통수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「달구지는 기계의 힘을 이용한 교통수단이야.」","correct":true,"mis_target":"SO3-2-u2-X24"},{"t":"친구 나 — 「증기 기차는 수증기의 힘으로 움직여.」","mis":"SO3-2-u2-X25"},{"t":"친구 다 — 「가마는 가마꾼이 들어 옮겼어.」","mis":"SO3-2-u2-X23"}],"explanation":["달구지를 봐요.","소나 말이 끌어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#20','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C13',3,'error','auto','앞으로의 교통을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X34','SO3-2-u2-X33']::text[],false,'{"seq":20,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"error","stem":"앞으로의 교통을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「미래에는 교통수단이 줄고 생활도 지금과 똑같을 거야.」","correct":true,"mis_target":"SO3-2-u2-X34"},{"t":"친구 가 — 「자율 주행 휠체어는 환자의 이동을 도와.」","mis":"SO3-2-u2-X33"},{"t":"친구 나 — 「우주선으로 우주여행을 할 수 있어.」","mis":"SO3-2-u2-X33"}],"explanation":["미래를 봐요.","달라질 거예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#21','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C18',3,'error','auto','통신수단의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":21,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"error","stem":"통신수단의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「통신수단이 발달하면서 교환원이라는 직업이 새로 생겼어.」","correct":true,"mis_target":"SO3-2-u2-X41"},{"t":"친구 가 — 「기지국을 설치하는 통신 설비 기술자가 생겼어.」","mis":"SO3-2-u2-X41"},{"t":"친구 다 — 「무선 호출기는 점차 사라지고 있어.」","mis":"SO3-2-u2-X41"}],"explanation":["교환원을 봐요.","사라졌어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#22','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C14',3,'error','auto','단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X01','SO3-2-u2-X28','SO3-2-u2-X42']::text[],false,'{"seq":22,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"error","stem":"단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「세시 풍속은 절기나 계절과 관계없이 아무 때나 즐기는 풍습이야.」","correct":true,"mis_target":"SO3-2-u2-X01"},{"t":"친구 나 — 「교통의 발달로 생활 공간이 넓어졌어.」","mis":"SO3-2-u2-X28"},{"t":"친구 다 — 「통신수단은 몸과 마음의 건강을 위해 올바르게 써야 해.」","mis":"SO3-2-u2-X42"}],"explanation":["세시 풍속을 봐요.","해마다 일정한 때예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#23','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C6',4,'essay','teacher','옛날부터 오늘날까지 전해 내려오는 풍습이나 전통 놀이 하나를 골라 소개하고, 그것을 미래에도 이어 가려면 어떻게 하면 좋을지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-2-u2-C6","difficulty":4,"kind":"essay","stem":"옛날부터 오늘날까지 전해 내려오는 풍습이나 전통 놀이 하나를 골라 소개하고, 그것을 미래에도 이어 가려면 어떻게 하면 좋을지 쓰세요.","answer_guide":{"answer":"예: 설날에 복주머니를 차는 풍습은 복이 들어오기를 바라는 뜻이 담겨 있어요. 오늘날에도 복주머니를 선물해요. 미래에도 이어 가려면 학교에서 복주머니를 직접 만들어 보고 가족에게 선물하면 좋겠어요.","scoring_points":["풍습이나 놀이를 하나 골랐는가","바르게 소개했는가","이어 갈 방법을 썼는가"]},"explanation":["하나를 골라요.","소개해요.","방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#24','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C14',4,'essay','teacher','교통의 변화로 좋아진 점과 생긴 문제점을 하나씩 쓰고, 문제점을 줄이기 위해 내가 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u2-C14","difficulty":4,"kind":"essay","stem":"교통의 변화로 좋아진 점과 생긴 문제점을 하나씩 쓰고, 문제점을 줄이기 위해 내가 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 교통이 발달해 먼 곳에 사는 친척 집에도 반나절이면 갈 수 있게 됐어요. 하지만 자동차가 많아져 대기 오염이 생겼어요. 나는 가까운 곳은 걷거나 자전거를 타고, 먼 곳은 대중교통을 이용하겠어요.","scoring_points":["좋아진 점을 썼는가","문제점을 썼는가","내가 할 수 있는 일을 썼는가"]},"explanation":["좋아진 점이에요.","문제점이에요.","내 일을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_soc_u2_review_d#25','soc',3,2,'u2','','g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C20',4,'essay','teacher','「옛날과 오늘날의 생활 모습」 단원에서 새로 알게 된 점이나 느낀 점을 풍습, 교통, 통신 가운데 두 가지 이상과 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u2-C20","difficulty":4,"kind":"essay","stem":"「옛날과 오늘날의 생활 모습」 단원에서 새로 알게 된 점이나 느낀 점을 풍습, 교통, 통신 가운데 두 가지 이상과 이어 쓰세요.","answer_guide":{"answer":"예: 옛날부터 이어져 온 풍습에 가족의 건강과 복을 바라는 조상들의 마음이 담겨 있다는 것을 알게 됐어요. 교통이 발달해서 먼 곳도 빠르게 갈 수 있게 된 것이 신기했어요. 앞으로 통신수단을 안전하고 올바르게 쓰는 사람이 되고 싶어요.","scoring_points":["두 가지 이상과 이었는가","알게 된 점이나 느낀 점을 썼는가","옛날과 오늘날의 변화가 드러났는가"]},"explanation":["두 가지를 골라요.","알게 된 점이에요.","느낀 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
